(window.GIM_TS=window.GIM_TS||{})["Shabbat.0"]={"from":0,"a":[["\u0003יציאות,\u0004 (הוצאות) מרשות לרשות האסורות ביום \u0003השבת,\u0004 הרי הן בעיקרו של דבר \u0003שתים שהן ארבע בפנים,\u0004 שיש שתי פעולות יסודיות השייכות באדם הנמצא בפנים, ברשות היחיד, והן מתחלקות בפרטיהן לארבעה מקרים, \u0003ו\u0004כן \u0003שתים שהן ארבע בחוץ.\u0004","ומבררים: \u0003כיצד\u0004 הם המקרים עליהם מדובר?","— \u0003העני עומד בחוץ\u0004 ברחוב רשות הרבים, \u0003ובעל הבית עומד בפנים,\u0004 ברשות היחיד. מקרה ראשון: \u0003פשט\u0004 (הושיט) \u0003העני את ידו לפנים\u0004 רשות היחיד כשבידו חפץ שנטלו מרשות הרבים בה הוא עומד, \u0003ונתן\u0004 את החפץ \u0003לתוך ידו של בעל הבית\u0004 הנמצא ברשות היחיד — הרי שעשה בכך מלאכה של הוצאה מרשות הרבים לרשות היחיד. \u0003או שנטל מתוכה\u0004 מתוך ידו של בעל הבית דבר מה \u0003והוציא\u0004 אותו לחוץ, שבמקרה זה עשה מלאכה של הוצאה מרשות היחיד לרשות הרבים, ובשני המקרים הללו העני הוא שעשה את המלאכה בשלימותה, ועל כן \u0003העני חייב ובעל הבית פטור.\u0004","מקרה אחר של הוצאה והכנסה הנעשה מתוך רשות היחיד מבואר, כאשר \u0003פשט בעל הבית את ידו לחוץ,\u0004 לרשות הרבים, כשבידו חפץ שנטל מרשות היחיד\u0003, ונתן\u0004 את החפץ \u0003לתוך ידו של\u0004 ה\u0003עני\u0004 הנמצא ברשות הרבים — הרי שהוציא חפץ מרשות היחיד לרשות הרבים. \u0003או שנטל\u0004 בעל הבית חפץ \u0003מתוכה\u0004 של יד העני הנמצא ברשות הרבים, \u0003והכניס\u0004 אותו אליו לרשות היחיד, במקרים אלה רק בעל הבית הוא שעשה את מלאכת ההוצאה, ולכן \u0003בעל הבית חייב והעני פטור.\u0004 אלה הם אופני ההוצאה וההכנסה בפנים ובחוץ האסורות מן התורה, שהעושה אותן חייב.","בארבעה מקרים אחרים המובאים כאן לא נעשתה מלאכה שלימה על ידי אף אחד מן האנשים המעורבים במלאכה, וכגון: \u0003פשט העני\u0004 הנמצא ברשות הרבים \u0003את ידו\u0004 כשבתוכה חפץ שעקר ממקומו ברשות הרבים \u0003לפנים, ונטל בעל הבית\u0004 את החפץ \u0003מתוכה\u0004 והניחו בתוך הבית, ברשות היחיד, הרי שפעולת ההכנסה נעשתה על ידי שני האנשים, וכל אחד מהם עשה חצי מלאכה, \u0003או שנתן\u0004 בעל הבית חפץ \u0003לתוכה,\u0004 לתוך ידו של העני המצויה בתוך הבית, \u0003ו\u0004העני \u0003הוציא\u0004 את החפץ והעבירו לרשות הרבים — אמנם נעשתה כאן מלאכת הוצאה ואולם מאחר שלא עשאה אדם אחד בשלימותה לכן במקרים כגון אלה \u0003שניהם פטורין. וכן אם\u0004","\u0003פשט בעל הבית את ידו לחוץ,\u0004 לרשות הרבים ובה חפץ שעקר מרשות היחיד, \u0003ונטל העני\u0004 את החפץ \u0003מתוכה\u0004 והניחו ברשות הרבים, \u0003או שנתן העני\u0004 חפץ \u0003לתוכה,\u0004 לתוך יד בעל הבית, \u0003והכניס\u0004 בעל הבית את החפץ לרשות היחיד — \u0003שניהם פטורין,\u0004 שכל אחד מהם לא עשה אלא חצי מלאכה.","שנינו במשנתנו \"יציאות השבת שתים שהן ארבע\", ובדומה לכך \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת שבועות: \u0003שבועות\u0004 שחייב אדם בקרבן אם הפירן, הרי הן \u0003שתים שהן ארבע,\u0004 האחת, אם נשבע אדם שיעשה בעתיד פעולה מסויימת, והאחרת, שיימנע מלעשותה — הרי שתים מהן מפורשות בתורה, וכן יש להוסיף מריבוי בלשון המקרא עוד שתיים: אם נשבע אדם שעשה כבר פעולה ידועה, או שלא עשאה."],["\u0003ידיעות הטומאה שתים שהן ארבע.\u0004 שיש איסור חמור שיגע אדם טמא בדבר מקודש. ואולם כדי שיתחייב הנוגע בהבאת קרבן על חטא זה שחטא, דרוש שתהיה לו ידיעה ברורה לפני המעשה ולאחריו. שני הסוגים הפשוטים של שגגה בנושא זה הם: האחד, כששכח אדם שנטמא ואחר כך אכל בשר קודש (של קרבן), ולאחר מכן נזכר שוב שהוא טמא, ומקרה אחר — שידע שהוא טמא ושכח ונכנס לבית המקדש, ונזכר שוב לאחר מכן שהוא טמא. על שני מקרים אלה אפשר להוסיף עוד שניים: כשזכר בשעת האכילה שהוא טמא, אלא ששכח שהדבר שהוא אוכל הוא בשר קודש, או ששכח בשעת האכילה שהוא עומד להכנס למקדש.","וכן לגבי \u0003מראות נגעים\u0004 (בצרעת) הריהם \u0003שנים שהם ארבעה.\u0004 שכן בתורה (ויקרא פרק י\"ג) מוזכרים שני סוגי מראות: הבהרת והשאת. והוסיפו עליהם גם תולדות — נגעים שאינם לבנים כמו הנגע המוגדר בתורה, ויש תוספת לנגע הבהרת וגם לנגע השאת.","וכן נזכר שם ש\u0003יציאות השבת\u0004 הן \u0003שתים שהן ארבע.\u0004","ושואלים: \u0003מאי שנא הכא\u0004 \u0005[במה שונה כאן]\u0006 במשנתנו שנאמר בה בלשון \u0003\"שתים שהן ארבע בפנים ושתים שהן ארבע בחוץ\", ומאי שנא התם\u0004 \u0005[ובמה שונה שם]\u0006 במסכת שבועות שנאמר שם בדין הוצאות בשבת בלשון \u0003\"שתים שהן ארבע\" ותו לא\u0004 \u0005[ולא עוד]?\u0006","ומשיבים: \u0003הכא\u0004 \u0005[כאן]\u0006 במסכת שבת שב\u0003עיקר שבת הוא\u0004 עוסק, על כן \u0003תני\u0004 \u0005[שנה]\u0006 \u0003אבות\u0004 מלאכה, שהם ההוצאות מרשות לרשות, \u0003ותני\u0004 \u0005[ושנה]\u0006 גם את ה\u0003תולדות\u0004 של המלאכה, שהן ההכנסות מרשות אחת לחבירתה. ואילו \u0003התם\u0004 \u0005[שם]\u0006 במסכת שבועות \u0003דלאו\u0004 \u0005[שלא]\u0006 ב\u0003עיקר שבת הוא\u0004 עוסק, על כן \u0003תני\u0004 \u0005[שנה]\u0006 \u0003אבות\u0004 ואילו \u0003תולדות\u0004 הוא \u0003לא תני\u0004","\u0005[שונה].\u0006 על כך שואלים: \u0003אבות מאי ניהו\u0004 \u0005[מה הם]\u0006 בענין שבת? — ה\u0003יציאות\u0004 (ההוצאות מרשות היחיד אל רשות הרבים), ואולם \u0003יציאות\u0004 הלא רק \u0003תרי הויין\u0004 \u0005[שתים הן],\u0006 האחת, שמוציא בעל הבית מרשות היחיד ונותן לעני ברשות הרבים, והאחרת, שמוציא העני מתוך ידו של בעל הבית הנמצאת ברשות היחיד ומעביר לרשות הרבים! ומה הן איפוא אותן שתים \u0003נוספות האמורות במסכת שבועות (\"שהן ארבע\")?\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שבמסכת שבועות נמנות כל ארבע ההוצאות המוזכרות במשנתנו (גם אלה של החלק השני, שבהן נעשתה רק חצי מלאכה), הרי ש\u0003מהן לחיוב ומהן לפטור,\u0004 ודבר זה לא יתכן, \u0003והא דומיא\u0004 \u0005[והרי בדומה]\u0006 ל\u0003מראות נגעים קתני\u0004 \u0005[שנה]\u0006 במשנה, ואם כן יש להקבילם ולומר כי \u0003מה התם כולהו לחיובא\u0004 \u0005[שם,\u0006 במראות נגעים, \u0005כולם,\u0006 שניים שהם ארבעה, \u0005לחיוב],\u0006 \u0003אף הכא נמי כולהו לחיובא\u0004 \u0005[כאן\u0006 בענין שבת \u0005כולם לחיוב]!\u0006","\u0003אלא אמר רב פפא\u0004 כי יש להבין את הדברים כך: \u0003הכא\u0004 \u0005[כאן]\u0006 שב\u0003עיקר שבת הוא\u0004 עוסק, על כן \u0003תני חיובי ופטורי\u0004 \u0005[שנה\u0006 גם \u0005חיובים ו\u0006גם \u0005פטורים],\u0006 גם מקרים של הוצאה והכנסה שיש בהם חיוב מן התורה, וגם כאלה הפטורים מן התורה, ואילו \u0003התם דלאו\u0004 \u0005[שם שלא]\u0006 ב\u0003עיקר שבת הוא\u0004 עוסק, על כן \u0003חיובי תני\u0004 \u0005[חיובים שנה],\u0006 \u0003ופטורי\u0004 \u0005[ו\u0006אילו \u0005פטורים]\u0006 \u0003לא תני\u0004 \u0005[שנה].\u0006","על כך שואלים: \u0003חיובי מאי ניהו\u0004 \u0005[חיובים מה הם]?\u0006 — ה\u0003יציאות,\u0004 ואולם \u0003יציאות\u0004 הלא רק \u0003תרתי הויין\u0004 \u0005[שתים הן],\u0006 הוצאה מבפנים והוצאה מבחוץ, ומה אם כן משמעות לשון המשנה במסכת שבועות \"שהן ארבע\"? ומשיבים: אפשר למנות ארבע, \u0003שתים\u0004 של \u0003הוצאה ושתים\u0004 של \u0003הכנסה,\u0004 שגם המקרים של הכנסה מרשות הרבים לרשות היחיד נמנים במסכת שבועות.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 לשון \u0003\"יציאות\" קתני\u0004 \u0005[שנה]\u0006 שם, והרי שאין מדובר בהכנסות! \u0003אמר רב אשי:\u0004 ה\u0003תנא\u0004 שם \u0003הכנסה נמי\u0004 \u0005[גם כן]\u0006 \u0003\"הוצאה\" קרי\u0004 \u0005[\u0006הוא \u0005קורא]\u0006 \u0003לה.\u0004","\u0003ממאי\u0004 \u0005[ממה]\u0006 מהיכן אתה למד זאת? \u0003מדתנן\u0004 \u0005[מ\u0006מה \u0005ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המוציא מרשות לרשות\u0004 — \u0003חייב, ומי לא עסקינן\u0004 \u0005[והאם איננו עוסקים]\u0006 שם גם באופן \u0003דקא מעייל\u0004 \u0005[שהוא מכניס]\u0006 \u0003מרשות הרבים לרשות היחיד, וקא קרי\u0004 \u0005[והוא קורא]\u0006 \u0003לה\u0004 בלשון \u0003\"הוצאה\".\u0004","\u0003וטעמא מאי\u0004 \u0005[ומה טעם]\u0006 לשימוש לשון זה? — שכן \u0003כל עקירת חפץ ממקומו\u0004 והעברתו לרשות אחרת ה\u0003תנא\u0004 בלשון \u0003\"הוצאה\" קרי\u0004 \u0005[קורא]\u0006 \u0003לה,\u0004 שאין כוונתו כשהוא עוסק בהוצאה מן הבית אל החוץ, אלא כהגדרה כללית של העברת דבר מתחומו אל תחום אחר.","\u0003אמר רבינא: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 ומלשונה ניתן להסיק אותה מסקנה עצמה, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בה בלשון \u0003\"יציאות\u0004 השבת \u0003\"וקא\u0004 \u0005[והוא]\u0006 \u0003מפרש הכנסה לאלתר\u0004 \u0005[מיד],\u0006 שהמקרה הראשון המפורט במשנה הוא שהעני נותן חפץ בידו של בעל הבית, והרי זו הכנסה מרשות הרבים לרשות היחיד. ומעירים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך הוא.","\u0003רבא אמר:\u0004 לשון \"יציאות\" אינה קשה, שכן התנא בשתי המשניות לא לשון \"יציאות השבת\" שנה, כי אם \u0003\"רשויות\u0004 השבת \u0003\" קתני\u0004 \u0005[שנה],\u0006 וכך היא הגירסה הנכונה: \u0003\"רשויות שבת שתים\u0004 שהן ארבע \u0003\",\u0004 ולדבריו בשתי רשויות אלה יש ארבעה מקרים של מלאכה, בפנים ובחוץ.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מתנה לאביי:\u0004 במשנה מדובר על שתים שהן ארבע בפנים ושתים שהן ארבע בחוץ, הרי שמונה, ואולם קשה: וכי \u0003הא תמני הויין\u0004 \u0005[אלו שמונה הן]?\u0006 והלא \u0003תרתי סרי הויין\u0004 \u0005[שתים עשרה הן!],\u0006 שאם נתבונן נראה שבחלק האחרון של המשנה עושים גם העני וגם בעל הבית כל אחד פעולה אחת כדי לבצע את מלאכת ההכנסה או ההוצאה. ואם כן, יש ארבע פעולות הנמנות בחלקה הראשון של המשנה, ושמונה פעולות בחלקה השני!","ענה לו אביי: \u0003וליטעמיך שיתסרי הויין\u0004 \u0005[ולטעמך,\u0006 לשיטתך, הלא \u0005שש עשרה הן],\u0006 שכן גם בחלק הראשון משתתף מקבל החפץ מיד עושה הפעולה, ואף הוא עושה פעולה מסויימת, ואם כן, שש עשרה פעולות הן בסך הכל!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב מתנה: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה]\u0006 כי \u0003בשלמא\u0004 \u0005[נניח]\u0006"],["\u0003בבא דרישא\u0004 \u0005[החלק הראשון]\u0006 של המשנה המדבר במקרים שהעושה אותם הריהו \u0003פטור\u0004 מדין תורה, ואף מדברי חכמים הוא \u0003מותר\u0004 מלכתחילה בעשייה, שכן בין העני ובין בעל הבית שניתן החפץ על ידי האחר לתוך ידיהם לא עשו לא עקירה ולא הנחה, ואין במה שעשו כל חשיבות, ולכן \u0003לא קתני\u0004 \u0005[שנה],\u0006 לא החשיב אותם במשנה כחלק ממנין ההוצאות מרשות לרשות, \u0003אלא בבא דסיפא\u0004 \u0005[החלק שבסוף]\u0006 העוסק במקרים שאף שמדין תורה העושה אותם \u0003פטור, אבל\u0004 מדברי חכמים הוא \u0003אסור\u0004 — \u0003קשיא\u0004 \u0005[קשה],\u0006 שכל שמונת הפעולות המנויות אחרונות, אף שהעושה אותן פטור מדברי תורה, אסרו חכמים לעשות כן.","ובדרך אגב תוהים: \u0003מי איכא בכולי\u0004 \u0005[והאם יש בכל]\u0006 דיני \u0003שבת\u0004 מעשה שהוא בגדר \u0003\"פטור ומותר\"?! והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: כל פטורי\u0004 \u0005[הפטורים]\u0006 הכתובים בדיני \u0003שבת\u0004 הכוונה היא שהעושה אותם \u0003פטור\u0004 מדין תורה \u0003אבל\u0004 מדברי חכמים \u0003הוא אסור, בר מהני תלת\u0004 \u0005[חוץ משלושה אלה]\u0006 שהם בגדר \u0003\"פטור ומותר \": צידת צבי,\u0004 שלא צד אותו ממש אלא שישב אדם בפתחו של בית שקודם לכן נכנס לתוכו צבי מעצמו, \u0003ו\u0004כן \u0003צידת נחש\u0004 ארסי מפני הסכנה, \u0003ו\u0004כן ה\u0003מפיס מורסא,\u0004 כלומר, הפותח בועת מוגלה ומוציא מתוכה את הליחה. ואם כן, ודאי אף במקרה שנאמר בו בתחילת משנתנו \"פטור\" יש להבינו כ\"פטור אבל אסור\"!","ומשיבים: גם במקרים אלה הכוונה היא \"פטור ומותר\", אלא \u0003כי איצטריך ליה\u0004 \u0005[כאשר הוצרך לו]\u0006 \u0003לשמואל\u0004 להביא את שלושת המקרים היוצאים מן הכלל, הרי היו אלה \u0003פטורי דקא עביד\u0004 \u0005[\u0006מעשי \u0005פטור שהוא,\u0006 האדם, \u0005עושה]\u0006 בהם \u0003מעשה\u0004 מסויים, \u0003אבל פטורי דלא קא עביד\u0004 \u0005[\u0006מעשי \u0005פטור שאין הוא עושה]\u0006 בהם \u0003מעשה איכא טובא\u0004 \u0005[יש הרבה].\u0006","ושבים לשאלתו של רב מתנה: \u0003מכל מקום, תרתי סרי הויין\u0004 \u0005[שתים עשרה\u0006 פעולות \u0005הן]!\u0006 ומשיבים: \u0003פטורי דאתי בהו\u0004 \u0005[\u0006מעשי \u0005פטור שבא]\u0006 העושה אותם בשל עשייתם \u0003לידי חיוב חטאת\u0004 — \u0003קא חשיב\u0004 \u0005[הוא מונה],\u0006 ואילו מעשי פטור \u0003דלא אתי בהו\u0004 \u0005[שאינו בא בהם]\u0006 \u0003לידי חיוב חטאת\u0004 — \u0003לא קא חשיב\u0004 \u0005[אינו מונה].\u0006 שנמנים כאן רק המקרים של עקירת החפץ ממקומו, שבמקרה זה אם ימשיכו את המלאכה — אפשר לבוא לידי חיוב חטאת. ואולם הנחת חפץ לבדה איננה עשויה לגרור אחריה איסור חמור יותר.","לגופה של המשנה שואלים: בחלקה האחרון נמנים מקרים בהם \u0003שניהן פטורין,\u0004 ואולם, \u0003הא אתעבידא\u0004 \u0005[הרי נעשתה]\u0006 \u0003מלאכה מבינייהו\u0004 \u0005[מביניהם]!\u0006 ומאחר ששניהם יחד ביצעו לבסוף פעולה האסורה באיסור חמור מן התורה, כיצד יתכן ששיתופם יפטור את שניהם? על כך משיבים מזה ש\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 שהיה \u0003רבי אומר:\u0004 נאמר \"ואם נפש אחת תחטא בשגגה \u0003מעם הארץ בעשתה\u0004 אחת ממצוות ה' אשר לא תעשינה ואשם\" (ויקרא ד, כז), ומהדגשת הכתוב \"בעשותה\", שמשמעו: בעשותו אותה, יש להבין כי רק \u0003העושה את כולה,\u0004 את כל העבירה כולה הוא החייב, \u0003ולא העושה\u0004 את \u0003מקצתה,\u0004 ועל כן, \u0003יחיד ועשה אותה\u0004 — \u0003חייב,\u0004 ואילו \u0003שנים ועשו אותה\u0004 — \u0003פטורין,\u0004 שהרי כל אחד מהם עשה רק מקצתה. ומעירים: \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כשיטה זו של רבי, שכן \u0003אמר ר' חייא בר גמדא:\u0004 בתוך כדי דיון בדברים אלה \u0003נזרקה מפי חבורה\u0004 של חכמים \u0003ואמרו:\u0004 מהדגשת הכתוב \u0003\"בעשתה\"\u0004 למדים אנו כי \u0003יחיד שעשאה\u0004 — \u0003חייב,\u0004 ואילו \u0003שנים שעשאוה\u0004 — \u0003פטורין.\u0004","\u0003בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב מרבי:\u0004 אדם אשר \u0003הטעינו חבירו אוכלין ומשקין\u0004 על גבו ברשות היחיד בשבת, \u0003והוציאן\u0004 אותו אדם \u0003לחוץ\u0004 בעודם על גבו, \u0003מהו\u0004 דינו לגבי איסור הוצאה בשבת? וצדדי השאלה: הדבר ברור שאם היה המוציא לוקח חפץ בידו ועוקרו מרשות היחיד ומוציאו לרשות הרבים, היה חייב, ואולם השאלה היא: האם \u0003עקירת גופו\u0004 ממקומו ברשות היחיד כשהוא טעון חפץ \u0003כעקירת\u0004 ה\u0003חפץ\u0004 עצמו \u0003ממקומו דמי\u0004 \u0005[נחשבת],\u0006 ובמקרה זה יהיה \u0003חייב\u0004, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003לא\u0004 נחשב הדבר כעקירת החפץ ממקומו ולכן לא יהיה חייב? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003חייב, ואינו דומה ל\u0004דין אדם שהניחו ב\u0003ידו\u0004 חפץ, והוא רק הוציאו לרשות הרבים ששנינו במשנה שאינו חייב מן התורה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל בין שני המקרים הדומים לכאורה? — \u0003גופו נייח\u0004 \u0005[נח,\u0006 קבוע\u0005]\u0006 כרגיל במקום מסויים, ואולם \u0003ידו לא נייח\u0004 \u0005[אינה נחה].\u0006 ומאחר והיד אינה קבועה במקום אחד, לכן הזזתה ואף העברתה לרשות אחרת בלא פעולה ממשית של עקירה אינה נחשבת לעקירה. ואולם הגוף שהוא כרגיל קבוע במקום אחד, עקירתו ממקומו נחשבת לעקירה לענין שבת, וחייב עליה."],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא לרב\u0004 בן אחותו: \u0003בר פחתי\u0004 \u0005[בן אצילים],\u0006 \u0003לאו אמינא\u0004 \u0005[האם לא אמרתי]\u0006 \u0003לך, כי קאי\u0004 \u0005[\u0006כי \u0005כאשר עומד,\u0006 נמצא\u0005]\u0006 \u0003רבי בהא מסכתא\u0004 \u0005[במסכת זו]\u0006 \u0003לא תשייליה במסכתא אחריתי, דילמא לאו אדעתיה\u0004 \u0005[אל תשאלנו\u0006 שאלה \u0005במסכת אחרת, שמא אינה בדעתו]\u0006 ולא יוכל לענות. ושאלה זו ששאל רב לא בענין המסכת שהיו עוסקים בה היתה. \u0003דאי לאו\u0004 \u0005[שאם לא]\u0006 ש\u0003רבי גברא רבה\u0004 \u0005[אדם גדול]\u0006 \u0003הוא\u0004 — \u0003כספתיה\u0004 \u0005[היית מבייש אותו],\u0006 \u0003דמשני\u0004 \u0005[ש\u0006היה צריך \u0005לתרץ]\u0006 \u0003לך שינויא דלאו שינויא\u0004 \u0005[תירוץ שלא תירוץ]\u0006 \u0003הוא,\u0004 כלומר, תירוץ שאינו ראוי.","\u0003השתא מיהת שפיר משני\u0004 \u0005[עכשיו על כל פנים יפה תירץ]\u0006 \u0003לך\u0004 על אף היותו עסוק במסכת אחרת. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מי שהיה טעון\u0004 (נושא) \u0003אוכלין ומשקין מבעוד יום\u0004 (לפני כניסת שבת), ומכיון שכן לא עשה בהם מלאכת עקירה בתוך השבת, \u0003ו\u0004אולם \u0003הוציאן לחוץ\u0004 לרשות הרבים \u0003משחשיכה\u0004 בליל השבת — \u0003חייב, לפי ש\u0004גופו קבוע בדרך כלל במקום אחד, ולכן עקירתו נחשבת כעקירה, וחייב, ו\u0003אינו דומה ל\u0004עקירה סתמית של \u0003ידו\u0004 והזזתה ממקום למקום, שמאחד וידו אינה קבועה במקום אחד אין זה נחשב לעקירה.","\u0003אמר אביי: פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 \u0003לי\u0004 כי \u0003ידו של אדם\u0004 בעצמה כאשר מוציא אותה מן הרשות שהוא נמצא בה \u0003אינה\u0004 נחשבת \u0003לא כרשות הרבים ולא כרשות היחיד,\u0004 אף אם עומד בעל היד באחת מרשויות אלה. והוכחה לדבר: \u0003כרשות הרבים לא דמיא\u0004 \u0005[אינה נחשבת]\u0006 — \u0003מ\u0004דברי המשנה ביחס ל\u0003ידו\u0004 של ה\u0003עני.\u0004 ששנינו שהעני שהכניס ידו לרשות היחיד כשבתוכה חפץ שעקר מרשות הרבים ונטל בעל הבית את החפץ מתוכה — אין בעל הבית חייב, הרי שידו של העני איננה חלק מרשות הרבים אף כי הוא עצמו נמצא ברשות הרבים. ואף \u0003כרשות היחיד לא דמיא\u0004 \u0005[אינה נחשבת],\u0006 והוכחה לדבר — \u0003מ\u0004דברי המשנה ביחס ל\u0003ידו\u0004 של \u0003בעל הבית.\u0004 ששנינו שאם הוציא בעל הבית ידו לחוץ, ונטל העני מתוכה - אין פעולה זו נחשבת כמלאכת הוצאה מרשות היחיד.","ואולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אביי: ידו של אדם\u0004 ובה חפץ, והושיטה אותו אדם לרשות אחרת, \u0003מהו\u0004 דינה לענין \u0003שתעשה\u0004 (תיחשב להלכה) \u0003ככרמלית,\u0004 שהיא רשות ביניים שתיקנו חכמים, שאינה לא רשות היחיד ולא רשות הרבים, וזאת משום שיצאה מכלל רשות אחת ולא נכנסה לרשות שניה? וצדדי השאלה הלכה למעשה: \u0003מי קנסוה רבנן לאהדורי לגביה\u0004 \u0005[האם קנסוהו חכמים ל\u0006ענין \u0005החזרתה אליו]\u0006 וייאסר עליו מדבריהם להחזירה למקום בו הוא עומד, \u0003או לא?\u0004","ואומרים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו במקום אחר. שעל השאלה מה יעשה אדם שהיה בבית, כלומר, ברשות היחיד \u0003והיתה ידו מלאה פירות והוציאה לחוץ,\u0004 לרשות הרבים, \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]\u0006 ש\u0003אסור להחזירה\u0004 אל תוך ביתו, \u0003ותני אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 ש\u0003מותר להחזירה.\u0004 ובכן, \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה הם חלוקים]?\u0006 \u0003דמר סבר\u0004 \u0005[שחכם\u0006 \u0003זה\u0004 בברייתא אחת \u0005סבור]\u0006 כי היד \u0003ככרמלית דמיא\u0004 \u0005[נחשבת],\u0006 \u0003ומר סבר לאו\u0004 \u0005[שחכם\u0006 \u0003זה\u0004 בברייתא האחרת \u0005סבור\u0006 כי \u0005לא]\u0006 \u0003ככרמלית דמיא\u0004 \u0005[נחשבת]?!\u0006","את ההסברה הזו דוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003ככרמלית דמיא\u0004 \u0005[נחשבת]\u0006 \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 שאת ההבדל בין הברייתות יש לפרש כך: \u0003כאן,\u0004 ששנינו שאסור להחזיר את היד, הרי זה באופן שהוציאה בגובה \u0003למטה מעשרה\u0004 טפחים, והרי היא בתחום אוירה של רשות הרבים. \u0003וכאן,\u0004 ששנינו שמותר להחזירה, הרי באופן שהוציאה בגובה \u0003למעלה מעשרה\u0004 טפחים, שבכגון זה אינה נחשבת לא כתחום רשות הרבים ולא ככרמלית.","\u0003ואיבעית אימא\u0004 \u0005[ואם\u0006 תרצה אמור] כי \u0003אידי ואידי\u0004 \u0005[זו וזו],\u0006 שתי הברייתות עוסקות בכגון שהוציא ידו לרשות הרבים בגובה \u0003למטה מעשרה\u0004 טפחים \u0003ולאו\u0004 \u0005[ולא]\u0006 \u0003ככרמלית דמיא\u0004 \u0005[נחשבת]\u0006 היד, \u0003ו\u0004אף על פי כן \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן, \u0003כאן\u0004 שהתירו להחזירה הרי זה באופן שהוציאה \u0003מבעוד יום\u0004 בערב שבת, ומאחר שהוציאה מבעוד יום ולא עשה כל איסור בהוצאה זו, לכן לא קנסוהו חכמים והתירו לו להחזירה אף בשבת, ואולם \u0003כאן\u0004 שאסרו עליו להחזירה, הרי זה בכגון שהוציאה \u0003משחשיכה\u0004 וכבר נכנסה השבת, ומאחר שכן הרי שיש בכך צד איסור ולכך \u0003מבעוד יום, לא קנסוהו רבנן, משחשיכה, קנסוהו רבנן\u0004 ואסרו עליו להחזירה.","ומעירים: בהסבר זה קיים קושי מסויים, שכן \u0003אדרבה, איפכא מסתברא\u0004 \u0005[ההיפך\u0006 מזה \u0005מסתבר]\u0006 לומר, שכן שכשהוציא את היד \u0003מבעוד יום, דאי שדי ליה\u0004 \u0005[ש\u0006גם \u0005אם יזרוק אותו],\u0006 את החפץ שבתוכה החוצה \u0003לא אתי\u0004 \u0005[יבוא]\u0006 בכך \u0003לידי חיוב חטאת,\u0004 שהרי עקירת החפץ ממקומו היתה ביום חול, ולא תהא כאן אלא הנחה — ואם כן \u0003ליקנסוה רבנן\u0004 \u0005[שיקנסוהו חכמים],\u0006 ואולם אם הוציא את היד \u0003משחשיכה, דאי שדי ליה אתי בהו\u0004 \u0005[שאם יזרוק אותו,\u0006 את החפץ שבתוכה החוצה \u0005יבוא\u0006 \u0003בו] לידי חיוב חטאת\u0004 — \u0003לא ליקנסוה רבנן\u0004 \u0005[אל יקנסוהו חכמים].\u0006 שהרי אם יקנסוהו חכמים ויאסרו עליו להחזיר את ידו, עלול הוא להפיל את החפץ ברשות הרבים, ואם יעשה כן יעבור על איסור מן התורה.","\u0003ומ\u0004כיון ש\u0003לא משנינן הכי\u0004 \u0005[תירצנו כך]\u0006 אלא השתמשנו בדרך התירוץ הראשונה, הרי \u0003תפשוט\u0004 \u0005[תפתור],\u0006 מכאן את שאלתו של \u0003רב ביבי בר אביי.\u0004 ששאלתו היתה קשורה באותו נושא עקרוני. \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רב ביבי בר אביי:\u0004 מי ששגג ו\u0003הדביק\u0004 בשבת \u0003פת בתנור,\u0004 כדרך שהיו נוהגים לאפות לחם על ידי הדבקת הבצק בתנור המחומם, האם \u0003התירו לו\u0004 לבטל איסור שמדברי סופרים ו\u0003לרדותה\u0004 מן התנור \u0003קודם ש\u0004תיאפה ואז \u0003יבוא לידי חיוב חטאת\u0004 על אפיית לחם בשבת, \u0003או לא התירו?\u0004 שכן רדיית הפת אף היא אסורה בשבת, ואולם איסורה הוא רק מדברי סופרים. והשאלה הכללית היא: האם מותר לאדם לעבור על איסור מדברי סופרים, כדי שלא להכשל באיסור מן התורה, או לא?","ובהסתמך על הדברים שנאמרו קודם, \u0003תפשוט\u0004 \u0005[תפטור]\u0006 ש\u0003לא התירו,\u0004 שהרי בתשובה לבעיית אביי לא הובאה בחשבון ההנחה שאף אם יזרוק אדם את החפץ מידו, ויבוא בכך לידי איסור מן התורה, בכל זאת חייב הוא לקיים את קנסם של חכמים. אף כאן נפתור את הבעיה, ונאמר שלא ירדה את הפת, אף על פי שיתחייב בכך מדברי תורה. ואם כן בעיה זו של רב ביבי בר אביי שסבורים היינו שאין לה פתרון, נפתרה כאן, ויש להסתפק אם כן שמא לא היה התירוץ הקודם מבוסס כל צרכו. את הקושי הזה דוחים: \u0003הא לא קשיא\u0004 \u0005[\u0006דבר \u0005זה אינו קשה],\u0006 שיתכן לומר כי אף שלא נמצאה תשובה לשאלת רב ביבי בר אביי בזמנה, אין זאת אומרת שאינה ניתנת לפתרון, \u0003ו\u0004אכן משיש לך עתה ראיה לדבר מפתרון הקושי הקודם, \u0003תפשוט\u0004 \u0005[תפתור]\u0006 בכך אף שאלה זו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי \u0003לעולם לא תפשוט\u0004 \u0005[תפתור]\u0006 את השאלה, \u0003ולא קשיא\u0004 ומכל מקום יכול אתה לתרץ את הסתירה בין הברייתות ולומר כי \u0003כאן\u0004 כשהתירו להחזיר את היד הרי זה באופן שהוציאה לחוץ \u0003בשוגג,\u0004 ו\u0003כאן\u0004 שאסרו עליו להחזירה הרי זה באופן שהוציאה \u0003במזיד.\u0004 שאם הוציאה \u0003בשוגג\u0004 — \u0003לא קנסוה רבנן\u0004 \u0005[קנסוהו חכמים].\u0006 וכשהוציאה \u0003במזיד קנסוה רבנן\u0004 \u0005[קנסוהו חכמים]\u0006 ואסרו עליו להחזירה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כדי לתרץ את הסתירה כי \u0003אידי ואידי\u0004 \u0005[זו וזו,\u0006 שתי הברייתות\u0005]\u0006 מדברות באופן שהוציא את היד \u0003בשוגג, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003קנסו שוגג אטו\u0004 \u0005[משום]\u0006 \u0003מזיד קמיפלגי\u0004 \u0005[הם חלוקים],\u0006 ש\u0003מר סבר\u0004 \u0005[חכם זה\u0006 האוסר להחזירה \u0005סבור]\u0006 כי \u0003קנסו שוגג אטו\u0004 \u0005[משום]\u0006 \u0003מזיד,\u0004 ולכן אף על פי שהוציא את ידו לחוץ בשוגג, קונסים אותו ואוסרים עליו להחזירה, כדי שלא יבוא לעשות כן במזיד. \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 המתיר להחזירה \u0005סבור]\u0006 כי \u0003לא קנסו שוגג אטו\u0004 \u0005[משום]\u0006 \u0003מזיד,\u0004 ולכן לא אסרו עליו להחזירה.","\u0003ואיבעית אימא\u0004 \u0005[ואם\u0006 \u0005תרצה אמור]\u0006 כי \u0003לעולם לא קנסו שוגג אטו\u0004 \u0005[משום]\u0006 \u0003מזיד, ו\u0004אף על פי כן, \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 ואין כאן סתירה, כי \u0003כאן\u0004 הברייתא המתירה להחזירה מדברת לענין להחזירה \u0003לאותה חצר\u0004 שהוא עומד בתוכה,"],["\u0003כאן\u0004 הברייתא האוסרת להחזירה מדברת לענין להחזירה \u0003לחצר אחרת.\u0004 וכפי \u0003דבעא מיניה\u0004 \u0005[ששאל ממנו]\u0006 \u0003רבא מרב נחמן\u0004 שאלה זו: מי שהיה עומד בשבת בחצר ו\u0003היתה ידו מלאה פירות והוציאה לחוץ\u0004 לרשות הרבים, \u0003מהו\u0004 דינו לענין שיוכל \u0003להחזירה לאותה חצר\u0004 בה הוא עומד? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003מותר.\u0004 ושאלו עוד: \u0003מהו\u0004 דינה לענין להחזירה לא לאותה חצר אלא \u0003לחצר אחרת? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אסור.\u0004","על כך שאל רבא: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 מקרה אחד מחבירו, שהרי מבחינת ההגדרה שתי החצרות הריהן רשות היחיד, ולכאורה אין הבדל ביניהן מצד הלכות שבת! ענה רב נחמן בבדיחות הדעת: \u0003לכי תיכול עלה כורא דמילחא\u0004 \u0005[כאשר תאכל עליה כור מלח],\u0006 כלומר, צריך אתה לחשוב בדבר כל כך הרבה זמן כדי שאפשר באותו זמן לאכול כור שלם (שהיא מידה גדולה) של מלח. והרי פשוטה היא התשובה: \u0003התם\u0004 \u0005[שם]\u0006 שאמרנו שלהחזירה לתוך חצירו מותר, הרי זה משום ש\u0003לא איתעבידא\u0004 \u0005[נעשתה]\u0006 \u0003מחשבתו,\u0004 שכן רצה להוציא חפץ מתוך חצרו, ואם מחייבים אותו להחזיר את החפץ למקומו הרי אף בכך יש משום קנס מסויים. ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 שאמרנו שאסור לו להחזירה לחצר אחרת, הרי זה משום ש\u0003איתעבידא\u0004 \u0005[נעשתה]\u0006 \u0003מחשבתו\u0004 ולכן אסור לו להחזירה לשם.","מאחר שהוזכרה שאלתו של רב ביבי בר אביי דנים עתה בשאלה זו \u0003גופא\u0004 \u0005[לגופה].\u0006 \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב ביבי בר אביי\u0004 מי ש\u0003הדביק פת בתנור\u0004 בערב שבת ונכנסה השבת האם \u0003התירו לו\u0004 לבטל את האיסור שמדברי סופרים \u0003ולרדותה קודם ש\u0004תיאפה ואז \u0003יבוא לידי חיוב חטאת, או לא התירו?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר אביי לרבינא: היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהדביק את הפת \u0003בשוגג ולא אידכר ליה\u0004 \u0005[נזכר לו]\u0006 שהיום שבת, או שיש בכך איסור, אם כן \u0003למאן\u0004 \u0005[למי]\u0006 \u0003התירו?\u0004 שאם אינו זוכר שיש בדבר איסור, לא יעלה בדעתו לשאול אם מותר לו לרדות את הפת קודם אפייתה.","\u0003ואלא לאו דאיהדר ואידכר\u0004 \u0005[האם לא\u0006 תאמר \u0005שחזר ונזכר]\u0006 עוד לפני שנאפית שהדבר אסור, ואולם במקרה כזה זה \u0003מי מחייב\u0004 \u0005[האם\u0006 הוא \u0005חייב]\u0006 בקרבן חטאת?! \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל\u0004 החוטאים בשגגה ובשל כך הם \u0003חייבי חטאות\u0004 — \u0003אינן חייבין עד שתהא תחלתן שגגה וסופן שגגה,\u0004 שמתחילת המעשה ועד סופו לא יזכור אותו אדם שיש איסור בדבר. ואם כן, במקרה שלנו, מאחר שנזכר תוך כדי אפיית הלחם שיש איסור בדבר, עצם הזכרותו כבר פוטרת אותו מאיסור חטאת, והרדיה אינה דרושה עוד כדי למונעו מחיוב חטאת.","ו\u0003אלא\u0004 יש לומר שאותו אדם הדביק את הפת בתנור \u0003במזיד\u0004 והתחרט לאחר מכן ורצונו שלא לעבור עבירה. ואולם אז סגנון השאלה איננו מדוייק, ובלשון \u0003\"קודם שיבא לידי איסור סקילה\" מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 לומר! שהמחלל שבת במזיד חייב סקילה, ולא רק קרבן חטאת.","\u0003אמר רב שילא: לעולם\u0004 נפרש שהיה זה \u0003בשוגג,\u0004 והשאלה אם התירו לרדות את הפת היא לא ביחס לאותו אדם שהדביקה בתנור, \u0003אלא למאן\u0004 \u0005[למי]\u0006 \u0003התירו\u0004 — \u0003לאחרים\u0004 הרוצים להציל את העבריין מאיסור מן התורה.","\u0003מתקיף לה\u0004 \u0005[הקשה על כך]\u0006 \u0003רב ששת: וכי אומרים לו לאדם \"חטא כדי שיזכה חבירך\"?!\u0004 והרי אין להעלות על הדעת אפשרות להתיר איסור, אפילו מדברי חכמים, כדי לזכות אדם אחר במצוה, והוא הדין שאין מתירים כדי למנוע אדם אחר מלעבור איסור!","\u0003אלא אמר רב אשי: לעולם\u0004 המדובר הוא שהדביק את הפת \u0003במזיד. ואימא\u0004 \u0005[ואמור,\u0006 גרוס\u0005]\u0006 כך: \u0003קודם שיבא לידי איסור סקילה.\u0004 ואכן, \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מתני לה בהדיא\u0004 \u0005[היה שונה אותה\u0006 כך \u0005במישרין]\u0006 בדרך פשוטה יותר, ולא כשאלה כי אם כפסק הלכה. שלדבריו \u0003אמר רב ביבי בר אביי:\u0004 מי ש\u0003הדביק פת בתנור\u0004 בערב שבת \u0003התירו לו לרדותה\u0004 בשבת מהתנור \u0003קודם שיבא לידי איסור סקילה.\u0004","שנינו במשנה דוגמאות מספר שבהן \u0003פשט העני את ידו,\u0004 פעם שנתן לידו של בעל הבית, ופעם שנטל מידו של בעל הבית, ובמקרים אלה שנינו שחייב חטאת. על כך שואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב? והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 להלכה שה\u0003עקירה ו\u0004ה\u0003הנחה\u0004 תהיינה \u0003מעל גבי מקום ארבעה על ארבעה\u0004 טפחים, ובפחות מכן אין זה נחשב למקום מסויים, וכאילו אין החפץ מצוי כלל במקום, \u0003ו\u0004הרי בידו של אדם \u0003ליכא\u0004 \u0005[אין]\u0006 שיעור זה. ומשום מה חייב?","\u0003אמר רבה: הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 דעת \u0005מי היא]?\u0006 — דעת \u0003ר' עקיבא\u0004 היא ש\u0003אמר\u0004 ש\u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיהיה \u0003מקום ארבעה על ארבעה,\u0004 ולדעתו אף בפחות משיעור זה הריהו נחשב כמקום לענין הוצאת שבת. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הזורק\u0004 חפץ \u0003מרשות היחיד\u0004 אחת \u0003לרשות היחיד\u0004 אחרת \u0003ורשות הרבים באמצע, ר' עקיבא מחייב\u0004 משום הוצאה לרשות הרבים, \u0003וחכמים פוטרים,\u0004 כיון שרק עבר החפץ בתוך רשות הרבים ולא הונח בו.","ואת המחלוקת הזו יש להסביר כך: \u0003ר' עקיבא סבר אמרינן\u0004 \u0005[סבור\u0006 כי \u0005אומרים אנו,\u0006 מניחים\u0005]\u0006 כי \u0003קלוטה כמי שהונחה דמיא\u0004 \u0005[נחשבת],\u0006 ומאחר ולדעתו חפץ שנקלט אף לזמן קצר ביותר בתוך חללה של רשות הרבים, הרי הוא כאילו נח בתוכה, ולפיכך היתה כאן איפוא עקירה מרשות היחיד והנחה ברשות הרבים, ולכן יש לחייב את הזורק. \u0003ורבנן סברי לא אמרינן\u0004 \u0005[וחכמים סבורים\u0006 כי \u0005אין אנו אומרים]\u0006 \u0003קלוטה כמי שהונחה דמיא\u0004 \u0005[נחשבת],\u0006 ומאחר שלדעתם לא נח החפץ כלל ברשות הרבים לא היתה כאן עקירה מרשות היחיד והנחה ברשות הרבים, ולכן הריהו פטור. ועל כל פנים אפשר ללמוד מדברי ר' עקיבא שהנחה אינה דורשת מקום מסויים, אלא עצם הימצאותו של חפץ בתוך רשות הרבים משמשת כבר כהנחה. הרי שלשיטה זו אין צורך בהנחה על גבי מקום של ארבעה על ארבעה טפחים.","ומתחילה תוהים על עצם דבריו של רבה: \u0003למימרא דפשיטא ליה\u0004 \u0005[האם נאמר כי פשוט לו]\u0006 \u0003לרבה\u0004 ש\u0003ב\u0004שאלה האם \u0003קלוטה כמי שהונחה דמיא\u0004 \u0005[נחשבת]\u0006"],["\u0003ו\u0004כשהיה הדבר \u0003בתוך עשרה\u0004 טפחים מן הקרקע \u0003פליגי\u0004 \u0005[נחלקו],\u0006 \u0003והא מיבעיא בעי לה\u0004 \u0005[והרי בשאלה שאל אותה]\u0006 \u0003רבה,\u0004 שלא היה ברור לו אם אמנם זה הוא אופן הפירוש הנכון של מחלוקת ר' עקיבא וחכמים. \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רבה:\u0004 האם החולקים בענין הזורק מרשות היחיד לרשות היחיד ורשות הרבים באמצע במקרה שנזרק החפץ \u0003למטה מעשרה\u0004 טפחים \u0003פליגי\u0004 \u0005[נחלקו],\u0006 \u0003ובהא פליגי\u0004 \u0005[וב\u0006דבר \u0005זה נחלקו],\u0006 ש\u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 כי \u0003קלוטה כמי שהונחה דמיא\u0004 \u0005[נחשבת],\u0006 \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 ש\u0003קלוטה כמי שהונחה דמיא\u0004 \u0005[נחשבת].\u0006 \u0003אבל\u0004 אם זרק את החפץ \u0003למעלה מעשרה\u0004 טפחים מעל לרשות הרבים ל\u0003דברי הכל\u0004 הוא \u0003פטור, ודכולי עלמא לא ילפינן\u0004 \u0005[ולדעת הכל אין אנו למדים]\u0006 דין \u0003זורק מ\u0004דין \u0003מושיט.\u0004 כי קיימת הלכה מיוחדת בדין הושטת חפצים, שאדם העומד ברשות היחיד ומושיט חפץ דרך רשות הרבים לרשות היחיד אחרת, אף על פי שלא נח החפץ בתחום רשות הרבים הרי זו נחשבת כהוצאה. ואולם כאמור אין דין הזורק כן.","\u0003או דילמא\u0004 \u0005[שמא]\u0006 ב\u0003למעלה מעשרה\u0004 טפחים \u0003פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 \u0003ובהא פליגי\u0004 \u0005[וב\u0006דבר \u0005זה נחלקו]:\u0006 ש\u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 כי \u0003ילפינן\u0004 \u0005[לומדים אנו]\u0006 דין ה\u0003זורק מ\u0004דין \u0003מושיט,\u0004 שיש לראותם כפרטים של הלכה אחת, \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי \u0003לא ילפינן\u0004 \u0005[אין אנו למדים]\u0006 \u0003זורק ממושיט.\u0004 ואף שהמושיט את החפץ במקרה כזה היה חייב, אבל הזורקו — פטור. כי הלכה זו ביחס ל\"מושיט\" היא הלכה מבודדת, מעין גזירת הכתוב, ואין ללמוד ממנה לגבי מקרה אחר. \u0003אבל\u0004 הזורק מרשות היחיד אחת לחבירתה דרך רשות הרבים \u0003למטה מעשרה\u0004 טפחים — ל\u0003דברי הכל חייב\u0004 הזורק. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שהכל מודים ש\u0003קלוטה כמי שהונחה דמיא\u0004 \u0005[נחשבת].\u0006","ומאחר שרבה אינו בטוח כיצד יש לפרש את המשנה בענין זורק חפץ, כיצד קובע הוא, בהסבירו את משנתנו, מה דעתו של ר' עקיבא בנושא זה? על כך משיבים: \u0003הא לא קשיא\u0004 \u0005[\u0006דבר \u0005זה אינו קשה]\u0006 שיש לומר כי \u0003בתר דאיבעי הדר איפשיטא ליה\u0004 \u0005[אחר שנשאלה לו\u0006 שאלה זה \u0005חזרה ונפתרה לו]\u0006 שיש להבין \u0003דסבר\u0004 \u0005[שסבור]\u0006 \u0003ר' עקיבא\u0004 ש\u0003קלוטה כמי שהונחה דמיא\u0004 \u0005[נחשבת].\u0006 ואולם לגופם של דברים יש עוד מקום לשאול על עצם ההשוואה בין דברי ר' עקיבא לבין הכתוב במשנתנו.","כי \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003הנחה\u0004 לבדה \u0003הוא דלא בעיא\u0004 \u0005[שאינה צריכה]\u0006 מקום ארבעה על ארבעה כדי שתיחשב להנחה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003עקירה בעיא\u0004 \u0005[צריכה]\u0006 לשיעור מקום זה. כי ההנחה, בהיותה רק סיום מלאכה אינה דורשת את כל התנאים כמו העקירה שהיא תחילתה ועיקרה של מלאכת ההוצאה (רשב\"א). ואולם מדברי ר' עקיבא למדים אנו רק שקלוטה כמי שהונחה, אבל לא שהעקירה נחשבת מכל מקום שהוא!","\u0003אלא אמר רב יוסף: הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 שיטת \u0005מי היא]?\u0006 — שיטת \u0003רבי היא.\u0004","ושואלים: \u0003הי\u0004 \u0005[לאיזו]\u0006 הלכה שאמר \u0003רבי\u0004 מתכוון רב יוסף? \u0003אילימא הא\u0004 \u0005[אם תאמר\u0006 כי הכוונה היא להלכה \u0005זו]\u0006 של \u0003רבי, דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003זרק\u0004 אדם חפץ בשבת ברשות הרבים מתחילת ארבע אמות לסופן \u0003ונח\u0004 החפץ \u0003על גבי זיז כל שהוא\u0004 — \u0003רבי מחייב, וחכמים פוטרין.\u0004 ולכאורה אפשר להוכיח מכאן שלדעת רבי אין צורך למקום מסויים בגודלו לצורך עקירה והנחה. ואולי להלכה זו התכוון רב יוסף?!","ודוחים: \u0003התם כדבעינן למימר לקמן\u0004 \u0005[שם\u0006 הפירוש הוא \u0005כפי שנצטרך לומר הלאה]\u0006 \u0003כ\u0004דברי \u0003אביי.\u0004 ש\u0003אמר אביי: הכא\u0004 \u0005[כאן],\u0006 כלומר, אותה ברייתא אינה עוסקת בכל מצב אלא \u0003ב\u0004מקרה המיוחד כשהיה \u0003אילן העומד ברשות היחיד ו\u0004אילו \u0003נופו\u0004 (ענפיו) \u0003נוטה לרשות הרבים, וזרק\u0004 אדם חפץ מרשות הרבים \u0003ונח\u0004 החפץ על \u0003נופו\u0004 של האילן,","ש\u0003רבי סבר\u0004 \u0005[סבור]\u0006 כי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003\"שדי\u0004 \u0005[זרוק]\u0006 את \u0003נופו בתר\u0004 \u0005[אחר]\u0006 \u0003עיקרו\",\u0004 וחשוב כאילו היתה צמרתו של האילן המשך של גזעו, ולכן ייחשב האילן כולו כרשות היחיד, והזורק לתוכו — חייב. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003\"שדי\u0004 \u0005[זרוק]\u0006 את \u0003נופו בתר\u0004 \u0005[אחר]\u0006 \u0003עיקרו\",\u0004 ועל כן אין הנוף עצמו רשות היחיד, והזורק אליו מרשות הרבים — פטור. ומאחר שרבי מחשיב את הצמרת כחלק מן הגזע, הרי דבר הנזרק לצמרת נחשב כאילו הונח על הגזע, שיש בו מקום ארבעה על ארבעה. ואם כן אין ללמוד מכאן שלדבריו אין צורך בהנחה על מקום חשוב.","\u0003אלא\u0004 יתכן כי \u0003הא\u0004 \u0005[זו]\u0006 ההלכה אליה מתכוון רב יוסף, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם \u0003זרק\u0004 אדם בשבת חפץ \u0003מרשות הרבים לרשות הרבים ו\u0004היתה \u0003רשות היחיד באמצע\u0004 — \u0003רבי מחייב,\u0004 משום הוצאה מרשות לרשות, \u0003וחכמים פוטרין.\u0004","\u0003ואמר רב יהודה אמר שמואל:\u0004 במקרה זה \u0003מחייב היה רבי\u0004 את הזורק להביא \u0003שתים,\u0004 שני קרבנות חטאת, משום שהיו כאן שתי עבירות: \u0003אחת\u0004 — \u0003משום הוצאה\u0004 מרשות הרבים לרשות היחיד, בשעת מעברו של החפץ שם, \u0003ואחת\u0004 — \u0003משום הכנסה\u0004 מרשות היחיד לרשות הרבים, \u0003אלמא לא בעי\u0004 \u0005[מכאן,\u0006 ש\u0005אינו צריך]\u0006 \u0003עקירה ולא הנחה על גבי מקום ארבעה על ארבעה.\u0004 שהרי לא זו בלבד שחייב על הכנסת החפץ לרשות היחיד והנחתו בה בדרך קליטה באוירו, אלא חייב אף משום עקירת החפץ מרשות היחיד והבאתו לרשות הרבים, הרי שלדעת רבי אין צורך בעקירה והנחה במקום חשוב.","את הראייה הזו דוחים: \u0003הא איתמר עלה\u0004 \u0005[הרי נאמר עליה]\u0006 על מחלוקת זו כי \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006"],["\u0003לא מחייב\u0004 היה \u0003רבי אלא ברשות היחיד מקורה\u0004 (מכוסה בתקרה), \u0003דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003ביתא כמאן דמליא דמיא\u0004 \u0005[הבית כמי ש\u0006היה \u0005מלא\u0006 הוא \u0005נחשב],\u0006 כלומר, הבית כולו על חללו נחשב כיחידה אחת, וכל חלק ממנו כאילו היה ממולא בדברים ממשיים, וחפץ העובר דרך בית נחשב כאילו נח שם על שטח ממשי בן ארבעה על ארבעה טפחים לפחות. אבל ברשות היחיד \u0003שאינה מקורה\u0004 — \u0003לא\u0004 מחייב היה רבי.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכא נמי\u0004 \u0005[כאן\u0006 במשנתנו \u0005גם כן]\u0006 \u0003ב\u0004רשות היחיד \u0003מקורה\u0004 מדובר, ולכן העקירה וההנחה מעל היד נחשבות כנעשו במקום שיש בו ארבעה טפחים, ואולם \u0003התינח\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 \u0003ברשות היחיד מקורה\u0004, אבל \u0003ברשות הרבים מקורה מי\u0004 \u0005[האם]\u0006 \u0003חייב\u0004 כלל? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב שמואל בר יהודה\u0004 ש\u0003אמר ר' אבא\u0004 ש\u0003אמר רב הונא\u0004 ש\u0003אמר רב: המעביר חפץ ארבע אמות\u0004 ממקום למקום \u0003ברשות הרבים מקורה,\u0004 אף על פי שהעברת חפץ ארבע אמות ברשות הרבים אסורה מן התורה, כהוצאה מרשות לרשות, במקרה זה \u0003פטור;\u0004 וטעמו של דבר — \u0003לפי שאינו דומה\u0004 רשות הרבים המקורה \u0003לדגלי מדבר,\u0004 השטח שעברו בו מחנות (\"דגלי\") ישראל במדבר. כי הלכות מלאכות שבת נלמדות מן המלאכות שנעשו בבניית המשכן בעת חניית ישראל במדבר, והמדבר ודאי שלא היה מקורה. ומשום כך אי אפשר להסביר את משנתנו ברשות הרבים מקורה, אף לשיטת רבי.","\u0003אלא אמר ר' זירא:\u0004 יש למצוא מקור אחר למשנתנו, ולדעתו \u0003הא מני\u0004 \u0005[\u0006משנתנו \u0005זו\u0006 כדעת \u0005מי היא]?\u0006 — כדעת \u0003אחרים היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחרים אומרים: עמד\u0004 אדם \u0003במקומו\u0004 בשבת \u0003וקבל\u0004 חפץ שזרק לו אחר מרשות אחרת תוך כדי עמידתו — \u0003חייב\u0004 זורק החפץ משום מלאכת הוצאה, שהיתה כאן עקירה והנחה, ואולם אם \u0003עקר\u0004 המקבל \u0003ממקומו\u0004 ורץ לקראת החפץ \u0003וקבל\u0004 אותו בידו — \u0003פטור.\u0004 כי אף שעשה הזורק עקירה, מכל מקום הנחת החפץ תלויה היתה בפעולתו של המקבל, והיתה כאן איפוא מצד הזורק רק עקירה בלא הנחה. על כל פנים שנינו שלדעת אחרים אם \u0003עמד במקומו וקבל\u0004 — \u0003חייב\u0004 הזורק, ו\u0003הא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שתהא \u0003הנחה על גבי מקום ארבעה\u0004 על ארבעה טפחים \u0003וליכא\u0004 \u0005[ואין]\u0006 כאן! \u0003אלא\u0004 ודאי \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שלדעת אחרים \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיהא זה מקום ארבעה על ארבעה.","ודוחים: אין זו הוכחה, שכן יש לומר \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003הנחה הוא דלא בעינן\u0004 \u0005[שאין אנו צריכים]\u0006 שתהא, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003עקירה בעינן\u0004 \u0005[צריכים]\u0006 מקום ארבעה להחשיבה. \u0003ו\u0004אף \u0003הנחה נמי\u0004 \u0005[גם כן]\u0006 יש לומר כי \u0003דילמא\u0004 \u0005[שמא]\u0006 היה זה באופן \u0003דפשיט כנפיה\u0004 \u0005[שפשט\u0006 את \u0005כנפי\u0006 מעילו\u0005]\u0006 \u0003וקבלה דאיכא נמי\u0004 \u0005[ש\u0006בכגון זה \u0005יש גם כן]\u0006 \u0003הנחה\u0004 על מקום ארבעה. ואם כן, אין מכאן הוכחה כלל.","על כן, \u0003אמר ר' אבא: מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת באופן מיוחד, ו\u0003כגון שקבל בטרסקל\u0004 \u0005[סל],\u0006 \u0003ו\u0004כן כש\u0003הניח\u0004 היה זה מ\u0003על גבי טרסקל,\u0004 שבכגון זה \u0003איכא נמי\u0004 \u0005[יש גם כן]\u0006 \u0003הנחה\u0004 במקום ארבעה על ארבעה טפחים. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"ידו \" קתני\u0004 \u0005[שנינו],\u0006 וכיצד מפרש אתה שקבלו בטרסקל? על כך משיבים: תקן את גרסת המשנה ו\u0003תני\u0004 \u0005[שנה,\u0006 גרוס\u0005]\u0006 \u0003\"טרסקל שבידו\".\u0004","ושואלים לגופו של דבר: \u0003התינח\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 כשהיה ה\u0003טרסקל ברשות היחיד, אלא\u0004 אם היה \u0003טרסקל ש\u0004מונח \u0003ברשות הרבים\u0004 הלא מיד ל\u0003רשות היחיד הוא\u0004 נעשה, שהרי מן הסתם גבוה הוא מן הקרקע עשרה טפחים, ויש בראשו שיעור השטח הדרוש ליצירת רשות היחיד.","ומאחר שאיננו אומרים כן, \u0003לימא\u0004 \u0005[נאמר]\u0006 שתהא זו הוכחה שמשנתנו ש\u0003לא כ\u0004שיטת \u0003ר' יוסי בן יהודה\u0004 היא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר: נעץ קנה ברשות הרבים ובראשו\u0004 תלה \u0003טרסקל\u0004 ו\u0003זרק\u0004 חפץ מרשות הרבים \u0003ונח\u0004 החפץ \u0003על גביו\u0004 — \u0003חייב,\u0004 משום שהוציא מרשות הרבים והכניס לרשות היחיד. שכן מאחר ושטח הטרסקל ארבעה על ארבעה טפחים והוא גבוה למעלה מעשרה טפחים, הריהו נחשב בשל כך לרשות היחיד. ואף כי הקנה המשמש בסיסו של טרסקל זה אינו רחב ארבעה, מכל מקום, מאחר שהטרסקל רחב דיו, אנו מדמים כאילו היו מחיצות הסל יורדות בקו ישר למטה, ואם כן נוצר כעין עמוד של רשות היחיד המצוי ברשות הרבים.","ומשנתנו אינה כשיטת ר' יוסי בר' יהודה, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי בר' יהודה\u0004 היא, הרי כש\u0003פשט בעל הבית את ידו לחוץ ונתן לתוך ידו\u0004 (ולענייננו — לטרסקל שבידו) \u0003של עני\u0004 הנמצא ברשות הרבים \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב?\u0004 והרי לשיטה זו הטרסקל נחשב כרשות היחיד ובעל הבית רק \u0003מרשות היחיד לרשות היחיד קא מפיק\u0004 \u0005[הוא מוציא]!\u0006 והרי זו הוכחה איפוא שאין שיטת משנתנו כשיטת ר' יוסי בר' יהודה.","על כך משיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כי שיטת \u0003ר' יוסי בר' יהודה\u0004 היא משנתנו, ואולם \u0003התם\u0004 \u0005[שם]\u0006 ששנינו שהטרסקל נחשב כרשות היחיד, הרי זה כשהיה \u0003למעלה מעשרה\u0004 טפחים, \u0003הכא\u0004 \u0005[כאן]\u0006 במשנתנו, היה הטרסקל \u0003למטה מעשרה\u0004 טפחים, ואף לשיטת ר' יוסי בר' יהודה בכגון זה אינו נחשב כרשות היחיד והריהו איפוא חלק מרשות הרבים, ולכן נחשבת זו כהוצאה, וחייב.","ומעירים: אף על פי כן, \u0003קשיא ליה\u0004 \u0005[קשה\u0006 היה \u0005לו]\u0006 \u0003לר' אבהו\u0004 על דרך ביאור זו: \u0003מי קתני\u0004 \u0005[האם שנינו]\u0006 לשון \u0003\"טרסקל שבידו \"? והא\u0004 \u0005[והרי]\u0006 \u0003\"ידו \" קתני\u0004 \u0005[שנינו],\u0006 ואין לנו סיבה לתקן כך את המשנה! \u0003אלא אמר ר' אבהו:\u0004 יש לומר שמדובר פה ב\u0003כגון ש\u0004בכל מקרה \u0003שלשל\u0004 המקבל את \u0003ידו למטה משלשה\u0004 טפחים מן הקרקע \u0003וקבלה\u0004 לאותו חפץ בידו. שלמטה משלושה טפחים נחשב לכל דבר כאילו היה צמוד לקרקע ולכן גם כמקום ארבעה על ארבעה.","על כך שואלים: \u0003והא\u0004 \u0005[והרי]\u0006 לשון \u0003\"עומד\" קתני\u0004 \u0005[שנינו]\u0006 (\"העני עומד בחוץ\")\u0005,\u0006 וכיצד יתכן שיהא העני עומד, ועם זאת ידו סמוכה שלושה טפחים לקרקע? על כך ענה ר' אבהו: מדובר כאן \u0003ב\u0004אופן שהוא \u0003שוחה\u0004 (מתכופף), שבכגון זה הוא גם עומד וגם ידו מגיעה סמוך לקרקע. \u0003ואיבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שאפשר לתאר דבר זה באופן שעומד העני \u0003ב\u0004תוך \u0003גומא\u0004 ובכגון זה יכולה ידו להיות סמוכה לקרקע. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תיאור אחר של המצב, שהמדובר היה \u0003בננס,\u0004 שאף בעמידה ידיו מגיעות שלושה טפחים סמוך לקרקע.","על כל אלה \u0003אמר רבא:\u0004 וכי \u0003איכפל\u0004 \u0005[התאמץ]\u0006 ה\u0003תנא לאשמעינן\u0004 \u0005[להשמיענו]\u0006 \u0003כל הני\u0004 \u0005[אלה]?!\u0006 כי קשה להניח שלא מצא התנא דרך אחרת להסביר את ההלכה שלא באופן יוצא דופן. \u0003אלא אמר רבא:\u0004 יש לפתור את הבעיה מתוך קביעת הכלל כי \u0003ידו של אדם חשובה לו כארבעה על ארבעה\u0004 טפחים. כי אמנם דרושה עקירה והנחה מעל גבי מקום בעל חשיבות, ואף שכרגיל אין מקום חשוב בפחות מארבעה טפחים, בכל זאת ידו של אדם חשובה למדי עבורו כדי להוות מקום חשוב לגבי הלכות שבת. \u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: ידו של אדם חשובה לו ארבעה על ארבעה\u0004 טפחים.","אמר \u0003ר' אבין אמר ר' אילעאי אמר ר' יוחנן: זרק חפץ ונח בתוך ידו של חבירו\u0004 המצוי ברשות אחרת — \u0003חייב.\u0004 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו],\u0006 איזה עקרון הלכתי יש בדבר זה? — ש\u0003ידו של אדם חשובה לו כארבעה על ארבעה? ו\u0004אולם, \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמרה ר' יוחנן חדא זימנא\u0004 \u0005[פעם אחת]!\u0006 ולשם מה חזר עליו אף כי בשינוי צורה? ומשיבים: בכל זאת נחוץ היה להשמיע גם את ההלכה שמסר ר' אילעאי, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שידו של אדם חשובה, אמורים דווקא \u0003היכא דאחשבה\u0004 \u0005[היכן שהחשיב אותה]\u0006 \u0003הוא\u0004 עצמו \u0003לידיה\u0004 \u0005[את ידו],\u0006 ולקח או הניח את החפץ בידו. \u0003אבל היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא אחשבה\u0004 \u0005[החשיב אותה]\u0006 \u0003הוא לידיה\u0004 \u0005[את ידו]\u0006 אלא נפל החפץ (נח) בידו של אחר בלא שיתכוון לכך — \u0003אימא\u0004 \u0005[הייתי אומר]\u0006 כי בכגון זה \u0003לא\u0004 נחשבת ידו כמקום חשוב ולא יתחייב, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שחשיבותה של היד היא מוחלטת ואינה תלויה בכוונת עושה הפעולה.","ועוד \u0003אמר ר' אבין אמר ר' אילעאי אמר ר' יוחנן: עמד\u0004 אדם \u0003במקומו וקיבל\u0004 חפץ שנזרק לו מרשות אחרת — \u0003חייב.\u0004 ואולם אם \u0003עקר ממקומו וקיבל\u0004 אז את החפץ — \u0003פטור.\u0004 ואכן, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003אחרים אומרים:\u0004 אם \u0003עמד במקומו וקיבל\u0004 בידו את החפץ שנזרק מרשות אחרת — \u0003חייב.\u0004 ואם \u0003עקר ממקומו וקיבל\u0004 אותו — \u0003פטור.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יוחנן\u0004 בהסתמך על כך: אם \u0003זרק חפץ\u0004 מרשות אחת \u0003ונעקר הוא ממקומו\u0004 ורץ לרשות אחרת \u0003וחזר וקיבלו\u0004 לאותו חפץ בידו ברשות השניה — \u0003מהו\u0004 דינו?","להבהרת הענין שואלים: \u0003מאי קמבעיא ליה\u0004 \u0005[מה נשאלה לו]?\u0006 כלומר, מה הוא צד הספק בבעיה זו? שהרי לכאורה עשה אותו אדם עקירה והנחה בשלימותן! \u0003אמר רב אדא בר אהבה:\u0004 ענין \u0003\"שני כחות באדם אחד \" קא מבעיא ליה\u0004 \u0005[נשאלה לו].\u0006 שאם עשה אדם פעולה לא בהמשך אחד, כי אם כשתי פעולות נפרדות, הסתפק ר' יוחנן מה דינו, האם \u0003שני כחות באדם אחד\u0004 בכל זאת \u0003כאדם אחד דמי\u0004 \u0005[נחשבים],\u0006 \u0003וחייב, או דילמא\u0004 \u0005[שמא]\u0006 \u0003כשני בני אדם דמי\u0004 \u0005[נחשבים],\u0006 \u0003ופטור.\u0004 לשאלה זו לא נמצאה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ועוד \u0003אמר ר' אבין אמר ר' יוחנן:\u0004 מי ש\u0003הכניס ידו לתוך חצר חבירו וקיבל מי גשמים\u0004 שיורדים באותה שעה בתוך ידו \u0003והוציא\u0004 אותם לרשות אחרת — \u0003חייב. מתקיף\u0004 \u0005[מקשה]\u0006 על כך \u0003ר' זירא: מה לי\u0004 אם \u0003הטעינו חבירו,\u0004 שהניח חבירו חפץ בתוך ידו, ו\u0003מה לי\u0004 אם \u0003הטעינו שמים\u0004 במי גשם, הרי \u0003איהו\u0004 \u0005[הוא]\u0006 \u0003לא עביד\u0004 \u0005[עשה]\u0006 \u0003עקירה,\u0004 ומדוע יתחייב בשל כך כמוציא מרשות לרשות?! ומשיבים: \u0003לא תימא\u0004 \u0005[אל תאמר,\u0006 תגרוס\u0005]\u0006 לשון \u0003\"קיבל\u0004 מי גשמים \u0003\",\u0004 וכמשמעות לשון זו שקיבל בידו והוא לא מאומה, \u0003אלא\u0004 גרוס \u0003\"קלט\u0004 מי גשמים \u0003\",\u0004 שאסף את מי הגשמים בידו מן האויר, והרי זו כעקירה. על כך שואלים: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 כדי להתחייב שתהיה ה\u0003עקירה מעל גבי מקום ארבעה\u0004 טפחים, \u0003וליכא\u0004 \u0005[ואינה]!\u0006 וכיצד איפוא יתחייב?","\u0003אמר ר' חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא: כגון שקלט מעל גבי\u0004 ובצד \u0003הכותל,\u0004 ואם כן עקר ממקום חשוב, ולכן הדבר נחשב לעקירה, וחייב. על כך שואלים: \u0003על גבי כותל נמי\u0004 \u0005[גם כן],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא נח\u0004 דבר, אלא גולש והולך מיד, ואם כן — לא היתה עקירה מן הכותל כלל. ומשיבים שהמקרה היה \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רבא\u0004 בענין אחר, שהמדובר הוא \u0003בכותל משופע,\u0004 ואם כן יש לומר כי \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בכותל משופע.\u0004 ואומרים: \u0003והיכא איתמר\u0004 \u0005[והיכן נאמר]\u0006 דבר זה של \u0003רבא\u0004 — \u0003אהא דתנן\u0004 \u0005[על זה ששנינו\u0006 במשנתנו\u0005]:\u0006"],["\u0003היה\u0004 אדם \u0003קורא\u0004 בשבת בספר מספרי הקודש ויושב \u0003על האיסקופה\u0004 (מפתן בית גבוה ורחב) \u0003ונתגלגל הספר מידו\u0004 החוצה לרשות הרבים, וספר זה עשוי היה כמגילה — \u0003גוללו אצלו,\u0004 מותר לו לגלול את הספר בחזרה אליו, מאחר שקצהו האחד עדיין נשאר בידו. אך אם \u0003היה קורא בראש הגג,\u0004 שהוא רשות היחיד גמורה, \u0003ונתגלגל הספר מידו, עד שלא הגיע\u0004 קצה הספר \u0003לעשרה טפחים\u0004 מעל רשות הרבים עדיין נמצא הספר בתחום לעצמו, ומותר לו ל\u0003גוללו אצלו.\u0004 ואולם \u0003משהגיע\u0004 הספר \u0003לעשרה טפחים\u0004 התחתונים שבתוך תחום רשות הרבים — אסור לו לגוללו אליו, ולכן אך \u0003הופכו על הכתב,\u0004 שכתב הספר יפנה פנימה ולא יהא גלוי ומונח בבזיון. \u0003והוינן\u0004 \u0005[והיינו עוסקים,\u0006 תמהים\u0005]\u0006 \u0003בה,\u0004 בהלכה זו: \u0003אמאי\u0004 \u0005[מדוע]\u0006 צריך שיהא \u0003הופכו על הכתב,\u0004 ואסרו עליו להחזיר את הספר אצלו? \u0003והא\u0004 \u0005[והרי]\u0006 עדיין \u0003לא נח\u0004 הספר על דבר מסוים ברשות הרבים, ואף אם יחזירהו לא יהא בכך משום עקירה!","\u0003ו\u0004על כך \u0003אימור\u0004 \u0005[אמר]\u0006 \u0003רבא:\u0004 מדובר כאן \u0003בכותל משופע,\u0004 שמתוך שהוא משופע נח עליו הספר במידה מסויימת. אך תשובה זו עדיין אינה מספקת כדי להסביר את ענין קליטת המים, כי \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר רבא\u0004 שדין הכותל המשופע שונה דווקא \u0003בספר, דעביד דנייח\u0004 \u0005[ש\u0006הוא \u0005עשוי לנוח]\u0006 על גביו, ואולם \u0003מים מי עבידי דנייחי\u0004 \u0005[האם עשויים\u0006 הם \u0005לנוח]\u0006 בכותל משופע?! ואם כן השאלה הראשונה ביחס למים עדיין במקומה עומדת.","\u0003אלא אמר רבא:\u0004 כאן מדובר ב\u0003כגון שקלט\u0004 את מי הגשמים \u0003מעל גבי גומא\u0004 מלאה מים. על כך שואלים: אם קלט אותם מעל גבי \u0003גומא\u0004 הלא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שנחשב הדבר כקליטה ממקום חשוב! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי מאחר והמים היורדים מן הגג לתוך הגומא \u0003מים על גבי מים\u0004 הם ושמא בשל כך \u0003לאו\u0004 \u0005[לא]\u0006 בכלל \u0003הנחה הוא,\u0004 על כן השמיע לנו שקליטת מים מעל גבי גומא מלאה מים נחשבת כעקירה ממקום הנחתם.","ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003רבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 שכבר \u0003אמר רבא:\u0004 הדבר פשוט כי \u0003מים על גבי מים\u0004 — \u0003היינו\u0004 \u0005[זוהי]\u0006 \u0003הנחתן,\u0004 ועקירתם משם — עקירה היא לכל דבר. וכן ברור כי \u0003אגוז\u0004 הצף \u0003על גבי מים\u0004 — \u0003לאו היינו\u0004 \u0005[אין זו]\u0006 בכלל \u0003הנחתו,\u0004 ולפיכך עקירתו משם אינה נחשבת כעקירה. ואולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 מקרה בו היה \u0003אגוז\u0004 מצוי \u0003ב\u0004תוך \u0003כלי, ו\u0004אותו \u0003כלי צף על גבי מים,\u0004 ועקר אדם את האגוז מן הכלי, האם תיחשב זאת לעקירה? וצדדי השאלה: האם \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003אגוז אזלינן\u0004 \u0005[הולכים אנו]\u0006 ורק לפי מצבו תיקבע ההלכה, והוא הלא הוא מונח בתוך הכלי, \u0003והא נייח\u0004 \u0005[והרי\u0006 הוא \u0005נח],\u0006 \u0003או דילמא בתר\u0004 \u0005[שמא אחר]\u0006 ה\u0003כלי אזלינן\u0004 \u0005[הולכים אנו]\u0006 \u0003והא\u0004 \u0005[וזה,\u0006 הכלי\u0005]\u0006 הלא \u0003לא נייח\u0004 \u0005[נח],\u0006 שכן בהיותו על גבי המים הוא \u0003דנייד\u0004 \u0005[שנד]\u0006 ממקום למקום על גביהם. לשאלה זו לא נמצא פתרון ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","בעיה דומה לזו, ביחס ל\u0003שמן שצף על גבי יין,\u0004 וכידוע אין השמן מתערב ביין אלא צף עליו בשכבה שלמה, תלוי הדבר ב\u0003מחלוקת ר' יוחנן בן נורי ורבנן\u0004 \u0005[וחכמים],\u0006 האם נחשב השמן כגוף זר המונח על היין או שמא הריהו כמחובר לו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שמן שצף על גבי יין ונגע טבול יום\u0004 (אדם שנטמא וטבל אחר כך, שיש בו עוד טומאה קלושה עד הערב שמש, שהוא מטמא משקים שנגע בהם, אבל אותם משקים שוב אינם יכולים לטמא דבר אחר) \u0003בשמן\u0004 — \u0003לא פסל אלא\u0004 את ה\u0003שמן בלבד\u0004 ולא את היין, שהרי רק בשמן נגע ואין השמן מטמא. \u0003ור' יוחנן בן נורי אומר: שניהם\u0004 נחשבים ל\u0003מחוברים זה לזה,\u0004 ולכן נטמאו שניהם כאחד באותו מגע. ואותם שיקולים עצמם אם השמן והיין מחוברים קובעים גם לגבי דיני שבת.","ועוד \u0003אמר ר' אבין אמר ר' אילעאי אמר ר' יוחנן: היה\u0004 אדם עומד בשבת ברשות היחיד או הרבים והוא \u0003טעון אוכלים ומשקין,\u0004 וכוונתו היתה להעבירם לפינה אחרת באותה רשות, ומכיון שהלך נמלך ויצא אל מחוץ לאותה רשות, \u0003ו\u0004הוא \u0003נכנס ויוצא\u0004 מרשות לרשות אפילו \u0003כל היום כולו\u0004 — \u0003אינו חייב\u0004 מן התורה משום הוצאה בשבת \u0003עד שיעמוד,\u0004 שהטלטול הזה אינו נחשב להוצאה, כיון שלא נתכוון מתחילה לעקור את עצמו על מנת להוציא. ולכן רק לאחר שיעמוד ובכך ייחשב הדבר להנחה ממש, ולאחר מכן יעקור שוב וילך, יוכל לבוא לידי חיוב.","על כך הוסיף ו\u0003אמר אביי: והוא\u0004 דווקא \u0003שעמד\u0004 אותו אדם \u0003לפוש\u0004 \u0005[לנוח],\u0006 ואז נחשב הדבר להנחה. אבל אם עמד לתקן משאו — אין זה נחשב להנחה. ומעירים: \u0003ממאי\u0004 \u0005[ממה]\u0006 הוציא אביי מסקנה זו — \u0003מ\u0004מה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בדיני טלטול ברשות הרבים. ששנינו שאף שמן התורה המעביר בשבת חפץ ארבע אמות ברשות הרבים — חייב, מכל מקום אמרו ש\u0003אם\u0004 ב\u0003תוך\u0004 העברת החפץ ב\u0003ארבע אמות עמד לפוש\u0004 \u0005[לנוח]\u0006 — \u0003פטור,\u0004 שכיון שעמד לנוח — עשה הנחה באמצע, ולא היו ארבע אמות שלמות. ואולם אם עמד \u0003לכתף\u0004 (לישר את המשא על כתיפו) — \u0003חייב,\u0004 שאין עמידה לצורך כיתוף נחשבת להנחה, ואולם היא נחשבת כאחד מצרכי טלטול המשא. ואילו לאחר שהלך מ\u0003חוץ\u0004 לתחום \u0003ארבע אמות,\u0004 אם \u0003עמד לפוש\u0004 \u0005[לנוח]\u0006 — בכך עשה הנחה וסיים את מלאכתו, ו\u0003חייב.\u0004 אבל אם עמד \u0003לכתף\u0004 — \u0003פטור\u0004 עד שינוח. ומהלכה זו למד אביי שרק עמידה לפוש נחשבת להנחה לענין העברה בשבת.","על עיקרה של ההלכה שאמר ר' יוחנן בנכנס ויוצא כל היום, שואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה,\u0006 איזה עקרון, \u0005השמיע לנו]\u0006 בהלכה זו? — את הכלל שאין אדם מחויב על מלאכת הוצאה בשבת כ\u0003שלא היתה עקירה\u0004 של החפץ ממקומו \u0003משעה ראשונה\u0004 שעקרו \u0003לכך,\u0004 כלומר, לצורך הוצאה, אלא למטרה אחרת. ואולם \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמרה ר' יוחנן חדא זימנא\u0004 \u0005[פעם אחת],\u0006 ש\u0003אמר רב ספרא אמר ר' אמי אמר ר' יוחנן: המעביר חפצים מזוית לזוית\u0004 בתוך רשות היחיד, \u0003ונמלך עליהן\u0004 תוך כדי טלטול \u0003והוציאן\u0004 לרשות הרבים — \u0003פטור, שלא היתה עקירה משעה ראשונה לכך,\u0004 לצורך הוצאה לרשות אחרת. ומדוע אם כן חזר שנית ושנה אותה הלכה? ומשיבים: \u0003אמוראי נינהו\u0004 \u0005[אמוראים\u0006 שונים \u0005הם]\u0006 שמסרו דבר זה, \u0003מר\u0004 \u0005[חכם זה]\u0006 \u0003אמר לה בהאי לישנא\u0004 \u0005[אותה בלשון זו],\u0006 \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003אמר לה בהאי לישנא\u0004 \u0005[אותה בלשון זו,\u0006 אחרת\u0005],\u0006 ושניהם לא באו אלא לנסח את הכלל שקבע ר' יוחנן פעם אחת.","מאחר שהוזכרה קודם הבעיה הקשורה בהפסקות שעושה אדם בתוך מלאכת ההוצאה, מוסיפים לדון במקרה מורכב יותר הקשור בבעיה זו. \u0003תנו רבנן\u0004 \u0005[שנו\u0006 חכמים] בברייתא: \u0003המוציא\u0004 מן ה\u0003חנות,\u0004 שהיא רשות היחיד, \u0003לפלטיא\u0004 \u0005[רחבה,\u0006 כיכר\u0005],\u0006 שהיא רשות הרבים, \u0003דרך סטיו\u0004 \u0005[שדרות עמודים]\u0006 שבין החנות לבין רשות הרבים ודינו ככרמלית — \u0003חייב,\u0004 שהרי הוציא מרשות היחיד לרשות הרבים. \u0003ובן עזאי פוטר.\u0004","ומבררים את השיטות: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003בן עזאי,\u0004 שכן \u0003קסבר\u0004 \u0005[הוא סובר]\u0006 כי \u0003מהלך כעומד דמי\u0004 \u0005[נחשב],\u0006 שכאילו הוא עומד בכל פסיעה ופסיעה, ולכן, מאחר שהלך דרך הסטיו שאינו לא רשות הרבים ולא רשות היחיד — הרי בתוך הילוכו נח שם, ואם כן לא הוציא מרשות היחיד לרשות הרבים אלא הוציא לכרמלית וממנה. \u0003אלא רבנן\u0004 \u0005[חכמים],\u0006 \u0003נהי נמי דקסברי\u0004 \u0005[אם אמנם גם כן הם סבורים]\u0006 כי \u0003מהלך לאו\u0004 \u0005[לא]\u0006 \u0003כעומד דמי\u0004 \u0005[נחשב],\u0006 בכל זאת אין שיטתם מובנת, כי \u0003היכא אשכחנא כהאי גוונא\u0004 \u0005[היכן מצאנו בכגון זה]\u0006 ש\u0003חייב?\u0004 שהרי אין כאן העברה מרשות לרשות במישרין אלא דרך מקום שאין בו איסור מן התורה. והיכן מצאנו שחייבה התורה בהוצאה מסוג זה?","\u0003אמר ר' ספרא אמר ר' אמי אמר ר' יוחנן:\u0004 אין זה מקרה יוצא דופן,"],["\u0003מידי דהוה\u0004 \u0005[כדבר שהוא]\u0006 בדין ה\u0003מעביר חפץ ברשות הרבים. התם, לאו אף על גב\u0004 \u0005[שם, האם לא אף על פי]\u0006 שכל \u0003כמה דנקיט ליה ואזיל\u0004 \u0005[ש\u0006הוא \u0005לוקח אותו והולך]\u0006 \u0003פטור\u0004 הוא, כל עוד לא הניח את החפץ, ובכל זאת \u0003כי מנח ליה\u0004 \u0005[כאשר\u0006 הוא \u0005מניח\u0006 \u0005אותו]\u0006 — \u0003חייב.\u0004 נמצא שבין מקום העקירה ומקום ההנחה שיש בו חיוב, משתרע שטח שגודלו אינו מוגדר שבו יכול הוא להמשיך את הליכתו, וכל עוד הוא מהלך הריהו פטור. ואם כן, \u0003הכא נמי לא שנא\u0004 \u0005[כאן גם כן אינו שונה],\u0006 שבשני המקרים קיים אותו מצב: אם יניח את החפץ באמצע דרכו — יתחייב, ואילו השטח שבאמצע איננו מקום חיוב.","השוואה זו דוחים: \u0003מי דמי\u0004 \u0005[האם זה דומה]?!\u0006 שכן \u0003התם כל היכא דמנח ליה\u0004 \u0005[מקום ש\u0006הוא \u0005מניח אותו,\u0006 את החפץ\u0005]\u0006 הלא \u0003מקום חיוב הוא,\u0004 ואין לדבר על שני מקומות של חיוב שיש ביניהם שטח של פטור, כי גם שטח הביניים הוא מקום חיוב לכשיניח בו את החפץ. ואילו \u0003הכא, אי מנח ליה\u0004 \u0005[כאן, אם מניח אותו]\u0006 \u0003בסטיו\u0004 הלא \u0003מקום פטור הוא\u0004 במוחלט. ושוב חוזרת השאלה: היכן מצאנו מקרה שבו יהיה חיוב בהעברת חפץ דרך מקום שאין בו חיוב.","\u0003אלא\u0004 יתכן להביא דוגמה אחרת: \u0003מידי דהוה\u0004 \u0005[כדבר שהוא]\u0006 בדין ה\u0003מעביר חפץ\u0004 ברשות הרבים \u0003מתחלת ארבע\u0004 אמות בדיוק \u0003לסוף ארבע\u0004 אמות. \u0003התם לאו אף על גב דאי מנח ליה\u0004 \u0005[שם, האם לא אף על פי שאם מניח אותו]\u0006 \u0003בתוך ארבע אמות\u0004 הוא \u0003פטור,\u0004 שבפחות מארבע אמות לא נעשתה מלאכה שלמה של העברה ברשות הרבים, \u0003כי מנח ליה בסוף ארבע אמות חייב, הכא נמי לא שנא\u0004 \u0005[כאן גם כן אינו שונה],\u0006 ויש לומר כי קיימת רצועה מסויימת של מקום פטור בין העקירה וההנחה.","ושוב דוחים: \u0003מי דמי\u0004 \u0005[האם זה דומה]?!\u0006 \u0003התם\u0004 \u0005[שם],\u0006 ברשות הרבים \u0003לגבי דהאי גברא\u0004 \u0005[אותו אדם]\u0006 הלא \u0003מקום פטור הוא,\u0004 שכן טלטל פחות מארבע אמות, ואולם \u0003לכולי עלמא\u0004 \u0005[לכל העולם,\u0006 לשאר בני אדם\u0005]\u0006 הלא \u0003מקום חיוב הוא,\u0004 שהמקום עצמו הוא רשות הרבים ואדם אחר שהניח בו בסוף ארבע אמות יהיה חייב. ואילו \u0003הכא לכולי עלמא\u0004 \u0005[כאן\u0006 הסטיו הלא \u0005לכל\u0006 \u0005העולם]\u0006 \u0003מקום פטור הוא,\u0004 ואין להשוות פטור הנובע מחוסר השלמתה של המלאכה, לפטור מוחלט התלוי בטיבו של המקום.","\u0003אלא\u0004 יתכן להביא דוגמה אחרת: \u0003מידי דהוה\u0004 \u0005[כדבר שהוא]\u0006 בדין ה\u0003מוציא\u0004 חפץ \u0003מרשות היחיד לרשות הרבים דרך צדי רשות הרבים,\u0004 שהיא רצועה צרה הנמצאת ברשות הרבים בסמוך לבתים ואין הרבים מצויים בה. \u0003התם לאו אף על גב דאי מנח ליה\u0004 \u0005[שם האם לא אף על פי שאם מניח אותו,\u0006 את החפץ\u0005]\u0006 ב\u0003צדי רשות הרבים\u0004 — \u0003פטור, ו\u0004בכל זאת \u0003כי מנח ליה\u0004 \u0005[כאשר מניח אותו]\u0006 \u0003ברשות הרבים\u0004 — \u0003חייב,\u0004 ואם כן, \u0003הכא נמי לא שנא\u0004 \u0005[כך גם כאן אינו שונה].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך],\u0006 על הסבר זה \u0003רב פפא: הניחא לרבנן דאמרי\u0004 \u0005[זה נוח,\u0006 מובן \u0005ל\u0006שיטת \u0005חכמים האומרים]\u0006 כי \u0003צדי רשות הרבים לאו\u0004 \u0005[לא]\u0006 \u0003כרשות הרבים דמי\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 אלא לדעתם הם מעין רשות לעצמה, הרי דומה הדוגמה לענייננו. \u0003אלא ל\u0004שיטת \u0003ר' אליעזר בן יעקב\u0004 ש\u0003אמר\u0004 ש\u0003צדי רשות הרבים כרשות הרבים\u0004 ממש \u0003דמי\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: אימור\u0004 \u0005[אמור]\u0006 ש\u0003שמעת\u0004 את \u0003ר' אליעזר בן יעקב\u0004 ש\u0003אמר\u0004 ש\u0003צדי רשות הרבים כרשות הרבים דמי\u0004 \u0005[נחשבים]\u0006 רק \u0003היכא דליכא חיפופי\u0004 \u0005[במקום שאין יתידות]\u0006 המשמשות להפריד בין הבתים והחצרות ובין רשות הרבים עצמה, כדי שלא יזיקו הרבים לכותלי הבתים. \u0003אבל היכא דאיכא חיפופי מי שמעת ליה\u0004 \u0005[במקום שיש יתידות האם שמעת אותו]\u0006 שגם בכגון זה דינם שונה מזה של רשות הרבים עצמה? \u0003הלכך להא דמיא\u0004 \u0005[לזה\u0006 הוא \u0005דומה]\u0006 ויש, איפוא, בידינו דוגמה נוספת של חיוב בהוצאה דרך מקום פטור.","\u0003אמר ר' יוחנן:\u0004 אף על פי שחלק בן עזאי לגבי הוצאת החפץ דרך הסטיו בדרך הילוך ולדעתו המוציא פטור — \u0003מודה בן עזאי\u0004 לחכמים \u0003ב\u0004דין אדם ה\u0003זורק\u0004 חפץ מרשות היחיד לרשות הרבים דרך הסטיו שהוא חייב, שכן הרי זה כהוצאה ישירה מרשות לרשות. ואכן, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003המוציא\u0004 בשבת חפץ \u0003מחנות לפלטיא דרך סטיו\u0004 — \u0003חייב.\u0004 ודין זהה לכל דרכי ההעברה מרשות לרשות בדרך זו, \u0003אחד המוציא, ואחד המכניס, ואחד הזורק, ואחד המושיט\u0004 בידו מרשות לרשות. \u0003בן עזאי אומר: המוציא והמכניס\u0004 בדרך הילוכו \u0003פטור,\u0004 שכן נחשב כאילו עמד לנוח בסטיו, ואילו \u0003המושיט והזורק,\u0004 שפעולתם ללא הפסקה — \u0003חייב.\u0004","כדי לבאר את עיקר דיני רשויות השבת מביאים את \u0003מה שתנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא שאמרו חכמים \u0003ארבע רשויות\u0004 הן \u0003ל\u0004ענין דיני ה\u0003שבת: רשות היחיד, ורשות הרבים, ו\u0004עוד שתי רשויות נוספות: \u0003כרמלית\u0004 שאינה לא כרשות הרבים ולא כרשות היחיד, \u0003ומקום פטור\u0004 שאינו נחשב בכלל הרשויות.","והדברים מפורטים: \u0003ואיזו היא רשות היחיד?\u0004 — \u0003חריץ\u0004 (תעלה) \u0003שהוא עמוק עשרה\u0004 טפחים \u0003ורחב ארבעה, וכן גדר שהוא גבוה עשרה\u0004 טפחים \u0003ורחב ארבעה\u0004 — \u0003זו היא רשות היחיד גמורה.\u0004","שתנאי רשות היחיד הם, שיהיה שטח של ארבעה על ארבעה טפחים, והבדל גובה של עשרה טפחים מן הסביבה המקפת, \u0003ואיזו היא רשות הרבים? סרטיא\u0004 \u0005[רחוב ראשי],\u0006 \u0003ופלטיא\u0004 \u0005[ככר]\u0006 \u0003גדולה, ו\u0004כן \u0003מבואות\u0004 (סמטאות) שבין הרחובות הגדולים שהם \u0003מפולשין\u0004 \u0005[פתוחים]\u0006 משני הצדדים אל רשות הרבים — \u0003זו היא רשות הרבים גמורה.\u0004 ובענין זה: \u0003אין מוציאין מרשות היחיד\u0004 כגון \u0003זו לרשות הרבים\u0004 כגון \u0003זו, ואין מכניסין מרשות הרבים\u0004 כגון \u0003זו לרשות היחיד\u0004 כגון \u0003זו,\u0004 אם היה זה \u0003בשוגג\u0004 — \u0003חייב\u0004 להביא קרבן \u0003חטאת,\u0004 ואם היה זה \u0003במזיד\u0004 ולא היו עדים למעשהו ובשל כך אף לא התרו בו — הריהו \u0003ענוש כרת,\u0004 ואם התרו בו שלא יעבור והיו לכך עדים — הרי הוא \u0003נסקל.\u0004","\u0003אבל ים ובקעה\u0004 (שדה) \u0003ואיסטוונית\u0004 (סטיו, שדרות עמודים וכדומה) \u0003והכרמלית\u0004 — הרי כל אלה נכנסים לסוג הכללי המכונה \"כרמלית\" ו\u0003אינה לא כרשות הרבים,\u0004 משום שאין רבים מצויים שם, \u0003ולא כרשות היחיד,\u0004 שכן אין להם מחיצות. אלא קבעו חכמים שייחשבו כרשות לעצמה, לענין \u0003אין נושאין ונותנין בתוכה\u0004 בתוך ארבע אמות, כדרך שאסור לעשות זאת ברשות הרבים. \u0003ואם\u0004 עבר \u0003ונשא ונתן בתוכה\u0004 — \u0003פטור,\u0004 שהרי אין הדבר אסור מן התורה. \u0003ו\u0004כן \u0003אין מוציאין מתוכה לרשות הרבים ולא מרשות הרבים לתוכה,\u0004 שהרי אינה כרשות הרבים. \u0003ו\u0004אף \u0003אין מכניסין מרשות היחיד לתוכה ולא מתוכה לרשות היחיד,\u0004 שהרי אינה רשות היחיד. \u0003ואם\u0004 עבר ו\u0003הוציא\u0004 או ש\u0003הכניס\u0004 — \u0003פטור,\u0004 שהרי אין בכך איסור תורה. בדומה לכך מוסבר עוד כי יש סוג של רשות היחיד אשר מדברי סופרים נהגו בו כאילו היה כרמלית או רשות הרבים.","כי \u0003חצרות של רבים\u0004 וכן \u0003מבואות שאינן מפולשין\u0004 \u0005[פתוחים]\u0006 משני צידיהם, כיון שנמצאים בהם אנשים רבים, דומים הם במקצת לרשות הרבים וגזרו איסור על טלטול בתוכם אלא אם כן \u0003עירבו\u0004 (עירוב חצרות או שיתוף מבואות) ועל ידי כך צירפו את החצרות השונות לחצר אחת, שבכגון זה \u0003מותרין\u0004 כולם להכניס לתוכה חפצים מן הבתים. ואולם אם \u0003לא עירבו\u0004 — \u0003אסורים.\u0004","ואילו כדוגמה לרשות הרביעית (\"מקום פטור\"), מתואר: \u0003אדם עומד על האיסקופה\u0004 \u0005[מפתן הדלת]\u0006 ו\u0003נוטל\u0004 חפץ \u0003מבעל הבית\u0004 העומד ברשות היחיד \u0003ו\u0004כן אם \u0003נותן לו.\u0004 וכמו כן במקום זה \u0003נוטל מן העני\u0004 העומד ברשות הרבים \u0003ו\u0004כן אם \u0003נותן לו,\u0004 כי מקום פטור אין בו כל צד איסור וחיוב בטלטול והוצאה בשבת, \u0003ובלבד שלא יטול מבעל הבית ונותן לעני\u0004 או \u0003מעני ונותן לבעל הבית,\u0004 שעל ידי זה סייע להעברה מרשות לרשות. \u0003ו\u0004אולם \u0003אם\u0004 עבר ו\u0003נטל\u0004 מאחד \u0003ונתן\u0004 לשני — ודאי שאין בכך מלאכה אסורה מן התורה, ו\u0003שלשתן פטורים.\u0004","ואילו \u0003אחרים אומרים:\u0004 לא כל איסקופה היא מקום פטור, כי איננה מיוחדת למדי לעצמה, אלא לפעמים ה\u0003איסקופה משמשת שתי רשויות\u0004 כשהיא מתבטלת לכל אחת בצירוף אחר. ועל כן \u0003בזמן שהפתח פתוח\u0004 — הריהי כהמשך הבית ונחשבת כרשות היחיד, ואם היה ה\u0003פתח נעול\u0004 — הריהי נחשבת \u0003כלחוץ,\u0004 שהיא מצטרפת לרשות הרבים ונחשבת כחלק ממנה. כל זה, כאשר האיסקופה איננה רשות שלימה לעצמה. \u0003ו\u0004אולם \u0003אם היתה\u0004 ה\u0003איסקופה גבוהה עשרה\u0004 טפחים מרשות הרבים \u0003ורחבה ארבעה\u0004 טפחים — \u0003הרי זו רשות לעצמה,\u0004 כרשות היחיד גמורה, ואף נבדלת מן הבית.","שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בתוספתא מהי הגדרת רשות היחיד, והוסיפה התוספתא בהדגשה: \u0003\"זו היא רשות היחיד\".\u0004 ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה],\u0006 מה באה ההדגשה הזאת להוציא? ומשיבים: \u0003למעוטי הא\u0004 \u0005[למעט\u0006 הלכה \u0005זו]\u0006 שאמר \u0003ר' יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003יתר על כן אמר ר' יהודה: מי שיש לו שני בתים בשני צדי רשות הרבים\u0004 העומדים זה מול זה, אם רוצה \u0003עושה\u0004 לעצמו רשות היחיד באמצע (בתוך רשות הרבים) באמצעות"],["\u0003לחי מכאן,\u0004 כלומר, יעמיד פס גבוה עשרה טפחים בכיוון הניצב אל רשות הרבים, ויעשה על ידי כך קיר סמלי אשר לדיני מבואות הוא נחשב לקיר, \u0003ו\u0004יעשה לו עוד \u0003לחי מכאן,\u0004 מן הצד השני, והרי זה כאילו סגר את רשות הרבים מכל \u0003צידיה. או\u0004 יעשה כתיקון אחר הנעשה במבואות — יניח \u0003קורה מכאן,\u0004 בין קצהו האחד של בית אחד לקצה המקביל של הבית שממולו, ועל ידי כך יבנה מחיצה סמלית לרוחב הרחוב, \u0003ו\u0004כן יעשה \u0003קורה מכאן,\u0004 מן הצד השני. ולדעת ר' יהודה נעשה השטח שבאמצע על ידי כך רשות היחיד, \u0003ו\u0004מותר לאדם להיות \u0003נושא ונותן באמצע\u0004 כברשות היחיד. \u0003אמרו לו\u0004 חכמים: והלא \u0003אין מערבין רשות הרבים בכך,\u0004 שאם רוצים לעשות את רשות הרבים לרשות היחיד יש צורך במחיצות ממשיות!","ושוב שואלים על לשון התוספתא האומרת \"זו היא רשות היחיד גמורה\": \u0003ואמאי קרו ליה\u0004 בלשון זו \u0003\"גמורה\"?\u0004 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כי פליגי רבנן עליה\u0004 \u0005[כאשר חלוקים חכמים עליו]\u0006 על \u0003ר' יהודה\u0004 ואמרו \u0003דלא הוי\u0004 \u0005[שאינה]\u0006 \u0003רשות היחיד, הני מילי\u0004 \u0005[דברים אלה]\u0006 נאמרו רק לגבי האיסור \u0003לטלטל\u0004 שם ביום השבת, שעל ידי מחיצות אלה לא נעשתה רשות היחיד לכל דבר עד כדי להתיר לטלטל בתוכה. \u0003אבל\u0004 יתכן שלגבי האיסור \u0003לזרוק\u0004 מרשות הרבים למקום זה ייחשב השטח שבין המחיצות כרשות היחיד מן התורה ויהא בכך איסור. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 התנא כי לדעת חכמים אין זו רשות היחיד כלל.","עוד שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בתוספתא מהי הגדרת רשות הרבים, והוסיפה התוספתא בהדגשה: \u0003\"זו היא רשות הרבים\".\u0004 ושוב שואלים: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 נאמרה ההדגשה \"זו\"? ומשיבים: כאן באה התוספתא \u0003למעוטי אידך\u0004 \u0005[למעט\u0006 את ההלכה \u0005האחרת]\u0006 שאמר \u0003ר' יהודה. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 שלעולי הרגל התירו לעשות מסביב לבארות המים מחיצות סמליות, על מנת להפוך את הבאר וסביבותיה לרשות היחיד, כך שיוכלו עולי הרגל להשתמש במי הבורות (שהרי הם רשות היחיד) אף בשבת. ועל כך \u0003ר' יהודה אומר: אם היתה דרך רשות הרבים מפסקתן\u0004 ועוברת במישרין בתחום הבורות ובתוך המחיצות — \u0003יסלקנה לצדדין,\u0004 כדי שעוברי דרכים לא יעברו שם. שלדעתו, יש במעבר אנשים רבים בתחום זה כדי לקלקל את רשות היחיד זו שנעשתה רק על ידי מחיצות סמליות. \u0003ו\u0004אילו \u0003חכמים אומרים: אינו צריך\u0004 לסלק את דרך רשות הרבים משם. וזוהי אם כן משמעות ההדגשה שבתוספתא \"זו היא רשות הרבים\", לומר כי רק זו בגדר רשות הרבים אבל באר שעשו לה מחיצות יצאה מכלל רשות הרבים, אף אם ממשיכים הרבים להלך בה.","ומוסיפים לשאול: \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קוראים לה]\u0006 \u0003\"גמורה\"?\u0004 ומשיבים: אמנם אין צורך בהדגשה זו, \u0003אלא איידי דתנא רישא\u0004 \u0005[מתוך ששנה\u0006 ב\u0005ראש\u0006 המשנה\u0005]\u0006 לשון \u0003\"גמורה\", תני נמי סיפא\u0004 \u0005[שנה גם כן\u0006 ב\u0005סופה]\u0006 לשון \u0003\"גמורה\",\u0004 מתוך שיגרת הלשון.","על הרשימה הזאת של המקומות המוגדרים כרשות הרבים שואלים: \u0003ולחשוב נמי\u0004 \u0005[ושימנה גם כן]\u0006 את ה\u0003מדבר\u0004 בין מקומות רשות הרבים, \u0003דהא תניא\u0004 \u0005[שהרי שנינו]\u0006 בברייתא אחרת: \u0003איזו היא רשות הרבים?\u0004 — \u0003סרטיא ופלטיא גדולה, ומבואות המפולשין, והמדבר! אמר אביי: לא קשיא,\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 כי \u0003כאן\u0004 שנמנה המדבר בכלל רשות הרבים, הרי זה \u0003בזמן שישראל\u0004 היו \u0003שרויין במדבר,\u0004 והיה זה מקום הרבים. ו\u0003כאן,\u0004 שלא נמנה המדבר בכלל רשות הרבים הרי זה \u0003בזמן הזה\u0004 שאין רבים מצויים שם.","עוד שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בתוספתא ש\u0003אם הוציא\u0004 או \u0003הכניס\u0004 חפץ בשבת מרשות היחיד לרשות הרבים ולהיפך, אם עשה כן \u0003בשוגג\u0004 — \u0003חייב חטאת,\u0004 ואם \u0003במזיד\u0004 ולא היו עדים למעשהו ובשל כך אף לא התרו בו — הריהו \u0003ענוש כרת.\u0004 ואם היו עדים ואף התרו בו לבל יעשה זאת — הריהו \u0003נסקל.\u0004 ושואלים: מה ששנינו כי \u0003בשוגג חייב חטאת,\u0004 הלא זהו \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי ברור הוא שהעובר עבירה חמורה זו של חילול שבת בשגגה חייב חטאת! ומשיבים: הקטע בו השמיענו התנא \u0003כי אם עשה כן במזיד\u0004 הריהו \u0003ענוש כרת ונסקל אצטריכא ליה\u0004 \u0005[נצרכה לו],\u0006 וכיון שהיה חידוש בכך, הובאה גם הפיסקה הראשונה להשלמת הדברים.","על כך שואלים: \u0003הא נמי פשיטא\u0004 \u0005[זה גם כן פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי מפורש בתורה שהמחלל שבת במזיד חייב כרת בשאין עדים והתראה, וסקילה בשיש עדים והתראה! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 \u0003כ\u0004הקשר לדברי \u0003רב,\u0004 ש\u0003אמר רב: מצאתי מגלת סתרים בי\u0004 \u0005[בבית]\u0006 \u0003ר' חייא\u0004 שנכתבו בה עניינים מתורה שבעל פה בתמצית, \u0003וכתוב בה: איסי בן יהודה אומר: אבות מלאכות\u0004 האסורים בשבת \u0003הם ארבעים חסר אחת, ואינו חייב אלא אחת.\u0004 ביטוי זה סתום הוא, ולכאורה נראה שכוונתו שעל המלאכות כולן אינו חייב אלא חטאת אחת.","ושואלים: \u0003איני\u0004 \u0005[וכן הוא]?!\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אבות מלאכות ארבעים חסר אחת.\u0004 ואחר כך נמנו המלאכות עצמן. \u0003והוינן\u0004 \u0005[והיינו\u0006 מתקשים\u0005]\u0006 \u0003בה: מנינא\u0004 \u0005[מנין]\u0006 \u0003למה לי?\u0004 שכן די היה ברשימה בלבד! \u0003ואמר ר' יוחנן\u0004: אף למנין יש חשיבות, להודיענו \u0003שאם עשאן\u0004 את כל המלאכות \u0003כולן בהעלם אחת,\u0004 כלומר, מתוך שגגה אחת, בלי להזכר בינתיים שהדבר אסור — \u0003חייב\u0004 להביא קרבן חטאת \u0003על כל אחת ואחת\u0004 מן המלאכות לחוד. ואם כן אין לפרש את דברי איסי בן יהודה כפי שפירשנום.","\u0003אלא אימא\u0004 \u0005[אמור,\u0006 פרש\u0005]\u0006 כך: ארבעים מלאכות חסר אחת הן, ו\u0003אינו חייב על אחת מהן,\u0004 שבין המלאכות יש אחת היוצאת מן הכלל (שלא נתפרשה) שאינו חייב עליה סקילה ויש בה רק איסור \"לא תעשה\" בלבד. \u0003ו\u0004כשהוזכר בתוספתא שהמוציא בשבת חייב, \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 התנא בכך: \u0003הא מהנך דלא מספקן\u0004 \u0005[זו,\u0006 ההוצאה מרשות לרשות, \u0005מאלו שאינן מסופקות]\u0006 וברור לנו שחייבים עליה חטאת.","עוד \u0003אמר מר\u0004 \u0005[החכם]\u0006 בתוספתא: \u0003אבל ים ובקעה והאיסטוונית והכרמלית אינן לא כרשות היחיד ולא כרשות הרבים\u0004, אלא כרמלית. על כך תוהים: \u0003ו\u0004כי ה\u0003בקעה אינו לא כרשות היחיד ולא כרשות הרבים? והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 במסכת טהרות ש\u0003הבקעה בימות החמה\u0004 שהוא זמן שהרבים מהלכים בה, משמשת \u0003רשות היחיד ל\u0004דיני \u0003שבת.\u0004 שכן על פי הגדרת רשויות השבת נשארת היא בגדר רשות היחיד. \u0003ו\u0004אולם \u0003כרשות הרבים\u0004 היא נחשבת \u0003ל\u0004ענין הלכות \u0003טומאה,\u0004 שלגביהן יש הבדל בין מקום שהרבים מצויים בו לבין מקום שאין הרבים מהלכים בו. ואילו \u0003בימות הגשמים,\u0004 בחורף, שאין רבים מהלכים בשדות, הבקעה נחשבת כ\u0003רשות היחיד לכאן ולכאן,\u0004 גם לענין טהרות וגם לענין שבת. ואם כן, הרי שהבקעה נחשבת כרשות היחיד ולא ככרמלית!","\u0003אמר עולא: לעולם\u0004 אמור שהבקעה \u0003כרמלית הויא\u0004 \u0005[היא]\u0006 \u0003ואמאי קרי\u0004 \u0005[ומדוע קורא]\u0006 \u0003לה\u0004 במשנה \u0003רשות היחיד\u0004 — \u0003לפי\u0004 שרצה להדגיש \u0003שאינה רשות הרבים.\u0004 כי במסכת טהרות לא נכנסו לפרטי דברים בדיני שבת, אלא אך הובלט ההבדל בין דיני שבת וטהרה.","\u0003רב אשי אמר:\u0004"],["\u0003כגון דאית\u0004 \u0005[שיש]\u0006 \u0003לה מחיצות\u0004 גבוהות עשרה טפחים מסביב. \u0003וכי הא\u0004 \u0005[כמו\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר עולא אמר ר' יוחנן: קרפף,\u0004 שהיא חצר גדולה שאיננה מצורפת ומשמשת במישרין את הבית, שגודלו \u0003יותר מבית סאתים, שלא הוקף\u0004 בגדר מתחילה \u0003ל\u0004צורך \u0003דירה\u0004 בתוכו, כי אם במחיצה לשמור על חפצים בלבד, \u0003ואפילו\u0004 היה גדול עד כדי בית \u0003כור\u0004 (פי שלושים מסאה) \u0003ואפילו\u0004 בית \u0003כוריים\u0004 — נחשב הוא עדיין לרשות היחיד, ו\u0003הזורק לתוכו\u0004 בשבת חפץ מרשות הרבים — \u0003חייב. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003מחיצה היא\u0004 שמסביב לקרפף, ודינה כמחיצה לכל דבר, \u0003אלא שמחוסרת דיורין.\u0004 ואף שמשום חסרון זה החמירו חכמים בקרפף זה ואסרו לטלטל בתוכו כאילו היתה כרמלית, ואולם אין זה מבטל את עיקר דינו, שמן התורה הריהו רשות היחיד גמורה. וגם בקעה זו שהוזכרה היתה שטח גדול שהוקף מחיצות לשמירה ונעשה על ידי כך רשות היחיד.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ל\u0003רב אשי\u0004 שהוא \u0003לא אמר\u0004 את פירוש הדברים \u0003כ\u0004פי שפירש זאת \u0003עולא,\u0004 לפי שיש טעם לדבר, \u0003אלא עולא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כשמעתיה\u0004 \u0005[כהלכה שלו\u0006 עצמו\u0005]?\u0006 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 עולא: \u0003אי דאית\u0004 \u0005[אם\u0006 מדובר באופן \u0005שיש]\u0006 \u0003לה מחיצות\u0004 האם \u0003\"בקעה\" קרי\u0004 \u0005[קורא]\u0006 הוא \u0003לה?!\u0004 והלא \u0003קרפף היא!\u0004 שמלשון \"בקעה\" מסתבר שאין לה מחיצות כלל. \u0003ורב אשי\u0004 מצדיק את שיטתו באמרו ש\u0003\"רשות היחיד\" קתני\u0004 \u0005[נאמר]\u0006 במשנה ולא \"כרמלית\", ודבריו קרובים, איפוא, יותר ללשון המשנה.","ברשימת המקומות השנויים בתוספתא ודינם כרמלית נמנית גם ה\u0003כרמלית.\u0004 ושואלים: \u0003אטו כולהו\u0004 \u0005[והאם כולם],\u0006 כל שאר הדברים השנויים שם, כגון ים בקעה ואיסטוונית, \u0003נמי לאו\u0004 \u0005[גם כן לא]\u0006 \u0003כרמלית נינהו\u0004 \u0005[הם]?\u0006 ואם כן, מה היא כרמלית זו המוזכרת כאן בהבלטה? ומשיבים: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: לא נצרכה\u0004 תוספת זו \"והכרמלית\" \u0003אלא לקרן זוית הסמוכה לרשות הרבים. דאף על גב דזימנין דדחקי ביה\u0004 \u0005[שאף על פי שלפעמים דוחקים בה]\u0006 \u0003רבים ועיילי לגוה\u0004 \u0005[ונכנסים לתוכה],\u0006 \u0003כיון דלא ניחא תשמישתיה\u0004 \u0005[שאיון שימושה נוח],\u0006 \u0003כי\u0004 \u0005[כמו]\u0006 \u0003כרמלית דמי\u0004 \u0005[\u0006היא \u0005נחשבת].\u0006","וכעין זה, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: בין העמודין\u0004 שבצד רשות הרבים \u0003נידון ככרמלית. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אף על גב דדרסי\u0004 \u0005[אף על פי\u0006 \u0003שדורסים,\u0004 דורכים\u0005]\u0006 \u0003בה רבים, כיון דלא מסתגי להו בהדיא\u0004 \u0005[שאין\u0006 הם \u0005יכולים ללכת\u0006 בה \u0005במישרין]\u0006 — \u0003ככרמלית דמיא\u0004 \u0005[\u0006היא \u0005נחשבת].\u0006 \u0003אמר ר' זירא אמר רב יהודה:\u0004 אף ה\u0003איצטבא שלפני העמודים\u0004 שעליה מניחים הסוחרים את סחורתם \u0003נידון ככרמלית.\u0004","ומעירים: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003בין העמודים\u0004 נחשב ככרמלית, \u0003כל שכן\u0004 שהוא הדין לענין ה\u0003איצטבא.\u0004 ואולם \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003איצטבא\u0004 היא כרמלית — אפשר לומר כי דווקא ב\u0003איצטבא\u0004 הדין \u0003הוא\u0004 כן משום ש\u0003לא ניחא תשמישתיה\u0004 \u0005[נוח שימושה],\u0006 \u0003אבל\u0004 המקום ש\u0003בין העמודים דניחא תשמישתיה\u0004 \u0005[שנוח שימושו]\u0006 — \u0003לא\u0004 ייחשב ככרמלית. \u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 אמרו באותו ענין: \u0003אבל בין העמודין דזימנין דדרסי ליה\u0004 \u0005[שלפעמים שדורסים,\u0006 דורכים \u0005בו]\u0006 \u0003רבים,\u0004 הרי \u0003כרשות הרבים דמיא\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006","בקשר לשאלה באיזו מידה שימושם של הרבים מחשיב מקום מוגדר לרשות הרבים, הביאו את ההלכה ש\u0003אמר רבה בר שילא אמר רב חסדא:\u0004 אם היתה \u0003לבינה זקופה\u0004 מונחת \u0003ברשות הרבים וזרק\u0004 חפץ ממרחק ארבע אמות \u0003וטח\u0004 (הדביק) חפץ זה \u0003בפניה\u0004 — \u0003חייב\u0004 משום זריקה לרשות הרבים. אבל אם נפל החפץ \u0003על גבה\u0004 של הלבינה — \u0003פטור\u0004 כי אין הרבים מהלכים על גבי הלבינה ואין זו רשות הרבים גמורה.","\u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003והוא\u0004 דווקא \u0003שגבוה\u0004 אותה לבינה \u0003שלשה\u0004 טפחים לכל הפחות, שאז \u0003לא דרסי לה\u0004 \u0005[דורסים אותה,\u0006 דורכים עליה\u0005]\u0006 \u0003רבים,\u0004 ולכן, אף שהלבינה ניצבת ברשות הרבים — הריהי כמקום בפני עצמו. ואולם \u0003היזמי והיגי,\u0004 מיני קוצים, \u0003אף על גב דלא גביהי\u0004 \u0005[אף על פי שאינם גבוהים]\u0006 \u0003שלשה\u0004 טפחים אינם נחשב מקומם לרשות הרבים, כיון שאין בני אדם מהלכים על גבי הקוצים, ולא שייך להחשיב מקום זה כרשות הרבים. \u0003ו\u0004אילו \u0003חייא בר רב אמר: אפילו\u0004 מקום \u0003היזמי והיגי\u0004 ברשות הרבים, אם היו נמוכים נחשב מקומם כרשות הרבים, \u0003אבל\u0004 מקום ברשות הרבים בו מונחת \u0003צואה לא\u0004 נחשב כרשות הרבים, שאין אנשים מהלכים במקום זה. \u0003ורב אשי אמר: אפילו\u0004 מקום ברשות הרבים בו מונחת \u0003צואה\u0004 נחשב כרשות הרבים, כיון שבסופו של דבר האנשים הממהרים לעבודתם לא יקפידו וידרכו עליה.","\u0003אמר רבה דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב שילא: כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: אין כרמלית פחותה מארבעה\u0004 טפחים. הוסיף \u0003ואמר\u0004 על כך \u0003רב ששת: ו\u0004הכרמלית \u0003תופסת עד עשרה.\u0004 על לשון זו של רב ששת תהו: \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 \u0003\"ותופסת עד עשרה \"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דאי איכא\u0004 \u0005[שאם יש]\u0006 מסביבה \u0003מחיצה\u0004 בגובה \u0003עשרה\u0004 טפחים \u0003הוא דהוי\u0004 \u0005[שהיא]\u0006 נחשבת \u0003כרמלית, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא הוי\u0004 \u0005[אינה]\u0006 נחשבת כ\u0003כרמלית, ו\u0004האם \u0003לא?\u0004 וכי אין זו כרמלית? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב גידל אמר רב חייא בר יוסף אמר רב: בית שאין בתוכו\u0004 גובה \u0003עשרה\u0004 טפחים לקירות, \u0003וקרויו\u0004 \u0005[הגג שעליו]\u0006 \u0003משלימו ל\u0004גובה \u0003עשרה\u0004 טפחים מעל הקרקע, הרי \u0003על גגו\u0004 — \u0003מותר לטלטל בכולו,\u0004 שכן גגו הריהו רשות היחיד לכל דבר, ו\u0003בתוכו\u0004 — \u0003אין מטלטלין בו אלא ארבע אמות,\u0004 שאין הגובה בפנים מספיק כדי לעשותו רשות היחיד, והוא נשאר בגדר כרמלית. הרי שאפילו בפחות מעשרה טפחים יש דין כרמלית!","\u0003אלא מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 דברי רב ששת \u0003\"ותופסת עד עשרה\"\u0004 — יש להבין זאת ש\u0003עד עשרה הוא דהויא\u0004 \u0005[שהינה]\u0006 תחום ה\u0003כרמלית, ו\u0004אולם \u0003למעלה מעשרה\u0004 טפחים \u0003לא הוי\u0004 \u0005[אינה]\u0006 כבר בגדר \u0003כרמלית. וכי הא\u0004 \u0005[וכמו זה]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: שיננא\u0004 (גדול השיניים), \u0003לא תיהוי במילי דשבתא\u0004 \u0005[אל תעסוק\u0006 בשאלות \u0005בענייני שבת]\u0006 \u0003למעלה מעשרה\u0004 טפחים. ומעתה מבררים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 ובאיזה ענין אמר שמואל דבר זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכוונתו היתה לומר ש\u0003אין רשות היחיד למעלה מעשרה\u0004 טפחים? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא:\u0004 אם \u0003נעץ\u0004 אדם \u0003קנה ברשות היחיד וזרק\u0004 חפץ מרשות הרבים \u0003ונח על גביו, אפילו\u0004 היה הקנה \u0003גבוה מאה אמה\u0004 — \u0003חייב, מפני שרשות היחיד עולה עד לרקיע.\u0004 והרי שיש רשות היחיד אפילו למעלה מעשרה טפחים!"],["ו\u0003אלא\u0004 תאמר כי רצה שמואל לומר ש\u0003אין רשות הרבים למעלה מעשרה\u0004 טפחים — והלא \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא,\u0004 ולשם מה יחזור על דבר המפורש כבר במשנה? \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הזורק\u0004 חפץ \u0003ארבע אמות\u0004 ברשות הרבים ונח החפץ \u0003בכותל\u0004 העומד ברשות הרבים, אם נח \u0003למעלה מעשרה טפחים\u0004 מעל הקרקע — הרי הוא \u0003כזורק באויר\u0004 ולא עשה ולא כלום. ואם נח \u0003למטה מעשרה טפחים\u0004 — הריהו \u0003כזורק בארץ.\u0004 והרי משנה מפורשת היא שתחום רשות הרבים מגיע רק עד לעשרה טפחים!","\u0003אלא\u0004 ודאי יש לומר כי דברי שמואל היו ביחס ל\u0003כרמלית,\u0004 ש\u0003אין כרמלית למעלה מעשרה\u0004 טפחים. \u0003ו\u0004אם כן, \u0003אקילו\u0004 \u0005[הקלו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים]\u0006 \u0003מקולי\u0004 \u0005[מן ההקלות]\u0006 שב\u0003רשות היחיד ומקולי\u0004 \u0005[ומן ההקלות]\u0006 שב\u0003רשות הרבים.\u0004 ומפרטים: \u0003מקולי\u0004 \u0005[מן ההקלות]\u0006 שב\u0003רשות היחיד\u0004 — \u0003דאי איכא\u0004 \u0005[שאם יש]\u0006 \u0003מקום ארבעה\u0004 טפחים \u0003הוא דהויא\u0004 \u0005[שהינה]\u0006 \u0003כרמלית, ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שאין שם מקום ארבעה טפחים — \u0003מקום פטור בעלמא\u0004 \u0005[סתם,\u0006 בלבד\u0005]\u0006 \u0003הוא.\u0004 ו\u0003מקולי\u0004 \u0005[מן ההקלות]\u0006 שב\u0003רשות הרבים\u0004 — ש\u0003עד עשרה טפחים הוא דהויא\u0004 \u0005[שהינה]\u0006 תחום ה\u0003כרמלית\u0004 ואולם \u0003למעלה מעשרה טפחים לא הויא\u0004 \u0005[אינה]\u0006 \u0003כרמלית.\u0004","\u0003גופא\u0004 \u0005[לגוף]\u0006 הענין שהוזכר קודם לכן ש\u0003אמר רב גידל אמר רב חייא בר יוסף אמר רב: בית שאין\u0004 ב\u0003תוכו\u0004 גובה \u0003עשרה, וקרויו\u0004 \u0005[הגג שעליו]\u0006 \u0003משלימו ל\u0004גובה \u0003עשרה טפחים,\u0004 הרי \u0003על גגו\u0004 — \u0003מותר לטלטל בכולו,\u0004 שכן גגו הריהו רשות היחיד לכל דבר, ו\u0003בתוכו\u0004 — \u0003אין מטלטלין בו אלא בארבע אמות,\u0004 שאין הגובה בפנים מספיק כדי לעשותו רשות היחיד, והוא נשאר בגדר כרמלית.","ועל הלכה זו \u0003אמר אביי: ואם חקק\u0004 (חפר) \u0003בו\u0004 ברצפת הבית שטח של \u0003ארבעה על ארבעה\u0004 טפחים \u0003והשלימו\u0004 שבמקום החפירה יהא גובהו \u0003עשרה\u0004 טפחים עד לתקרה — הופך הבית להיות רשות היחיד, ו\u0003מותר\u0004 כבר \u0003לטלטל\u0004 (כברשות היחיד) \u0003ב\u0004כל הבית \u0003כולו. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שבשל אותו מקום חקוק שיש בו רשות היחיד, נעשה שאר הבית כטפל אליו, ו\u0003הוי\u0004 \u0005[נעשים]\u0006 הם \u0003חורי רשות היחיד, וחורי רשות היחיד\u0004 אף שאין בהם מדות רשות היחיד, מכל מקום \u0003כרשות היחיד\u0004 עצמה \u0003דמו\u0004 \u0005[\u0006הם \u0005נחשבים].\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שעסקו חכמים בבירורה של בעיה זו. ששנינו: הכל מודים כי \u0003חורי רשות היחיד כרשות היחיד דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 שמצטרפים לרשות היחיד ונידונים כמותה, אלא שנחלקו בדבר \u0003חורי רשות הרבים, אביי אומר\u0004 ש\u0003כרשות הרבים דמו\u0004 \u0005[\u0006הם \u0005נחשבים].\u0006 ו\u0003רבא אומר: לאו\u0004 \u0005[לא]\u0006 \u0003כרשות הרבים דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 אלא או כרמלית או מקום פטור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לאביי: לדידך\u0004 \u0005[לשיטתך]\u0006 ש\u0003אמרת\u0004 כי \u0003חורי רשות הרבים כרשות הרבים דמו\u0004 \u0005[נחשבים],\u0006 אם כן \u0003מאי שנא מהא דכי אתא\u0004 \u0005[במה שונה\u0006 הדבר \u0005מ\u0006הלכה \u0005זו, שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: לא נצרכה אלא\u0004 לחדש ולומר כי הכרמלית כוללת גם \u0003קרן זוית הסמוכה לרשות הרבים, ו\u0004לשיטתך \u0003תיהוי\u0004 \u0005[תהיה]\u0006 פינה זו \u0003כחורי רשות הרבים,\u0004 ודינה כרשות הרבים עצמה, ומה החידוש בדבר?! ענה אביי: יש להבדיל בין הדברים, ולומר כי \u0003התם\u0004 \u0005[שם]\u0006 בקרן זוית \u0003לא ניחא תשמישתיה\u0004 \u0005[נוח שימושו],\u0006 ואולם \u0003הכא ניחא תשמישתיה\u0004 \u0005[כאן\u0006 בחורי רשות הרבים \u0005נוח שימושו],\u0006 שמאחר שנוח להשתמש בחורים שברשות הרבים, ומשתמשים בהם, הרי הם כמקום הרבים לכל דבר.","עוד הקשו לאביי: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 כי \u0003הזורק\u0004 חפץ בשבת למרחק \u0003ארבע אמות\u0004 ברשות הרבים ונח החפץ \u0003בכותל\u0004 הקבוע ברשות הרבים, אם היה הכותל \u0003למעלה מעשרה\u0004 טפחים — הריהו \u0003כזורק באויר,\u0004 ופטור. ואם היה גובהו \u0003למטה מעשרה טפחים\u0004 — הריהו \u0003כזורק בארץ\u0004 עצמה, וחייב. \u0003והוינן\u0004 \u0005[ועסקנו]\u0006 \u0003בה,\u0004 בהלכה זו: \u0003מאי\u0004 \u0005[מה]\u0006 טעם כשאין בגובה הכותל עשרה טפחים יהא זה \u0003כזורק בארץ? והא\u0004 \u0005[והרי]\u0006 \u0003לא נח\u0004 החפץ בכותל, שמסתבר שרק פגע החפץ בכותל וחזר ונפל על הקרקע, וכיון שלא היתה הנחה — אין זו מלאכת טלטול!","\u0003ואמר ר' יוחנן\u0004 כי במשנה זו \u0003ב\u0004שזרק \u0003דבילה\u0004 (תאנה) \u0003שמינה\u0004 הנדבקת לכותל ונחה שם \u0003שנו. ואי סלקא דעתך\u0004 \u0005[ואם יעלה על דעתך]\u0006 לומר כי \u0003חורי רשות הרבים כרשות הרבים דמו\u0004 \u0005[נחשבים],\u0006 אם כן \u0003למה לי לאוקמה\u0004 \u0005[להעמידה,\u0006 להסבירה\u0005]\u0006 למשנה \u0003בדבילה שמינה? לוקמה\u0004 \u0005[יעמידה]\u0006 \u0003בצרור וחפץ\u0004 סתם, \u0003ו\u0004ש\u0003נח\u0004 החפץ \u0003בחור\u0004 שבכותל שהוא הסבר פשוט יותר!","על שאלה זו \u0003זימנין משני לה\u0004 \u0005[פעמים היה מתרץ אותה],\u0006 את הקושיה, כי \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003צרור וחפץ דמיהדר ואתי\u0004 \u0005[שחוזר ובא]\u0006 כאשר זורקים אותו, ואינו נח בחור שנזרק בו ולכן נוח יותר להסביר בדבילה. ו\u0003זימנין משני לה\u0004 \u0005[פעמים היה מתרץ אותה],\u0006 את הקושיה, כי מדובר \u0003בכותל דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003חור. וממאי\u0004 \u0005[וממה]\u0006 מוצא הוא סיוע להסבר זה? — \u0003מדקתני רישא\u0004 \u0005[ממה ששנינו בראש\u0006 המשנה\u0005]:\u0006 \u0003זרק\u0004 חפץ ברשות הרבים \u0003למעלה מעשרה טפחים\u0004 — דינו הוא \u0003כ\u0004דין ה\u0003זורק באויר. ואי סלקא דעתך\u0004 \u0005[ואם יעלה על דעתך]\u0006 לומר \u0005כי מדובר כאן\u0006 \u0003בכותל דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003חור,\u0004 אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהא דינו \u0003כ\u0004די ה\u0003זורק באויר? הא\u0004 \u0005[\u0006ו\u0005הרי]\u0006 \u0003נח בחור,\u0004 וחור זה רשות היחיד הוא (שהוא למעלה מעשרה טפחים) ונעשתה על ידי כך מלאכת הוצאה!","\u0003וכי תימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת באופן \u0003דלית בהו\u0004 \u0005[שאין בהם]\u0006 באותם חורים \u0003ארבעה על ארבעה\u0004 טפחים, שכך מצוי בחורים שבכותל, ולכן נחשבים החורים למקום פטור, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 בענין זה עצמו \u0003רב יהודה אמר ר' חייא:\u0004 אם \u0003זרק\u0004 חפץ \u0003למעלה מעשרה טפחים והלכה\u0004 החפץ \u0003ונחה בחור\u0004 ואפילו היה גודלו \u0003כל שהוא\u0004 — הרי \u0003באנו\u0004 בענין זה \u0003למחלוקת ר' מאיר ורבנן\u0004 \u0005[וחכמים],\u0006 שההכרעה אם יש כאן איסור תלויה בבירור אותה מחלוקת. ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]\u0006 שלכל ענין אם חסר בגודל החלל כדי שיגיע לכדי שיעור מסויים ובכך ישתנה דינו, הרי אם ישנה אפשרות על פי מציאות השטח לחקוק ולחתוך חלק מסויים ולהשלים את גודל החלל לכדי השיעור הקובע — \u0003חוקקין להשלים,\u0004 כלומר, הרי זה כאילו נעשה הדבר בפועל. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 ש\u0003אין חוקקין להשלים,\u0004 אלא דנים את החלל כמות שהוא. ואם כן, כשנפל חפץ בחור קטן הרי לדעת ר' מאיר חוקקים להשלים, וייחשב כאילו היה החור ארבעה על ארבעה טפחים, ודינו כרשות היחיד לכל דבר. \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד ממנה],\u0006 ממה ששנינו שהזורק בכותל למעלה מעשרה טפחים הריהו כזורק באויר, כי מדובר \u0003בכותל דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003חור,\u0004 ולא התעוררה כלל שאלת הרחבת החלל. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","ועוד חוזרים לדון \u0003גופא\u0004 \u0005[לגופו]\u0006 של דבר שהוזכר קודם בדרך אגב. ששנינו ש\u0003אמר רב חסדא:\u0004 אם \u0003נעץ\u0004 אדם \u0003קנה ברשות היחיד, ונח על גביו\u0004 חפץ שזרק הוא עצמו מרשות הרבים, \u0003אפילו\u0004 אותו קנה \u0003גבוה מאה אמה\u0004 — \u0003חייב.\u0004 וטעם הדבר — \u0003לפי שרשות היחיד עולה עד לרקיע\u0004. ושואלים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 כי \u0003רב חסדא\u0004 ש\u0003אמר\u0004 את דבריו \u0003כ\u0004שיטת \u0003רבי\u0004 הוא שאמר כן? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 שנחלקו תנאים בענין דומה. ששנינו: אם \u0003זרק\u0004 אדם חפץ בשבת ברשות הרבים, \u0003ונח\u0004 החפץ \u0003על גבי זיז כל שהוא\u0004 — \u0003רבי מחייב וחכמים פוטרים. אלמא\u0004 \u0005[מכאן]\u0006 שרק לדעת רבי אין צורך שינוח החפץ על גבי מקום מסויים בגודלו, ודברי רב חסדא בקנה מובנים איפוא רק לפי שיטתו."],["\u0003אמר אביי: ברשות היחיד דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שהלכה \u0003כ\u0004שיטת \u0003רב חסדא,\u0004 שרשות היחיד נחשבת לחטיבה אחת מלאה עד לרקיע. \u0003אלא הכא\u0004 \u0005[כאן,\u0006 בברייתא זו\u0005]\u0006 מדובר במקרה מיוחד — \u0003באילן העומד ברשות היחיד ו\u0004אילו \u0003נופו\u0004 \u0005[ענפיו]\u0006 \u0003נוטה לרשות הרבים, וזרק\u0004 אדם חפץ מרשות הרבים \u0003ונח\u0004 החפץ על \u0003נופו.\u0004 ש\u0003רבי סבר\u0004 \u0005[סבור]\u0006 כי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003\"שדי\u0004 \u0005[זרוק]\u0006 את \u0003נופו בתר\u0004 \u0005[אחר]\u0006 \u0003עיקרו\",\u0004 וחשוב את הצמרת כולה כאילו היתה בתחום רשות היחיד. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003\"שדי\u0004 \u0005[זרוק]\u0006 את \u0003נופו בתר\u0004 \u0005[אחר]\u0006 \u0003עיקרו\",\u0004 ומשום כך הצמרת נמצאת שלא ברשות היחיד אלא במקום פטור, ולכן אינו חייב.","\u0003אמר אביי: זרק כוורת,\u0004 שהיא כחבית עגולה, עשויה קנים \u0003ל\u0004תוך \u0003רשות הרבים,\u0004 והיתה הכוורת \u0003גבוהה עשרה\u0004 טפחים \u0003ואינה רחבה\u0004 (בקוטר) \u0003ששה\u0004 טפחים — \u0003חייב.\u0004 כי מאחר שאין קוטרה מגיע לששה טפחים, אין בשטחה לפי חשבון ריבוע של ארבעה על ארבעה טפחים. ולכן, כוורת זו נחשבת חפץ, ואם זרקה מרשות היחיד לרשות הרבים — חייב. ואולם אם היתה הכוורת \u0003רחבה\u0004 בקוטרה \u0003ששה\u0004 טפחים — \u0003פטור,\u0004 שכיון שיש בשטח הכוורת ריבוע של ארבעה על ארבעה טפחים הריהי כבר נחשבת כרשות היחיד לעצמה, ואין בה משום זריקה מרשות לרשות.","ו\u0003רבא אמר: אפילו אינה רחבה ששה\u0004 טפחים — \u0003פטור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שכן \u0003אי אפשר לקרומיות של קנה\u0004 (החלקים הבולטים ויוצאים מאריגת הקנים של הכוורת) ש\u0003לא יעלו למעלה מעשרה\u0004 טפחים. ואם כן, נמצא שהכוורת כולה לא הגיעה כלל אל רשות הרבים — שהרי חלק ממנה נמצא עדיין במקום פטור (עשרה טפחים מעל לרשות הרבים).","ואם \u0003כפאה\u0004 לכוורת זו שאין ברוחבה ששה טפחים \u0003על פיה,\u0004 שזרקה כשפיה למטה, במקרה זה אם היתה הכוורת גבוהה רק \u0003שבעה\u0004 טפחים \u0003ומשהו\u0004 — עדיין \u0003חייב,\u0004 שכוורת זו הריהי כשאר חפצים שנפלו לשם. ואולם אם היה גובהה של כוורת זו גדול מזה והגיע לכדי \u0003שבעה\u0004 טפחים \u0003ומחצה\u0004 — \u0003פטור,\u0004 שכן בתוך שלושה טפחים לקרקע אנו מסתמכים על הכלל של \"לבוד\" שלפיו דבר סמוך בתוך שלושה טפחים נחשב כמחובר, ואנו ממשיכים את מחיצות הכוורת עד לקרקע, ואז נחשב כאילו נגעה כבר הכוורת בקרקע רשות הרבים (כשהוא עדיין במרחק שלשה טפחים) בעוד חלקה העליון עדיין במקום פטור. וכאילו היתה זו כוורת הגבוהה מעשרה טפחים.","ואילו \u0003רב אשי אמר: אפילו\u0004 היה גובה הכוורת \u0003שבעה\u0004 טפחים \u0003ומחצה\u0004 — \u0003חייב.\u0004 שכן אין אנו יכולים להחשיב את מחיצות הכוורת כגבוהות יותר. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — משום שה\u0003מחיצות לתוכן עשויות,\u0004 שמחיצותיה של הכוורת אין להן כל תפקיד מעבר לתחומה הממשי, ועל כן, אין מקום להאריך את המחיצות מדין לבוד. ומשום כך, אם אין הכוורת גבוהה מעשרה טפחים הרי היא כחפץ בלבד.","\u0003אמר עולא: עמוד\u0004 שגובהו \u0003תשעה\u0004 טפחים שהיה עומד \u0003ברשות הרבים\u0004 והיו \u0003רבים מכתפין עליו,\u0004 כלומר, נעזרים בו כדי להקל על עצמם להרים משא על כתפיהם, \u0003וזרק\u0004 חפץ מרשות היחיד \u0003ונח על גביו,\u0004 על גבי העמוד — \u0003חייב. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — על פי כלל זה: כל דבר הבולט מרשות הרבים \u0003פחות משלשה\u0004 טפחים \u0003מדרס דרסי ליה\u0004 \u0005[דורסים אותו,\u0006 דורכים עליו\u0005]\u0006 ה\u0003רבים,\u0004 והוא נחשב כחלק מן הקרקע. \u0003משלשה ועד תשעה\u0004 טפחים — \u0003לא מדרס דרסי ליה\u0004 \u0005[דורסים עליו]\u0006 הרבים \u0003ולא כתופי מכתפי\u0004 \u0005[מכתפים]\u0006 עליו. ואולם דבר \u0003שגובהו תשעה\u0004 טפחים \u0003ודאי מכתפי עילויה\u0004 \u0005[מכתפים עליו],\u0006 וכיון שרבים משתמשים בו הריהו רשות הרבים, למרות גובהו.","בהסתמך על דברי עולא \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: גומא\u0004 העמוקה טפחים אחדים מקרקע רשות הרבים \u0003מאי\u0004 \u0005[מה]\u0006 דינה? האם אף היא תיחשב, בהתאם לכלל של עולא, כחלק מרשות הרבים? שכן בדרך כלל בהלכות שבת אין מבחינים בין דבר המוגבה מעל שטח, לבין הנמוך מן השטח הזה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003וכן בגומא,\u0004 שייכות אותן הלכות. ואילו \u0003רבא אמר: בגומא לא. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — כיון ש\u0003תשמיש על ידי הדחק לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 כ\u0003תשמיש,\u0004 וגומא, אף אם עומקה תשעה טפחים אינה מקום נוח לשימוש ואין להשוותה לעמוד בגובה זה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אדא בר מתנא לרבא\u0004 מממה ששנינו בברייתא: \u0003היתה קופתו\u0004 \u0005[סלו]\u0006 \u0003מונחת ברשות הרבים\u0004 והיא \u0003גבוהה עשרה\u0004 טפחים \u0003ורחבה ארבעה\u0004 — \u0003אין מטלטלין\u0004 חפץ \u0003לא מתוכה לרשות הרבים ולא מרשות הרבים לתוכה,\u0004 לפי שקופה זו דינה כרשות היחיד. ואם היה גובהה \u0003פחות מכן\u0004 — \u0003מטלטלין\u0004 מתוכה לרשות הרבים, ולהיפך. ומוסיפה הברייתא: \u0003וכן בגומא. מאי לאו אסיפא\u0004 \u0005[האם לא\u0006 נאמר דבר זה \u0005על הסוף]\u0006 של הברייתא, כלומר, שגומא הפחותה מעשרה טפחים מטלטלים מתוכה לרשות הרבים. והרי זה כדעת רב יוסף, שגומא בטלה לרשות הרבים: ודחה רבא: \u0003לא, ארישא\u0004 \u0005[לא\u0006 נאמר דבר זה אלא \u0005על ראשה\u0006 של הברייתא\u0005],\u0006 שאם היתה הגומא עמוקה עשרה טפחים אין מטלטלים ממנה, כי היא רשות היחיד גמורה, אבל אין להסיק מכאן לגבי גומא שעומקה פחות מעשרה טפחים.","עוד \u0003איתיביה\u0004 \u0005[שאל אותו]\u0006 רב אדא בר מתנא את רבא ממה ששנינו בברייתא אחרת העוסקת בדיני עירובי תחומים:"],["\u0003נתכוון לשבות ברשות הרבים\u0004 במקום מסויים, הרי כדי שייחשב לו ששבת באותו מקום צריך הוא להניח בו מזון הראוי לשתי סעודות. \u0003ו\u0004אם \u0003הניח\u0004 אדם זה את \u0003עירובו\u0004 (המזון המשמש לצורך העירוב) \u0003בבור למעלה מעשרה טפחים,\u0004 כלומר, שאינו עמוק עשרה טפחים — \u0003עירובו עירוב.\u0004 ואם הניח את העירוב \u0003למטה מעשרה טפחים,\u0004 שהוא עמוק עשרה טפחים ויותר — \u0003אין עירובו עירוב.\u0004 כי מקום זה נחשב כבר לרשות היחיד, ומאחר שאין הוא יכול להוציא את העירוב מרשות היחיד (הבור) לרשות הרבים, מקום שביתתו — אין זה נחשב לעירוב. ומעתה ניגשים לברר את פרטי הענין בנושא זה.","\u0003היכי דמי\u0004 \u0005[כיצד היה הדבר בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בבור דאית ביה\u0004 \u0005[שיש בו]\u0006 בעומקו \u0003עשרה\u0004 טפחים, ונפרש \"שהניחו \u0003למעלה\u0004 מעשרה טפחים\" — \u0003דדלאי ואותביה\u0004 \u0005[שהרימו והניחו],\u0006 כלומר, שהניח את העירוב בתוך עשרה טפחים מפני הקרקע, ונאמר כי \u0003\"למטה\u0004 מעשרה טפחים \u0003\",\u0004 משמעו \u0003דתתאי ואותביה\u0004 \u0005[שהורידו והניחו],\u0006 שהניח את העירוב למטה מעשרה טפחים מפני הקרקע, ואולם במקרה זה \u0003מה לי למעלה ומה לי למטה,\u0004 כלומר, מה ההבדל אם היה העירוב למעלה או למטה, והרי הבור הוא רשות היחיד, וכלל בידינו כי רשות היחיד תופסת מקרקעה עד לרקיע. ואין כל הבדל אם היה העירוב מונח גבוה יותר או נמוך יותר — שהרי בכל מקרה \u0003הוא במקום אחד,\u0004 ברשות הרבים, \u0003ועירובו במקום אחר הוא,\u0004 ברשות היחיד, ומאחר שאינו יכול להוציא את העירוב מן הבור — אין עירובו עירוב.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 נצטרך לפרש שהמדובר הוא \u0003בבור דלית ביה\u0004 \u0005[שאין בו]\u0006 בעומקו \u0003עשרה\u0004 טפחים, ונבין כך: \"למטה מעשרה טפחים\" הריהו בבור עמוק מעשרה, שתחתיתו למטה מעשרה מפני הקרקע. למעלה מעשרה — בבור פחות מעשרה ואינו רשות היחיד, וזהו \"הניח עירובו למעלה מעשרה טפחים\" לקרקע, \u0003וקתני עירובו עירוב\u0004. \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003תשמיש על ידי הדחק\u0004 בגומא הפחותה מעשרה טפחים \u0003שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003תשמיש,\u0004 ובור כזה הוא רשות הרבים ממש.","על כך ענה רבא תשובות שונות, \u0003זמנין משני ליה\u0004 \u0005[לפעמים היה מתרץ לו]\u0006 שמדובר כאן באופן ש\u0003הוא ועירובו בכרמלית,\u0004 שהתכוון לשבות בכרמלית ומניח את העירוב שם, והבור היה פחות מעשרה טפחים ושניהם ברשות אחת. \u0003ואמאי קרי\u0004 \u0005[ומדוע קורא]\u0006 \u0003לה\u0004 בברייתא למקום שביתתו \u0003\"רשות הרבים\"\u0004 — \u0003לפי שאינה רשות היחיד.\u0004","\u0003וזמנין משני ליה\u0004 \u0005[ולפעמים היה מתרץ לו]\u0006 תירוץ אחר, שמדובר כאן באופן שהיה \u0003הוא\u0004 אמנם \u0003ברשות הרבים ו\u0004אולם \u0003עירובו\u0004 נחשב כאילו היה \u0003ב\u0004תוך \u0003כרמלית\u0004, שבור שאין עומקו עשרה טפחים אינו כרשות הרבים כי אם ככרמלית. \u0003ו\u0004על השאלה כיצד בכל זאת ייחשב זה לעירוב כשר בעוד שאסור לטלטל גם מכרמלית לרשות הרבים, יש להשיב כי ברייתא זו הרי בהתאם לשיטת \u0003רבי היא,\u0004 ש\u0003אמר\u0004 רבי: \u0003כל דבר ש\u0004אסור לעשותו בשבת ואין איסורו מדין תורה אלא \u0003הוא משום שבות\u0004 (איסור מלאכה בשבת מדברי חכמים, כגון כרמלית) \u0003לא גזרו\u0004 בו חכמים \u0003עליו בין השמשות,\u0004 שהיא שעת הדמדומים שאינם לא ודאי יום ולא ודאי לילה. וכיון שבכדי שיחול העירוב די שיהיה ראוי לשימוש רגע אחד בין השמשות בערב שבת, הרי עירוב זה המונח בכרמלית מותר היה בשעתו.","ואמר לו רבא לרב אדא בר מתנא: \u0003ולא תימא דחויי קא מדחינא לך\u0004 \u0005[ואל תאמר שאני\u0006 רק \u0005דוחה אותך]\u0006 בתירוצים, \u0003אלא דוקא קאמינא\u0004 \u0005[במדוייק אני אומר]\u0006 \u0003לך.\u0004 שהשיטה שתשמיש על ידי הדחק אינו נחשב תשמיש הריהי שיטה מבוססת, והתירוצים הנם הסברים נאותים של אותה ברייתא. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אם היה רקק מים\u0004 (ביצה) \u0003ורשות הרבים מהלכת בו, הזורק לתוכה\u0004 מרחק \u0003ארבע אמות\u0004 — \u0003חייב\u0004 ככל מטלטל ארבע אמות ברשות הרבים. \u0003וכמה הוא\u0004 עומקו של \u0003רקק מים\u0004 זה — \u0003פחות מעשרה טפחים.\u0004 ועוד מוסיפה המשנה: \u0003רקק מים שרשות הרבים מהלכת בו הזורק לתוכו ארבע אמות\u0004 — \u0003חייב.\u0004","התמיהה על החזרה כמעט באותן מלים על אותו נושא ברורה, ועל כן: \u0003בשלמא\u0004 \u0005[נניח]\u0006 למה נשנו המילים \u0003\"רקק\" \"רקק\" תרי זימני\u0004 \u0005[שתי פעמים],\u0006 אפשר להסביר זאת כי \u0003חד\u0004 \u0005[\u0006במקרה \u0005אחד]\u0006 מדובר \u0003בימות החמה, וחד\u0004 \u0005[ו\u0006במקרה \u0005אחד]\u0006 מדובר \u0003בימות הגשמים. וצריכא\u0004 \u0005[וצריך]\u0006 להודיע לנו כי דין זה קיים גם בקיץ וגם בחורף. וטעמו של דבר — \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק \u0003בימות החמה,\u0004 היינו אומרים שהטעם הוא משום \u0003דעבידי אינשי לקרורי נפשיהו\u0004 \u0005[שעשויים אנשים לקרר\u0006 את \u0005עצמם]\u0006 ולכן עוברים דרך רקק המים. \u0003אבל בימות הגשמים אימא\u0004 \u0005[הייתי אומר]\u0006 ש\u0003לא. ו\u0004להיפך, \u0003אי אשמעינן\u0004 \u0005[אם היה משמיע לנו]\u0006 \u0003בימות הגשמים\u0004 בלבד הייתי אומר כי \u0003אגב דמטניף, מקרי ונחית\u0004 \u0005[ש\u0006הוא ממילא \u0005מטונף,\u0006 מלוכלך, \u0005קורה\u0006 שאינו מקפיד \u0005ונכנס]\u0006 לתוך הרקק, \u0003אבל בימות החמה\u0004 שאינו מלוכלך בבוץ, \u0003לא.\u0004 ועל כן \u0003צריכא\u0004 \u0005[הוצרכה]\u0006 המשנה לחזור על ענין הרקק פעמיים, להודיענו כי הלכה זו שייכת בכל עת.","\u0003אלא\u0004 הדגשת המשנה בענין \u0003הילוך\u0004 רשות הרבים בתוך אותו רקק \u0003תרי זימני\u0004 \u0005[שתי פעמים]\u0006 \u0003למה לי? אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד ממנה]\u0006 כי \u0003הילוך\u0004 אף \u0003על ידי הדחק\u0004 ולא בדרך קלה — \u0003שמיה\u0004 \u0005[שמו,\u0006 נקרא\u0005]\u0006 \u0003הילוך,\u0004 אבל \u0003תשמיש\u0004 \u0005[שימוש]\u0006 כאשר הוא רק \u0003על ידי הדחק,\u0004 בדוחק בלבד — \u0003לא שמיה תשמיש\u0004 \u0005[\u0006\u0005אין שמו,\u0006 אינו נקרא \u0005שימוש],\u0006 ולכן היה צריך להדגיש שרקק זה רשות הרבים מהלכת בו בפועל, שאם לא כן לא היה נחשב לרשות הרבים. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","בהקשר מסויים אל הכוורת שדובר באופן טלטול שאין בו חיוב, מביאים את מה ש\u0003אמר רב יהודה: האי זירזא דקני\u0004 \u0005[אותה חבילת קנים]\u0006 \u0003רמא וזקפיה, רמא וזקפיה\u0004 \u0005[\u0006ש\u0005השליכה והרימה, השליכה והרימה]\u0006 — \u0003לא מיחייב\u0004 \u0005[אינו מתחייב]\u0006 משום טילטולה ברשות הרבים \u0003עד דעקר ליה\u0004 \u0005[שיעקור אותה]\u0006 מעל גבי הקרקע, וכל עוד לא עקרה מעל גבי הקרקע — אף על פי שהוא מטלטלה דרך ארוכה — אין זה נחשב לעקירה והנחה האסורות על פי התורה, שכן תמיד נשאר חלק מן הקנים מונח.","עוד \u0003אמר מר\u0004 \u0005[החכם]:\u0006 יכול שיהא \u0003אדם עומד על האסקופה\u0004 \u0005[מפתן הדלת]\u0006 ויהא \u0003נוטל מבעל הבית\u0004 העומד ברשות היחיד \u0003ו\u0004כן \u0003נותן לו.\u0004 וכמו כן במקום זה \u0003נוטל מעני\u0004 העומד ברשות הרבים \u0003ונותן לו,\u0004 כי מקום פטור אין בו כל צד איסור וחיוב בטלטול והוצאה בשבת, ושואלים: \u0003האי\u0004 \u0005זאת\u0006 ה\u0003אסקופה מאי\u0004 \u0005[מהי],\u0006 באיזו איסקופה מדובר? שכן לאיסקופות שונות משמעות אחרת מבחינה הלכתית.","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהמדובר ב\u0003אסקופת\u0004 רשות הרבים, וכגון באיסקופת מבוי שאינה גבוהה שלושה טפחים מעל פני הקרקע, ואינה מקורה, והלחי המציין את תחום המבוי לפנים ממנה — כיצד אפשר לומר שהוא \u0003נוטל מבעל הבית? הא מפיק\u0004 \u0005[הרי\u0006 הוא \u0005מוציא]\u0006 \u0003מרשות היחיד לרשות הרבים!\u0004","\u0003ואלא\u0004 תאמר שמדובר ב\u0003אסקופת רשות היחיד,\u0004 וכגון שהיא מקורה, או שהיא נמצאת לפנים מן הלחי המציין את תחום המבוי, או שהיא גבוהה עשרה טפחים ושטחה לכל הפחות ארבעה על ארבעה טפחים — כיצד אפשר לומר שהוא \u0003נוטל מן העני? הא קא מעייל\u0004 \u0005[הרי הוא מכניס]\u0006 \u0003מרשות הרבים לרשות היחיד!\u0004","ו\u0003אלא\u0004 תאמר שהמדובר ב\u0003אסקופת כרמלית,\u0004 וכגון שאינה גבוהה עשרה טפחים ואולם יש בשטחה ארבעה על ארבעה טפחים — איך אפשר לומר כי הוא \u0003נוטל ונותן,\u0004 שמשמעו שמותר הדבר אפילו \u0003לכתחילה,\u0004 והרי \u0003סוף סוף איסורא מיהא איתא\u0004 \u0005[איסור בכל זאת יש בכך],\u0006 שאף שאין בכרמלית חיוב מן התורה, מכל מקום אסור הטלטול ממנה מדברי חכמים, וודאי אינו מותר לכתחילה!","\u0003אלא\u0004 יש לומר כי המדובר הוא ב\u0003אסקופה\u0004 ש\u0003מקום פטור בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 ולכן אין בה איסור כלל. וכיצד יכול להיות דבר כזה — \u0003כגון דלית ביה\u0004 \u0005[שאין בה]\u0006 \u0003ארבעה על ארבעה\u0004 טפחים, שאז איננה נחשבת כמקום לענין חיוב שבת. \u0003וכי הא דכי אתא\u0004 \u0005[וכמו\u0006 הלכה \u0005זו שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: מקום שאין בו ארבעה על ארבעה טפחים\u0004 והוא מוגדר לעצמו — \u0003מותר\u0004 גם \u0003לבני רשות היחיד ו\u0004גם \u0003לבני רשות הרבים לכתף עליו\u0004 בשבת, \u0003ובלבד שלא יחליפו\u0004 חפצים מרשות זו לרשות זו.","עוד \u0003אמר מר\u0004 \u0005[החכם]\u0006 בתוספתא, שאף אדם העומד על האיסקופה יכול הוא ליטול חפץ מבעל הבית וכן ליתן לו, וכן ליטול מן העני וליתן לו, \u0003ובלבד\u0004 שלא יחליפו ביניהם, \u0003שלא יטול מבעל הבית ונותן לעני, או\u0004 נוטל \u0003מעני ונותן לבעל הבית.\u0004 ואולם \u0003אם נטל ונתן\u0004 — \u0003שלשתן פטורין.\u0004 ושואלים: \u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר שתהא זו קושיה חמורה]\u0006 על \u0003רבא,\u0004 שכן \u0003אמר רבא : המעביר חפץ מתחילת ארבע\u0004 אמות \u0003לסוף ארבע\u0004 אמות \u0003ברשות הרבים\u0004 — \u0003אף על פי שהעבירו\u0004 למעלה מתחומה של רשות הרבים"],["\u0003דרך עליו,\u0004 שהגביה את החפץ בגובה שלמעלה מעשרה טפחים מפני קרקע רשות הרבים, שהוא מקום פטור, אף על פי כן \u0003חייב\u0004 משום טלטול ברשות הרבים. ואילו בתוספתא נאמר שאם עבר החפץ דרך מקום פטור, אינו חייב מן התורה בהעברתו מרשות לרשות! ודוחים, כי יש לחלק בין המקרים: \u0003התם\u0004 \u0005[שם]\u0006 בהלכה שקבע רבא \u0003לא נח\u0004 החפץ במקום פטור, אלא אך עבר באויר, ואולם \u0003הכא\u0004 \u0005[כאן],\u0006 דרך האיסקופה, הלא \u0003נח\u0004 החפץ במקום פטור, ועל ידי ההנחה נחלקה פעולת ההעברה לשתי פעולות נפרדות שאין בהן איסור מן התורה.","בהמשכה של התוספתא הובאה דעת \u0003אחרים\u0004 ה\u0003אומרים\u0004 כי \u0003אסקופה משמשת שתי רשויות: בזמן שהפתח פתוח\u0004 — בטלה האיסקופה לגבי הבית והריהי נחשבת \u0003כלפנים\u0004 הבית, כרשות היחיד. ובזמן שה\u0003פתח נעול\u0004 — אינה בטלה לגבי הבית, והריהי נחשבת \u0003כלחוץ,\u0004 כרשות הרבים.","ועל כך תוהים: כאשר הפתח פתוח הריהי נחשבת כרשות היחיד, \u0003ואף על גב דלית ליה\u0004 \u0005[ואף על פי שאין לה],\u0006 לאיסקופה זו \u0003לחי\u0004 בצידה?! \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חמא בר גוריא אמר רב: תוך הפתח,\u0004 כלומר, החלל שבכותל שבו נמצאת הדלת \u0003צריך לחי אחר\u0004 כדי \u0003להתירו\u0004 בטלטול, כלומר, יש להעמיד מעין מחיצה סמלית בצד הפתח כדי שייחשב גם חלל זה כסגור, ויהא מותר בטלטול כרשות היחיד גמורה. ואילו בתוספתא לא הוזכר כלל הצורך בלחי כזה!","\u0003וכי תימא דלית ביה\u0004 \u0005[ואם תאמר\u0006 שמדובר באיסקופה \u0005שאין בה]\u0006 \u0003ארבעה על ארבעה\u0004 טפחים ואינה חשובה מקום לעצמה, ולכך אינה צריכה לחי — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חמא בר גוריא אמר רב\u0004 במפורש: \u0003תוך הפתח, אף על פי שאין בו ארבעה על ארבעה\u0004 טפחים \u0003צריך לחי אחר\u0004 כדי \u0003להתירו\u0004 בטלטול!","על כך \u0003אמר רב יהודה אמר רב: הכא\u0004 \u0005[כאן]\u0006 \u0003באיסקופת מבוי עסקינן\u0004 \u0005[עוסקים אנו]\u0006 הפתוח לרשות הרבים רק מצד אחד, ומבוי זה נחשב מדין תורה כרשות היחיד, אלא שחכמים הצריכו לעשות לו כעין מחיצה רביעית סמלית. ומבוי זה היה מקורה, וקירוי זה מגיע גם לחלק מן האיסקופה, כך ש\u0003חציו מקורה וחציו שאינו מקורה, וקירויו כלפי פנים.\u0004 ובכגון זה אם היה ה\u0003פתח פתוח,\u0004 הרי דינו \u0003כלפנים,\u0004 שנחשב הקירוי שעל גביו כאילו היה יוצר מחיצה מלמעלה עד למטה (\"גוד אחית מחיצה\") וסותם את הפתח, ועושהו רשות היחיד. אך כאשר ה\u0003פתח נעול,\u0004 שוב אי אפשר לחשוב את הקירוי כמחיצה, ולכן אותו חלק מן האיסקופה הנמצא בחוץ נחשב \u0003כלחוץ,\u0004 כרשות הרבים.","\u0003רב אשי אמר: לעולם\u0004 אפשר לומר ש\u0003באיסקופת בית עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ובמקרה מיוחד, \u0003וכגון שקירה בשתי קורות,\u0004 שאותו קירוי שעל גבי האיסקופה היה עשוי משתי קורות נפרדות \u0003שאין בזו ארבעה\u0004 טפחים \u0003ואין בזו ארבעה\u0004 טפחים, \u0003ואין בין זו לזו\u0004 רווח של \u0003שלשה\u0004 טפחים, \u0003ו\u0004ה\u0003דלת\u0004 נמצאת \u0003באמצע,\u0004 בין שתי הקורות. ובמקרה כזה כאשר ה\u0003פתח פתוח,\u0004 נשאר חלל הפחות משלושה טפחים בין הקורות, ועל פי הכלל של לבוד, כל חלל פחות משלושה טפחים נחשב כסתום, ושתי הקורות נדונות כאילו היו קורה אחת בלבד, אשר מקצה החיצוני נחשבת היא כיוצרת מחיצה העושה את הפתח ולכן איסקופה זו נחשבת \u0003כלפנים,\u0004 כרשות היחיד גמורה. ואולם כאשר ה\u0003פתח נעול,\u0004 אין שתי הקורות מצטרפות עוד זו עם זו, שהרי הדלת ביניהן, וכיון שהקורה החיצונה פחותה מרוחב ארבעה טפחים, אינה נחשבת לתקרה היוצרת מחיצה עד למטה, ונמצא שהשטח שמתחת לקורה זו דינו \u0003כלחוץ,\u0004 כרשות הרבים.","עוד אמר \u0005[החכם]\u0006 בתוספתא ש\u0003אם היתה\u0004 ה\u0003איסקופה גבוהה עשרה\u0004 טפחים \u0003ורחבה ארבעה\u0004 טפחים על ארבעה, \u0003הרי זו רשות לעצמה,\u0004 אף אם היתה ברשות היחיד. ומעירים: דבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרב יצחק בר אבדימי.\u0004 ש\u0003אמר ר' יצחק בר אבדימי\u0004 ש\u0003אומר היה ר' מאיר: כל מקום שאתה מוצא שתי רשויות,\u0004 כלומר, שני מקומות שכל אחד מהם מוגדר למדי כדי להוות רשות לעצמה, אף על פי ש\u0003הן\u0004 מבחינה הלכתית \u0003רשות אחת,\u0004 ו\u0003כגון עמוד\u0004 העומד \u0003ברשות היחיד\u0004 והוא \u0003גבוה עשרה\u0004 טפחים \u0003ורחב ארבעה\u0004 על ארבעה, שלפי מידותיו הריהו נחשב רשות היחיד — \u0003אסור\u0004 מדברי סופרים \u0003לכתף עליו\u0004 ולקחת חפץ מקרקע רשות היחיד ולהניחו על גב העמוד, שהרי העמוד נידון לפי מידותיו כרשות בפני עצמה. וטעם הדבר — \u0003גזירה\u0004 היא שגזרו חכמים \u0003משום\u0004 מצב דומה של \u0003תל\u0004 בגובה זה \u0003ברשות הרבים.\u0004 וכיון שברשות הרבים יש בכך איסור מן התורה, משום הוצאה מרשות הרבים לרשות היחיד, אסרו חכמים שימוש בעמוד כזה אף ברשות היחיד."],["לאחר שעסקנו בנושא מצומצם ומוגדר של דיני הוצאות בשבת, עוברים לעסוק בדיני השבת על פי סדר קבלתה, ובראשונה מה הם הדברים שיש להמנע מהם לפני כניסת השבת. לגבי כל יום ויום אמרו: \u0003לא ישב אדם לפני הספר סמוך ל\u0004זמן תפילת \u0003מנחה עד שיתפלל.\u0004 וכן \u0003לא יכנס אדם למרחץ, ולא\u0004 יכנס לעשות מלאכתו ב\u0003בורסקי\u0004 (עיבוד עורות). \u0003ו\u0004כן לא יכנס \u0003לא לאכול\u0004 סעודתו \u0003ולא ל\u0004שבת ב\u0003דין\u0004 עד שיתפלל. \u0003ו\u0004אולם \u0003אם התחילו\u0004 כבר באותם הדברים — \u0003אין מפסיקין,\u0004 אינם חייבים להפסיק. וכלל אמרו: \u0003מפסיקין\u0004 בכל אלו הדברים \u0003לקרות קריאת שמע ואין מפסיקין לתפלה.\u0004","מתחילה היה צורך לברר את עצם הדברים במשנה, ושאלו: \u0003הי\u0004 \u0005[איזה]\u0006 \u0003\"סמוך למנחה\",\u0004 כלומר, סמוך לאיזו מנחה? שכן יש חלוקה בין זמן מנחה גדולה, שהוא כחצי שעה לאחר חצות היום ואילך, וזמן מנחה קטנה — שהוא כשעתיים וחצי לפני השקיעה. ומבררים: \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שאסור לעשות את כל אלה סמוך \u0003למנחה גדולה\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא? הא איכא\u0004 \u0005[\u0006ו\u0005הרי יש]\u0006 עדיין \u0003שהות ביום טובא\u0004 \u0005[הרבה]!\u0006 \u0003אלא\u0004 יש לומר שהמדובר הוא \u0003סמוך למנחה קטנה,\u0004","ואם כן רק במקרה זה \u0003אם התחילו אין מפסיקין.\u0004 ושואלים: \u0003נימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהיה\u0006 זו \u0005קושיה חמורה]\u0006 על דעת \u0003ר' יהושע בן לוי,\u0004 ש\u0003אמר\u0004 כי \u0003כיון שהגיע זמן תפלת המנחה אסור לאדם שיטעום כלום קודם שיתפלל תפלת המנחה.\u0004 ומשמע שאף אם כבר התחיל לאכול עליו להפסיק!","אלא יש לחזור מן ההסבר הקודם, ולומר כי \u0003לעולם\u0004 במשנה מדובר ב\u0003סמוך למנחה גדולה,\u0004 ודברי ר' יהושע בן לוי עוסקים בסמוך לזמן מנחה קטנה. וכדי להשיב על התמיהה שאם מדובר בסמוך לזמן מנחה גדולה יש אם כן שהות ביום — יש לפרש שכל אחד מן הדברים המנויים נעשה באופן שהוא גוזל זמן מרובה. וכשאמרו \"אל ישב אדם לפני הספר\" היתה הכוונה להסתפר \u0003בתספורת בן אלעשה,\u0004 שהיתה תספורתו מסובכת מאד והיה צורך בשעות אחדות כדי לעשותה. \u0003ו\u0004מה שאמרו שאל יכנס \u0003לא למרחץ\u0004 סמוך לזמן המנחה — הכוונה היא \u0003לכולא מילתא\u0004 \u0005[לכל דבר]\u0006 ה\u0003מרחץ,\u0004 ולא לרחיצה בלבד. אלא אף לחפיפה ורחיצה וזיעה. \u0003ולא\u0004 יכנס סמוך למנחה \u0003לבורסקי\u0004 — הכוונה היא \u0003לבורסקי גדולה\u0004 שיש צורך לעבד בה עורות מרובים, ולעשות כל מלאכת העיבוד מתחילתה. \u0003ולא\u0004 יכנס \u0003לאכול\u0004 — המדובר \u0003בסעודה גדולה\u0004 הנמשכת זמן רב. \u0003ולא\u0004 יכנס \u0003לדין\u0004 — הרי זה \u0003בתחילת דין\u0004 שיימשך זמן מרובה עד סיומו.","ואילו \u0003רב אחא בר יעקב אמר: לעולם\u0004 אפשר לפרש את המשנה בזמן מנחה גדולה ואף \u0003בתספורת דידן\u0004 \u0005[שלנו,\u0006 רגילה\u0005],\u0006 ו\u0003לכתחילה אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא ישב\u0004 לפני הספר סמוך לזמן המנחה — \u0003גזירה שמא ישבר הזוג\u0004 (המספריים), ועד שישיגו אחרים או יתקנו את המספריים יחלוף זמן מרובה. \u0003ו\u0004מה ששנינו ש\u0003לא\u0004 יכנס סמוך למנחה \u0003למרחץ\u0004 — אפילו \u0003להזיע בעלמא\u0004 \u0005[בלבד].\u0006 ו\u0003לכתחלה אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יכנס — \u0003גזירה\u0004 היא שגזרו חכמים \u0003שמא יתעלפה\u0004 \u0005[יתעלף]\u0006 במרחץ זה ועד שיעמוד מעלפונו ימשך הדבר זמן רב. \u0003ולא\u0004 יכנס סמוך למנחה \u0003לבורסקי\u0004 — אפילו \u0003לעיוני בעלמא\u0004 \u0005[להסתכל בלבד]\u0006 בעורות. ו\u0003לכתחלה אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יכנס — מתוך החשש \u0003דילמא חזי פסידא בזביניה ומטריד\u0004 \u0005[שמא יראה הפסד בסחורתו וייטרד],\u0006 ויבוא לתקן את מה שהתקלקל. \u0003ולא\u0004 יכנס \u0003לאכול בסעודה\u0004 סמוך לזמן המנחה — המדובר הוא \u0003בסעודה קטנה.\u0004 ו\u0003לכתחלה אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יכנס — מתוך החשש \u0003דילמא אתי לאמשוכי\u0004 \u0005[שמא יבוא להימשך]\u0006 באכילתו עד זמן מרובה. \u0003ולא\u0004 יכנס \u0003לדין\u0004 סמוך לזמן המנחה — מדובר אפילו \u0003בגמר דין.\u0004 ו\u0003לכתחלה אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יכנס — מתוך החשש \u0003דילמא חזי טעמא וסתר דינא\u0004 \u0005[שמא יראה טעם,\u0006 מנוגד למה שחשב מתחילה, \u0005ויסתור\u0006 את \u0005הדין]\u0006 כולו, ויהא צורך להתחיל הכל מתחילתו.","שנינו במשנה כי אם התחיל לעשות אחד מן הדברים האמורים, תספורת מרחץ בורסקי סעודה ודין, שוב אינו צריך להפסיק. על כך שאלו: \u0003מאימתי\u0004 נחשבת \u0003התחלת תספורת? אמר רב אבין: משיניח מעפורת\u0004 \u0005[עטיפה,\u0006 סדין\u0005]\u0006 \u0003של ספרין\u0004 (ספרים) \u0003על ברכיו. ומאימתי\u0004 נחשבת \u0003התחלת מרחץ? אמר רב אבין משיערה\u0004 (יסיר) \u0003מעפרתו\u0004 \u0005[עטיפתו,\u0006 הבגד העליון\u0005]\u0006 של הרוצה לרחוץ במרחץ \u0003ממנו,\u0004 כלומר, שיסיר את הסודר המכסה אותו, שהוא בגדו העליון. \u0003ומאימתי התחלת בורסקי?\u0004 — \u0003משיקשור בין כתיפיו\u0004 את סינור העור שבו הוא מכסה עצמו מלפניו (מאירי). \u0003ומאימתי\u0004 נחשבת \u0003התחלת אכילה?\u0004 — \u0003רב אמר: משיטול ידיו\u0004 לסעודה. \u0003ור' חנינא אמר: משיתיר חגורתו.\u0004","ומעירים: \u0003ולא פליגי\u0004 \u0005[ואינם חלוקים],\u0006 אלא \u0003הא\u0004 \u0005[זו]\u0006 שאמר ר' חנינא כי התחלת סעודה נחשבת משיתיר חגורתו, הרי זה \u0003לן\u0004 \u0005[לנו],\u0006 לבני בבל, שבבבל היו נוהגים כרגיל לחגור עצמם בחוזקה, והתחלת האכילה היא איפוא כשמתיר את חגורתו. \u0003והא\u0004 \u0005[וזו]\u0006 שאמר רב שהתחלת הסעודה נחשבת משיטול ידיו, הרי זה \u0003להו\u0004 \u0005[להם],\u0006 לבני ארץ ישראל שלא היו חוגרים בחוזקה ולכך התחלת הסעודה אצלם הריהי כשנוטל ידיו.","ומעין זה \u0003אמר אביי: הני חברין בבלאי, למאן דאמר\u0004 \u0005[אותם חברים,\u0006 תלמידי חכמים \u0005בבליים, ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003תפלת ערבית רשות, כיון דשרא ליה המייניה\u0004 \u0005[שהתיר לו\u0006 את \u0005חגורתו]\u0006 שוב \u0003לא מטרחינן ליה\u0004 \u0005[מטריחים אנו אותו]\u0006 להפסיק את סעודתו ולהתפלל. ותוהים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 שתפילת ערבית \u0003חובה\u0004 האם כן \u0003מטרחינן להו\u0004 \u0005[מטריחים אנו אותו]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003תפלת מנחה דלכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003חובה היא, ותנן\u0004 \u0005[ו\u0006בכל זאת \u0005שנינו\u0006 במשנתנו\u0005]\u0006 כי \u0003אם התחילו\u0004 באכילה — \u0003אין מפסיקין. ו\u0004על כך הרי \u0003אמר ר' חנינא:\u0004 זמן התחלת האכילה הוא \u0003משיתיר חגורו!\u0004"],["\u0003התם\u0004 \u0005[שם]\u0006 בזמן המנחה \u0003לא שכיחא\u0004 \u0005[מצויה]\u0006 \u0003שכרות,\u0004 שאין דרך לשתות הרבה באמצע היום, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 בערבית \u0003שכיחא\u0004 \u0005[מצויה]\u0006 \u0003שכרות,\u0004 ולכן היה מקום לגזור בזמן תפילת ערבית. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר להסביר כי \u0003במנחה, כיון דקביעא לה זימנא\u0004 \u0005[שקבוע לה זמן]\u0006 \u0003מירתת ולא אתי למפשע\u0004 \u0005[חושש\u0006 הוא \u0005ואינו בא לפשוע]\u0006 ולשכוח להתפלל. ואולם \u0003ערבית כיון דכולא ליליא\u0004 \u0005[שכל הלילה]\u0006 הוא \u0003זמן ערבית,\u0004 לכך הוא \u0003לא מירתת, ואתי למפשע\u0004 \u0005[אינו חושש, ויבוא להתרשל].\u0006 על עצם הדבר \u0003מתקיף לה\u0004 \u0005[שואל עליה]\u0006 \u0003רב ששת:\u0004 וכי \u0003טריחותא למיסר המייניה\u0004 \u0005[טרחה\u0006 היא \u0005לאזור\u0006 את \u0005חגורתו]?!\u0006 \u0003ועוד\u0004, אם טרחה היא, \u0003ליקו הכי וליצלי\u0004 \u0005[יקום כך,\u0006 בלי חגורה, \u0005ויתפלל]!\u0006 ומשיבים: יש צורך לחגור חגורה בתפילה, \u0003משום שנאמר: \"הכון לקראת אלהיך ישראל\"\u0004 (עמוס ד, יב), שצריך אדם להיות מוכן ומהודר בעמידתו לפני ה'.","מאחר והובא הפסוק \"הכון לקראת אלהיך ישראל\" מענין החיוב להכין עצמו באופן מהודר לתפילה, מביאים כי אכן \u0003רבא בר רב הונא רמי פוזמקי ומצלי\u0004 \u0005[היה לובש גרבים\u0006 יקרים \u0005ומתפלל]\u0006 ו\u0003אמר\u0004 שהוא עושה זאת ככתוב \u0003\"הכון לקראת\u0004 אלהיך ישראל \u0003\".\u0004 ואילו \u0003רבא\u0004 לא כך היה עושה, אלא בתפילתו \u0003שדי גלימיה, ופכר ידיה, ומצלי\u0004 \u0005[\u0006היה \u0005משליך,\u0006 מסיר את \u0005גלימתו, וחובק את ידיו, ומתפלל],\u0006 ו\u0003אמר\u0004 שעושה כן \u0003\"כעבדא קמיה מריה\"\u0004 \u0005[כעבד לפני אדוניו],\u0006 שמופיע בהכנעה יתירה. \u0003אמר רב אשי: חזינא ליה\u0004 \u0005[ראיתי אותו]\u0006 את \u0003רב כהנא כי איכא צערא בעלמא\u0004 \u0005[כאשר יש צער בעולם],\u0006 \u0003שדי גלימיה ופכר ידיה ומצלי\u0004 \u0005[\u0006היה \u0005משליך,\u0006 מסיר את \u0005גלימתו, וחובק את ידיו, ומתפלל],\u0006 ו\u0003אמר\u0004 שעושה כן \u0003\"כעבדא קמיה מריה\"\u0004 \u0005[כעבד לפני אדונו].\u0006 \u0003כי איכא שלמא\u0004 \u0005[כאשר יש שלום]\u0006 בעולם \u0003לביש ומתכסי\u0004 \u0005[\u0006היה \u0005לובש ומתכסה]\u0006 \u0003ומתעטף\u0004 בגלימה חשובה, \u0003ומצלי\u0004 \u0005[ומתפלל]\u0006 ו\u0003אמר\u0004 שעושה כן מכיון צריך לקיים \u0003\"הכון לקראת אלהיך ישראל\".\u0004","מאחר שדובר בתפילה, מסופר כי \u0003רבא חזייה\u0004 \u0005[ראהו]\u0006 את \u0003רב המנונא דקא\u0004 \u0005[שהוא]\u0006 \u0003מאריך בצלותיה\u0004 \u0005[בתפילתו].\u0006 \u0003אמר\u0004 עליו: \u0003מניחין חיי עולם,\u0004 את העיסוק בלימוד התורה, \u0003ועוסקים בחיי שעה,\u0004 בתפילה שיש בה בקשה על צרכי יום יום. ומסבירים: \u0003והוא,\u0004 רב המנונא, \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 כי \u0003זמן תפלה לחוד וזמן תורה לחוד,\u0004 וכשאדם מתפלל אינו נחשב כמחסיר בזמן התורה. מעין זה מסופר כי \u0003ר' ירמיה הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003ר' זירא והוו עסקי בשמעתא\u0004 \u0005[והיו עוסקים בהלכה].\u0006 \u0003נגה לצלויי והוה קא מסרהב\u0004 \u0005[נתאחר הזמן לתפילה והיה ממהר]\u0006 \u0003ר' ירמיה\u0004 לסיים את הנושא שעסקו בו כדי להתפלל. \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 \u0003ר' זירא\u0004 פסוק זה: \u0003\"מסיר אזנו משמע תורה גם תפלתו תועבה\"\u0004 (משלי כח, ט).","שנינו כי אם נכנס לדין סמוך לזמן תפילה, שוב אינו צריך להפסיק ולהתפלל. ומבררים: \u0003מאימתי\u0004 נחשבת \u0003התחלת דין?\u0004 — נחלקו בכך \u0003ר' ירמיה ור' יונה. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שתחילתו \u0003משיתעטפו הדיינים,\u0004 שהיו הדיינים מתעטפים בטליתם לפני שהיו מתחילים בדין. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שתחילת דין הרי היא \u0003משיפתחו בעלי דינים\u0004 בטענותיהם. ומעירים: \u0003ולא פליגי\u0004 \u0005[ואינם חלוקים]\u0006 אלא, \u0003הא\u0004 \u0005[זה]\u0006 שאומר משיפתחו בעלי דין, הרי זה באופן \u0003דעסקי ואתו בדינא\u0004 \u0005[ש\u0006כבר היו \u0005עוסקים ובאים בדין],\u0006 והיו הדיינים עטופים כבר. \u0003והא\u0004 \u0005[וזה]\u0006 שאומר משיתעטפו הדיינים, הרי זה באופן שעדיין \u0003לא עסקי ואתו בדינא\u0004 \u0005[היו עוסקים ובאים בדין],\u0006 ומשיתעטפו הרי זו התחלה.","ואגב הזכרת ענין הדין מסופר כי \u0003רב אמי ורב אסי הוו יתבי וגרסי ביני עמודי\u0004 \u0005[היו יושבים ולומדים בין העמודים]\u0006 מתחת לבית המדרש. \u0003וכל שעתא ושעתא\u0004 \u0005[שעה ושעה]\u0006 \u0003הוו טפחי אעיברא דדשא ואמרי\u0004 \u0005[היו טופחים על בריח הדלת ו\u0006היו \u0005אומרים]:\u0006 \u0003אי איכא דאית ליה דינא, ליעול וליתי\u0004 \u0005[אם יש\u0006 מישהו \u0005שיש לו דין, שיכנס ויבוא].\u0006 עוד מסופר כי \u0003רב חסדא ורבה בר רב הונא הוו יתבי בדינא כולי יומא, הוה קא חליש לבייהו\u0004 \u0005[היו יושבים בדין כל היום\u0006 ו\u0005נחלש ליבם]\u0006 מחמת אי אכילה. על כן \u0003תנא להו\u0004 \u0005[שנה להם]\u0006 \u0003רב חייא בר רב מדפתי\u0004 ברייתא על הנאמר \u0003\"\u0004ויהי ממחרת וישב משה לשפוט את העם \u0003ויעמד העם על משה מן הבקר עד הערב\"\u0004 (שמות יח, יג): \u0003וכי תעלה על דעתך שמשה\u0004 היה \u0003יושב ודן כל היום כלו?\u0004 שאם כן \u0003תורתו מתי נעשית?\u0004 מתי עסק בה? \u0003אלא\u0004 ודאי בא הכתוב \u0003לומר\u0004 לך כי \u0003כל דיין שדן דין אמת לאמיתו, אפילו\u0004 היה דן רק \u0003שעה אחת, מעלה עליו הכתוב כאילו נעשה שותף להקדוש ברוך הוא במעשה בראשית,\u0004 שכן על ידי דין אמת הוא מעמיד את העולם (המאירי). והדבר נלמד בדרך גזירה שווה: שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"ויעמוד העם על משה מן הבקר עד הערב\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 במעשה בראשית \u0003\"ויהי ערב ויהי בקר יום אחד\"\u0004 (בראשית א, ה), ומשמע כי הערב ומעט מן הבוקר נחשבים כיום שלם. ואף לענייננו די שישבו הדיינים בדין רק מקצת היום.","ועוד שואלים: \u0003עד מתי יושבין בדין?\u0004 מה הוא הזמן הרגיל לסיום מושב בית הדין? \u0003אמר רב ששת: עד זמן סעודה,\u0004 שהוא שעת הצהריים. \u0003אמר רב חמא: מאי קרא\u0004 \u0005[מהו הכתוב\u0006 המרמז על כך\u0005]?\u0006 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"אי לך ארץ שמלכך נער ושריך בבקר יאכלו. אשריך ארץ שמלכך בן חורים ושריך בעת יאכלו בגבורה ולא בשתי\"\u0004 (קהלת י, טז–יז). והוא מפרשו: השרים במדינה מתוקנת יושבים לסעוד רק אחרי שעסקו \u0003בגבורה של תורה\u0004 ובדין, \u0003ולא בשתייה של יין.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: אכילה ב\u0003שעה ראשונה\u0004 בבוקר — הרי זה \u0003מאכל לודים,\u0004 שהם בני אומה של אוכלי אדם, והם רעבתנים וממהרים לאכול. בשעה \u0003שניה\u0004 — הוא \u0003מאכל לסטים\u0004 (גנבים), שמאחר שעסקו בלילה בגניבה, הריהם מקדימים לאכול בבוקר. בשעה \u0003שלישית\u0004 — הוא זמן \u0003מאכל יורשים,\u0004 כלומר, של אנשים שירשו כסף רב ואינם עובדים לפרנסתם ולכך כל עיסקם בשעה מוקדמת של הבוקר באכילה. בשעה \u0003רביעית\u0004 — היא \u0003מאכל פועלים.\u0004 בשעה \u0003חמישית\u0004 — הוא \u0003מאכל כל אדם.\u0004","ושואלים: \u0003איני\u0004 \u0005[כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב פפא\u0004 ששעה \u0003רביעית\u0004 היא \u0003זמן סעודה לכל אדם!\u0004 אלא יש לתקן ולומר כי שעה \u0003רביעית\u0004 היא \u0003מאכל כל אדם.\u0004 בשעה \u0003חמישית\u0004 — הוא \u0003מאכל פועלים\u0004 שאינם מתפנים עד אז. ובשעה \u0003ששית\u0004 — הוא זמן \u0003מאכל תלמידי חכמים,\u0004 ועד אז זמן מושב בית הדין. ומוסיפים: האוכל \u0003מכאן ואילך\u0004 — הרי זה \u0003כזורק אבן לחמת\u0004 (לנאד), כלומר, שכבר אין זה מועיל לבריאות הגוף. \u0003אמר אביי: לא אמרן\u0004 \u0005[אמרנו]\u0006 שאכילה משעה ששית אינה מועילה, \u0003אלא\u0004 כש\u0003לא טעים מידי בצפרא\u0004 \u0005[טעם דבר בבוקר],\u0006 \u0003אבל\u0004 אם \u0003טעים מידי בצפרא\u0004 \u0005[טעם דבר בבוקר]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 דברים אלה.","אמר \u0003רב אדא בר אהבה: מתפלל אדם\u0004 אף מלכתחילה \u0003תפלתו בבית המרחץ. מיתיבי\u0004 \u0005[מקשים על\u0006 \u0003כך]\u0004 ממה ששנינו בתוספתא: \u0003הנכנס לבית המרחץ,\u0004 בחדר הראשון, \u0003מקום ש\u0004כל \u0003בני אדם עומדים לבושין\u0004 — הרי זה ככל מקום אחר ו\u0003יש שם מקרא\u0004 בתורה \u0003ותפלה. ואין צריך לומר\u0004 שמותרת בחדר זה \u0003שאילת שלום. ו\u0004יכול שיהא \u0003מניח\u0004 שם \u0003תפילין, ואין צריך לומר שאינו\u0004 חייב להיות \u0003חולץ\u0004 אותם.","ואילו בחדר הפנימי יותר, \u0003מקום ש\u0004בו \u0003בני אדם עומדים ערומים ולבושין,\u0004 ששם הם מתלבשים ומתפשטים \u0003יש שם שאילת שלום, ו\u0004אולם \u0003אין שם מקרא\u0004 בתורה \u0003ותפלה. ו\u0004אם הניח שם תפילין — \u0003אינו חולץ\u0004 את ה\u0003תפילין, ו\u0004אולם \u0003אינו מניח\u0004 שם תפילין \u0003לכתחלה.\u0004","ובחדר הפנימי שהוא \u0003מקום שבני אדם עומדין\u0004 שם רק כשהם \u0003ערומים\u0004 — \u0003אין שם שאילת שלום, ואין צריך לומר\u0004 שאין שם \u0003מקרא\u0004 בתורה \u0003ותפלה. ו\u0004אם נמצא שם כשהתפילין עליו — \u0003חולץ\u0004 את ה\u0003תפילין. ואין צריך לומר שאינו מניחן\u0004 שם מלכתחילה. ולכאורה דברי התוספתא סותרים למה שאמר רב אדא בר אהבה שהוא ודאי התכוון לחדר הפנימי שבמרחץ (שהוא לבדו קרוי מרחץ סתם) ולדעתו אפשר להתפלל שם לכתחילה!","ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב אדא בר אהבה\u0004 דבריו היה זה ב\u0003מרחץ\u0004 ריק \u0003שאין בו אדם.\u0004 ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוסי בר חנינא\u0004 שכל \u0003מרחץ שאמרו\u0004 שאסור בתפילה הרי זה \u0003אף על פי שאין בו אדם,\u0004 ו\u0003בית הכסא שאמרו\u0004 לענין איסור תפילה בו הרי זה \u0003אף על פי שאין בו צואה,\u0004 אלא ודאי כיון שהמקום משמש לדבר של גנאי אין ראוי להתפלל בו.","ומתרצים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב אדא\u0004 את דבריו, היה זה \u0003בחדתי\u0004 \u0005[ב\u0006מרחץ \u0005חדש]\u0006 שעדיין לא השתמשו בו לרחיצה. ושואלים: \u0003והא מבעיא בעא ליה\u0004 \u0005[והרי,\u0006 דבר זה, \u0005שאל אותו]\u0006 \u0003רבינא\u0004 את רב אדא באופן זה: מקום ש\u0003הזמינו\u0004 (הכינו) לצורך \u0003בית הכסא מהו\u0004 הדין לענין תפילה בתוכו, האם לענין זה \u0003יש\u0004 תוקף ל\u0003זימון,\u0004 שהוא הקובע לענין זה? \u0003או אין\u0004 תוקף הלכתי ל\u0003זימון? ו\u0004הרי \u0003לא איפשיטא ליה\u0004 \u0005[נפתרה לו]\u0006 בעיה זו. וכי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003הוא הדין למרחץ\u0004 שאף בו אותה בעיה? ומשיבים: \u0003לא, דילמא\u0004"],["\u0003שאני\u0004 \u0005[שונה]\u0006 \u0003בית הכסא דמאיס\u0004 \u0005[ש\u0006הוא \u0005מאוס],\u0006 וכשקוראים למקום 'בית הכסא' הרי יש בכך משום גנאי ושוב אינו ראוי לתפילה, אבל בית המרחץ — עד שירחץ בו ממש.","שנינו בתוספתא ש\u0003אין שם\u0004 בבית המרחץ \u0003שאילת שלום.\u0004 ומעירים כי דבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרב המנונא\u0004 שאמר \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא\u0004 ש\u0003אמר : אסור לאדם שיתן\u0004 (ישאל) \u0003שלום לחבירו בבית המרחץ, משום\u0004 שהמלה \"שלום\" היא כינויו של ה', וכפי \u0003שנאמר: \"\u0004ויבן שם גדעון מזבח לה' \u0003ויקרא לו ה' שלום\"\u0004 (שופטים ו', כד), ולכן אסור להזכירה במקום מבוזה.","ושואלים: \u0003אלא מעתה\u0004 לפי זה לשון \u0003\"הימנותא\" נמי\u0004 \u0005[\"נאמנות\" גם כן]\u0006 \u0003אסור\u0004 יהיה \u0003למימר\u0004 \u0005[לומר]\u0006 \u0003בבית הכסא, דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"האל הנאמן\u0004 שומר הברית והחסד\u0003\"\u0004 (דברים ז, ט). \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003הכי נמי\u0004 \u0005[כך הוא גם כן],\u0006 שאכן אסור לומר לשון נאמנות בבית הכסא, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא בר מחסיא, אמר רב חמא בר גוריא, אמר רב\u0004 כי \u0003שרי למימר \"הימנותא\"\u0004 \u0005[מותר לומר\u0006 לשון \u0005\"נאמנות\"]\u0006 \u0003בבית הכסא!\u0004 ומשיבים: יש הבדל בין הכינויים, \u0003התם\u0004 \u0005[שם]\u0006 \u0003שם\u0004 ה' \u0003גופיה\u0004 \u0005[עצמו]\u0006 \u0003לא איקרי הכי\u0004 \u0005[נקרא כך],\u0006 \u0003דמתרגמינן \"אלהא מהימנא\"\u0004 \u0005[ש\u0006כן \u0005אנו מתרגמים \"האל הנאמן\"],\u0006 ואולם \u0003הכא שם\u0004 ה' \u0003גופיה\u0004 \u0005[עצמו]\u0006 \u0003איקרי\u0004 \u0005[נקרא]\u0006 \u0003\"שלום \",דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ויקרא לו ה' שלום\",\u0004 ואין זה כינוי, אלא שם מקודש לעצמו.","אגב הזכרת דבר הלכה משמו, מביאים עוד מה ש\u0003אמר רבא בר מחסיא\u0004 שכך \u0003אמר רב חמא בר גוריא\u0004 שכך \u0003אמר רב: הנותן מתנה לחבירו, צריך להודיעו\u0004 שהוא נותן לו. וכפי \u0003שנאמר: \"\u0004אך את שבתותי תשמורו כי אות היא ביני וביניכם לדורותיכם \u0003לדעת כי אני ה' מקדשכם\"\u0004 (שמות לא, יג). הרי שכאשר נתן הקדוש ברוך הוא לישראל את השבת, אמר למשה להודיע להם על כך. \u0003תניא נמי הכי\u0004 \u0005[שנוייה\u0006 ברייתא \u0005גם כן כך]:\u0006 נאמר \u0003\"כי אני ה' מקדשכם\",\u0004 וכוונת הכתוב: \u0003אמר לו הקדוש ברוך הוא למשה: מתנה טובה יש לי בבית גנזי ו\"שבת \" שמה, ואני מבקש ליתנה לישראל, לך והודיעם\u0004 על כך. ו\u0003מכאן\u0004 — \u0003אמר רבן שמעון בן גמליאל\u0004 — למדנו כי \u0003הנותן\u0004 מתנה \u0003פת לתינוק, צריך להודיע לאמו\u0004 שנתן לו. ושואלים: \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005לו,\u0006 לתינוק\u0005]\u0006 כדי שבכך יודיע לאמו שנתן לו מתנה? \u0003אמר אביי: שאיף ליה משחא, ומלי ליה כוחלא\u0004 \u0005[ימשחנו בשמן,\u0006 או \u0005ישים כחול סביב לעינו],\u0006 כדי שיהא ניכר בו שינוי, וכשתראה אמו של הילד ותשאל אותו על כך, יספר לה שפלוני נתן לו פת לחם. \u0003והאידנא דחיישינן\u0004 \u0005[ועכשיו שחוששים אנו]\u0006 \u0003לכשפים\u0004 על ידי שמן או \u0003כחול, מאי\u0004 \u0005[מה]\u0006 יעשה הנותן? \u0003אמר רב פפא: שאיף ליה\u0004 \u0005[ימשח לו]\u0006 \u0003מאותו המין\u0004 שנתן לו לאכול.","על עצם הענין שואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חמא בר חנינא: הנותן מתנה לחבירו אין צריך להודיעו,\u0004 וכפי שמצאנו שאף שהקדוש ברוך עשה שקרן עור פני משה, בכל אופן \u0003נאמר\u0004 על משה: \u0003\"ומשה לא ידע כי קרן עור פניו בדברו אתו\"\u0004 (שמות לד, כט)! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאינו צריך להודיעו הרי זה \u0003במילתא דעבידא לאגלויי\u0004 \u0005[בדבר שעשוי להתגלות].\u0006 ואילו \u0003הא\u0004 \u0005[זה\u0006\u0003]\u0004 שאמרנו שצריך להודיעו הרי זה \u0003במילתא דלא עבידא לאגלויי\u0004 \u0005[שאינו עשוי להגלות].\u0006 ושואלים: אם כן, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שבת דעבידא לגלויי\u0004 \u0005[שעשוייה להיגלות],\u0006 שהרי יצטרכו להודיעה בתוך המצוות, ומדוע נתבקש משה להודיע על כך במיוחד? ומשיבים: \u0003מתן שכרה לא עביד לגלויי\u0004 \u0005[אינו עשוי להגלות],\u0006 ומתנה טובה מעין זו היה צורך להודיע.","ומסופר כי \u0003רב חסדא הוה נקיט בידיה תרי מתנתא דתורא\u0004 \u0005[אחז בידו שתי מתנות\u0006 כהונה \u0005שבשור],\u0006 ו\u0003אמר: כל מאן דאתי ואמר\u0004 \u0005[מי שיבוא ויאמר]\u0006 \u0003לי שמעתתא חדתא משמיה\u0004 \u0005[הלכה חדשה משמו]\u0006 של \u0003רב יהיבנא ליה ניהליה\u0004 \u0005[אתן\u0006 אותן \u0005לו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר מחסיא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: הנותן מתנה לחבירו צריך להודיעו.\u0004 וכפי \u0003שנאמר: \"לדעת כי אני ה' מקדשכם\". יהבה ניהליה\u0004 \u0005[נתן אותה,\u0006 את המתנה, \u0005לו]\u0006 לרבא בר מחסיא. אמר רבא בר מחסיא לרב חסדא: וכי \u0003חביבין עלך שמעתתא\u0004 \u0005[חביבות עליך ההלכות]\u0006 של \u0003רב כולי האי\u0004 \u0005[כל כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003אין\u0004 \u0005[כן].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא בר מחסיא: \u0003היינו\u0004 \u0005[זהו]\u0006 ש\u0003אמר רב: מילתא אלבישייהו יקירא\u0004 \u0005[המילת יקר ללובשיו]\u0006 (יעב\"ץ), כלומר, רק אדם הרגיל בדברים מעודנים יודע להעריך את טיבם. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 רב חסדא בהתפעלות: וכי \u0003אמר רב הכי\u0004 \u0005[כך]?!\u0006 \u0003בתרייתא עדיפא\u0004 \u0005[האחרונה עדיפה]\u0006 \u0003לי מקמייתא\u0004 \u0005[מן הראשונה],\u0006 \u0003ואי הוה נקיטנא אחריתי, יהיבנא\u0004 \u0005[ואילו הייתי מחזיק\u0006 מתנה \u0005אחרת, הייתי נותן\u0006 אותה\u0005]\u0006 \u0003לך.\u0004","\u0003ו\u0004עוד \u0003אמר רבא בר מחסיא, אמר רב חמא בר גוריא, אמר רב: לעולם אל ישנה אדם בנו\u0004 האחד \u0003בין\u0004 שאר \u0003הבנים,\u0004 שלא יפלה אותו לטובה. \u0003שבשביל משקל שני סלעים מילת שנתן יעקב ליוסף\u0004 כשעשה לו כתונת פסים \u0003יותר משאר בניו, נתקנאו בו אחיו ונתגלגל הדבר וירדו אבותינו למצרים.\u0004","ועוד \u0003אמר רבא בר מחסיא, אמר רב חמא בר גוריא, אמר רב: לעולם יחזר אדם\u0004 ויחפש \u0003וישב בעיר שישיבתה קרובה,\u0004 כלומר, שנוסדה לא מכבר, \u0003שמתוך שישיבתה קרובה עונותיה מועטין,\u0004 שלא הספיקו עדיין לחטוא בה כל כך. וכפי \u0003שנאמר\u0004 שאמר לוט למלאך: \u0003\"הנה נא העיר הזאת קרובה לנוס שמה והיא מצער\"\u0004 (בראשית יט, כ), \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 המלה \u0003\"קרובה\"? אילימא\u0004 \u0005[אם תאמר]:\u0006 \u0003דמיקרבא וזוטא\u0004 \u0005[שקרובה,\u0006 במרחק, \u0005וקטנה\u0006 ממש\u0005],\u0006 — לשם מה לו לומר זאת למלאך? \u0003והא קא חזו לה\u0004 \u0005[והרי הם רואים אותה]!\u0006 \u0003אלא\u0004 יש לומר כי משמעות \"קרובה\" — \u0003מתוך שישיבתה קרובה,\u0004 שנתיישבה מקרוב, לכן \u0003עונותיה מוצערין\u0004 (מעטים). \u0003אמר רב אבין: מאי קרא\u0004 \u0005[מה הכתוב]\u0006 המלמד שצוער היתה צעירה יותר משאר הערים? — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"אמלטה נא שמה\"\u0004 (בראשית יט, כ). \u0003\"נא\" בגימטריא\u0004 — \u0003חמשין ואחת\u0004 הוא, \u0003ו\u0004אילו הגימטריא \u0003של סדום\u0004 היא \u0003חמישים ושתים. ושלותה\u0004"],["של סדום שבה עשו את חטאיהם היתה בסך הכל \u0003עשרים ושש\u0004 שנים, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"שתים עשרה שנה עבדו את כדרלעמר ושלש עשרה שנה מרדו. ובארבע עשרה שנה\u0004 בא כדרלעומר\u0003\"\u0004 (בראשית יד, ד–ה). ושתים עשרה שנה וארבע עשרה שנה יחד שבהן היו משועבדים אינן ימי שלוה, ורק עשרים ושש שנים אחרות היו להם לשלוה ולחטא.","\u0003ו\u0004עוד \u0003אמר רבא בר מחסיא אמר רב חמא בר גוריא אמר רב: כל עיר שגגותיה גבוהים מבית הכנסת לסוף\u0004 היא \u0003חרבה,\u0004 משום בזיון בית הכנסת. ורמז לדבר ממה \u0003שנאמר: \"לרומם את בית אלהינו ולהעמיד את חרבתיו\"\u0004 (עזרא ט, ט), שהבית המיוחד לה' צריך להיות מרומם מן השאר. ומוסיפים: \u0003והני מילי בבתי\u0004 \u0005[ודברים אלה נאמרו ב\u0006גובה ה\u0005בתים]\u0006 עצמם, \u0003אבל בקשקושי ואברורי לית לן\u0004 \u0005[בעמודים ובמגדלים,\u0006 היוצאים מן הבית, \u0005אין לנו]\u0006 \u0003בה\u0004 איסור. \u0003אמר רב אשי: אנא עבדי\u0004 \u0005[אני עשיתי]\u0006 \u0003ל\u0004עיר \u0003מתא מחסיא\u0004 ש\u0003לא חרבה\u0004 \u0005[תחרב],\u0006 שבנה את בית הכנסת והגביהו משאר הבתים. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003חרבה\u0004 מתא מחסיא לבסוף! ומשיבים: על כל פנים, \u0003מאותו עון לא חרבה ,\u0004 אלא עוונות אחרים גרמו לכך.","\u0003ו\u0004עוד \u0003אמר רבא בר מחסיא אמר רב חמא בר גוריא אמר רב:\u0004 מוטב להיות \u0003תחת\u0004 עולו של \u0003ישמעאל ולא תחת\u0004 עולו של \u0003נכרי\u0004 (רומאים). \u0003תחת נכרי ולא תחת חבר\u0004 (כהני האש הפרסיים). \u0003תחת חבר ולא תחת תלמיד חכם.\u0004 שאם יחטא כנגד תלמיד חכם הממונה עליו יקפיד עליו ויענש בידי שמים. \u0003תחת תלמיד חכם ולא תחת יתום ואלמנה,\u0004 לפי שהם נעלבים בקלות והבטיח ה' שישמע צעקתם ויעניש את הפוגעים בהם.","\u0003ו\u0004עוד \u0003אמר רבא בר מחסיא אמר רב חמא בר גוריא אמר רב:\u0004 עדיף להיות חולה ב\u0003כל חולי\u0004 ממושך, \u0003ולא\u0004 ב\u0003חולי מעים.\u0004 וכן עדיף לסבול \u0003כל כאב\u0004 ואפילו חד וקשה, \u0003ולא כאב לב. כל מיחוש\u0004 קל, \u0003ולא מיחוש ראש. כל רעה, ולא אשה רעה.\u0004","\u0003ו\u0004עוד \u0003אמר רבא בר מחסיא אמר רב חמא בר גוריא אמר רב:\u0004 גם \u0003אם יהיו כל הימים דיו, ו\u0004ה\u0003אגמים\u0004 (קני הסוף הגדלים ליד המים) יהיו \u0003קולמוסים\u0004 לכתיבה, \u0003ו\u0004ה\u0003שמים\u0004 יהיו \u0003יריעות\u0004 עליהם ייכתבו הדברים, \u0003וכל בני אדם\u0004 יהיו \u0003לבלרין\u0004 (סופרים) — \u0003אין\u0004 כל אלה \u0003מספיקים לכתוב חללה של רשות,\u0004 כלומר, את כל הדברים שהממשלה צריכה לדאוג ולטפל בהם. \u0003אמר רב משרשיא: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך? — \u0003\"שמים לרום וארץ לעמק ולב מלכים אין חקר\"\u0004 (משלי כה, ג).","\u0003ו\u0004עוד \u0003אמר רבא בר מחסיא אמר רב חמא בר גוריא אמר רב: יפה תענית ל\u0004בטל \u0003חלום\u0004 רע \u0003כאש\u0004 השורפת את ה\u0003נעורת. אמר רב חסדא: ו\u0004התענית מועילה דווקא \u0003בו ביום\u0004 שחלם. \u0003ואמר רב יוסף:\u0004 אם אדם מצטער על חלום רע שחלם מותר לו להתענות \u0003אפילו בשבת.\u0004","ומסופר כי \u0003רב יהושע בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב אשי. עבדי ליה עיגלא תילתא\u0004 \u0005[עשו לו עגל מובחר].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לטעום מר מידי\u0004 \u0005[יטעם אדוני משהו].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בתענית יתיבנא\u0004 \u0005[יושב אני].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ו\u0004כי \u0003לא סבר ליה מר להא\u0004 \u0005[סבור אדוני\u0006 הלכה \u0005זו]\u0006 שאמר \u0003רב יהודה?\u0004 שכן \u0003אמר רב יהודה: לוה אדם תעניתו\u0004 ואינו מתענה ביום מסויים, \u0003ופורע\u0004 ומתענה תענית זו ביום אחר, ואם כן יכול אף אתה לדחות תעניתך ליום אחר! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003תענית חלום הוא. ו\u0004עליה \u0003אמר רבא בר מחסיא אמר רב חמא בר גוריא אמר רב: יפה תענית ל\u0004בטל \u0003חלום\u0004 רע \u0003כאש\u0004 השורפת את ה\u0003נעורת.\u0004 והוסיף \u0003ואמר\u0004 על כך \u0003רב חסדא\u0004 כי התענית מועילה דווקא \u0003בו ביום\u0004 שחלם. \u0003ואמר\u0004 על כך \u0003רב יוסף\u0004 שאם אדם מצטער על חלום רע שחלם מותר לו להתענות \u0003אפילו בשבת.\u0004","שנינו במשנה כי \u0003אם התחילו\u0004 כבר בכל אחד מן העיסוקים \u0003אין מפסיקין\u0004 לתפלה, אבל \u0003מפסיקין לקריאת שמע.\u0004 ושואלים: \u0003הא תנא ליה רישא\u0004 \u0005[הרי\u0006 שנה אותו כבר \u0005בראש\u0006 המשנה\u0005]\u0006 ש\u0003אין מפסיקין,\u0004 ומשום מה חוזר שוב לדבר זה? ומשיבים: \u0003סיפא אתאן\u0004 \u0005[בסוף\u0006 המשנה \u0005באנו]\u0006 \u0003ל\u0004דון ב\u0003דברי תורה,\u0004 שגם בהם יש לנהוג כך. וכפי \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003חברים\u0004 (תלמידי חכמים) \u0003שהיו עוסקים בתורה\u0004 — \u0003מפסיקין\u0004 מתורתם \u0003ל\u0004קרוא \u0003קריאת שמע, ו\u0004אולם \u0003אין מפסיקין לתפלה. אמר ר' יוחנן:\u0004 יש לסייג את הדברים ולא כי \u0003לא שנו\u0004 שאין מפסיקים בתפילה \u0003אלא כגון ר' שמעון בן יוחאי וחביריו שתורתן אומנותן\u0004 (מקצועם) ואינם מפסיקין כלל מלימודה. \u0003אבל כגון אנו,\u0004 העוסקים גם בדברים אחרים, \u0003מפסיקין\u0004 בין \u0003קריאת שמע\u0004 בין \u0003לתפלה.\u0004","על עיקר הדברים שואלים: \u0003והתניא\u0004 \u0005[והרי שנינו]\u0006 בברייתא אחרת: \u0003כשם שאין מפסיקין לתפלה, כך אין מפסיקין לקריאת שמע!\u0004 ומשיבים: \u0003כי תני ההיא\u0004 \u0005[כאשר שנויה\u0006 ברייתא \u0005זו]\u0006 — לגבי העוסקים \u0003בעיבור השנה\u0004 היא שנויה. שכיון שעיסוקם חשוב ביותר, ועל פיו נקבעים כל מועדי השנה, התירו להם שלא לקרוא קריאת שמע. וכפי ש\u0003אמר רב אדא בר אהבה, וכן תנו סבי\u0004 \u0005[שנו זקני]\u0006 העיר \u0003הגרוניא\u0004 שכך \u0003אמר ר' אלעזר בר' צדוק: כשהיינו עוסקין בעיבור השנה ביבנה לא היינו מפסיקין לא לקריאת שמע ולא לתפלה.\u0004","משנה זו עוסקת בהרחקות שונות, ובעיקר בדיני שבת, שנעשו כדי להרחיק אדם מעבירה שהיה עשוי לעשותה על ידי שיגרה והרגל. ואמרו: \u0003לא יצא החייט\u0004 כש\u0003מחטו\u0004 אצלו \u0003סמוך לחשכה\u0004 של ערב שבת, \u0003שמא ישכח\u0004 שהוא מטלטל את המחט \u0003ויצא\u0004 עמה ברשות הרבים אף כשיגיע ליל השבת. \u0003ו\u0004כן \u0003לא\u0004 יצא \u0003הלבלר בקולמוסו\u0004 מאותו טעם. \u0003ו\u0004כמו כן \u0003לא יפלה את כליו\u0004 (יבדוק אותם מן הכינים) בשבת, \u0003ולא יקרא\u0004 אדם בספר \u0003לאור הנר,\u0004 שלא יבוא לתקן את פתילת הנר. ואולם \u0003באמת אמרו\u0004 הלכה קבועה, שה\u0003חזן\u0004 יכול שיהא \u0003רואה היכן,\u0004 באיזה מקום בספר ה\u0003תינוקות\u0004 הנמצאים תחת השגחתו \u0003קוראין\u0004 בתורה, ואף לאור הנר בשבת, \u0003אבל הוא\u0004 עצמו \u0003לא יקרא. כיוצא בו\u0004 קבעו גזירה דומה לכך גם בהלכות אחרות, שאמרו: \u0003לא יאכל הזב\u0004 אף \u0003עם\u0004 אשתו \u0003הזבה\u0004 אף על פי ששניהם טמאים, \u0003מפני\u0004 שעל ידי אכילתם יחד יבואו לקרבה יתירה ולידי \u0003הרגל עבירה.\u0004","מדיני הגזירות שנגזרו שמא יעבור אדם עבירה \u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 \u0003לא יעמוד אדם ברשות היחיד וישתה\u0004 מים המצויים \u0003ברשות הרבים,\u0004 או להיפך, שיעמוד \u0003ברשות הרבים וישתה ברשות היחיד,\u0004 שמא יעביר את הכלי שהוא שותה בו מים למקום שהוא עומד בו, ויתחייב חטאת. \u0003אבל אם הכניס\u0004 את \u0003ראשו ורובו למקום שהוא שותה\u0004 — אין לחשוש עוד, ו\u0003מותר.\u0004"],["\u0003וכן בגת.\u0004","לאור ההלכה הנשנית במשנה זו \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לבני הישיבה: \u0003כרמלית מאי\u0004 \u0005[מה]\u0006 דינה לענין זה? האם מותר לעמוד ברשות אחת ולשתות בכרמלית, או לא? \u0003אמר אביי: היא היא,\u0004 שכשם שאסרו מרשות היחיד לרשות הרבים ולהיפך, כך אסרו בכרמלית ורשות אחרת. \u0003רבא אמר:\u0004 אין הדבר אסור, כי \u0003היא גופא\u0004 \u0005[עצמה]\u0006 האיסור לשתות ברשות אחרת, אינו אלא \u0003גזירה\u0004 שמא יבוא לידי טלטול, \u0003ואנן ניקום\u0004 \u0005[נעמוד]\u0006 \u0003ונגזור גזירה לגזירה?\u0004 ואף שאסרו ברשות שמן התורה, אין להוסיף בדומה גזירה גם בכרמלית שהיא מדברי חכמים.","\u0003אמר אביי: מנא אמינא לה\u0004 \u0005[מניין אומר אני אותה\u0006 הלכה\u0005]\u0006 — ממה \u0003דקתני\u0004 \u0005[ששנינו]\u0006 בסופה של המשנה: \u0003\"וכן בגת\".\u0004 ומעתה יש לברר \u0003מאי\u0004 \u0005[מהי]\u0006 ה\u0003גת\u0004 מבחינת רשויות השבת? \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהיא \u0003רשות היחיד\u0004 — הלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 אותה! \u0003אי\u0004 \u0005[אם]\u0006 היא \u0003רשות הרבים\u0004 — הלא אף זה \u0003תנינא\u0004 \u0005[שנינו].\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שגת זו \u0003כרמלית\u0004 היא, והרי שאף הכרמלית נאסרה במשנה.","ו\u0003רבא אמר:\u0004 מה שאמרו במשנה \u0003\"וכן בגת\"\u0004 אינו שייך לדיני שבת, כי אם \u0003לענין\u0004 דיני \u0003מעשר. וכן אמר רב ששת:\u0004 מה ששנינו במשנה \u0003\"וכן בגת\"\u0004 — \u0003לענין מעשר\u0004 שנינו זאת. וכפי \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שותין\u0004 לכתחילה את מיץ הענבים במישרין \u0003על\u0004 (מן) \u0003הגת\u0004 בלי לעשרו, \u0003בין על החמין,\u0004 שמזגו במים חמים, אף כי בכגון זה שוב אינו יכול להחזיר את היין הנותר לגת, כיון שיכול הוא להחמיץ את כל היין שבגת, ו\u0003בין על הצונן,\u0004 שמזגו במים צוננים, שבכגון זה יכול להחזיר את היין הנותר, \u0003ופטור. כי\u0004 שתיה כזו נחשבת לשתיית ארעי, וכל שאיננו אכילת קבע פטור מן המעשר, אלו \u0003דברי ר' מאיר. ר' אלעזר בר' צדוק מחייב\u0004 הפרשת מעשר בכל מקרה. \u0003וחכמים אומרים:\u0004 יש להבחין, ולומר כי \u0003על החמין,\u0004 אם מזג את היין במים חמים, כיון שאינו יכול להחזיר את מותר היין לגת הריהו \u0003חייב\u0004 במעשר, שהרי זו כשתיית קבע החייבת במעשר. ואולם \u0003על הצונן,\u0004 אם מזג את היין במים צוננים — הריהו \u0003פטור, מפני שהוא מחזיר את המותר\u0004 לגת, והרי זו שתיית ארעי הפטורה מן המעשר. ומשנתנו האומרת \"וכן בגת\", משמעה שרק אם היה ראשו ורובו בגת מותר לו לשתות ללא הפרשת מעשר, ואינה עוסקת במשפט זה בענין שבת כלל (ר\"ח).","כדי להביא ראיה לשיטת אביי מביאים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003לא יצא החייט במחטו סמוך לחשיכה שמא ישכח ויצא. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן באופן שהיתה המחט \u0003תחובה לו בבגדו?\u0004 ובמקרה זה גם אם יצא במחט זאת לרשות הרבים לא יתחייב מן התורה, לפי שאין זו דרך הוצאה וטלטול, אלא רק גזירת חכמים היא (שבות) שלא יוציא אף בדרך זו. ולא זו בלבד שאסרו לצאת במחט זו, אלא אף הוסיפו גזירה לגזירה, ואסרו על החייט לצאת במחטו אפילו סמוך לחשיכה. הרי שבדיני הוצאה בשבת גוזרים חכמים גזירה לגזירה (תוספות). ואם כן, גם בדין כרמלית גזרו חכמים, והרי זו הוכחה לשיטת אביי. ודוחים: \u0003לא,\u0004 מדובר כאן \u0003דנקיט ליה בידיה\u0004 \u0005[שהוא מחזיק אותה,\u0006 את המחט, \u0005בידו],\u0006 וזו מלאכת הוצאה גמורה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו בברייתא במפורש: \u0003לא יצא החייט במחטו התחובה בבגדו. מאי לאו\u0004 \u0005[האם לא]\u0006 המדובר כאן בשיוצא \u0003בערב שבת,\u0004 והרי שגזרו גזירה לגזירה, וכדברי אביי. ודוחים: \u0003לא, כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 הרי זה רק על יציאה \u0003בשבת. והתניא\u0004 \u0005[והרי שנינו]\u0006 בברייתא מפורשת: \u0003לא יצא החייט במחטו התחובה בבגדו בערב שבת עם חשיכה,\u0004 והרי שגזרו גזירה לגזירה, וכדברי אביי. ודוחים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו של מי היא]?\u0006 — של \u0003ר' יהודה היא,\u0004 שהוא \u0003אמר\u0004 ש\u0003אומן\u0004 המוציא חפץ \u0003דרך אומנתו,\u0004 אף שכרגיל אין אחרים מוציאים כך, האומן עצמו \u0003חייב,\u0004 שלגביו זו היא הדרך הרגילה.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יצא החייט במחטו התחובה לו בבגדו, ולא נגר בקיסם שבאזנו,\u0004 שהיה הנגר שם מאחורי אזנו קיסם, כעין סרגל, לצורך המלאכה, \u0003ולא סורק\u0004 צמר \u0003ב\u0004חוט \u0003משיחה\u0004 שבו הוא רגיל לקשור את חבילות הצמר והמונח כרגיל על \u0003אזנו, ולא\u0004 יצא ה\u0003גרדי\u0004 (אורג) \u0003באירא\u0004 \u0005[פקעת צמר]\u0006 \u0003שבאזנו\u0004 המשמשת לו לצורך המלאכה, \u0003ולא\u0004 יצא \u0003צבע בדוגמא\u0004 של צמר צבוע \u0003שבצוארו, ולא שולחני בדינר שבאזנו. ו\u0004בכל המקרים הללו \u0003אם יצא\u0004 — \u0003פטור\u0004 מן התורה, \u0003אבל אסור\u0004 מדברי סופרים, אלו \u0003דברי ר' מאיר. ר' יהודה אומר: אומן\u0004 המוציא בשבת חפץ בדרך שהיא \u0003דרך אומנתו\u0004 — \u0003חייב\u0004 מן התורה, \u0003ושאר כל אדם\u0004 המוציא באותה דרך — \u0003פטור,\u0004 אבל אסור.","כיון שהוזכרה מחלוקת ר' מאיר ור' יהודה בדין הנושא חפץ שלא כדרך הוצאתו, דנים בסתירה בין שתי ברייתות בנושא זה. \u0003תני חדא\u0004 \u0005[שנינו\u0006 בברייתא \u0005אחת]:\u0006 \u0003לא יצא הזב\u0004 בשבת \u0003בכיסו\u0004 שהוא קושר לאברו כדי לקבל בו את הזוב, \u0003ואם יצא\u0004 — \u0003פטור\u0004 מדברי תורה \u0003אבל אסור\u0004 מדברי סופרים. \u0003ותניא אידך\u0004 \u0005[ושנינו\u0006 בברייתא \u0005אחרת]:\u0006 \u0003לא יצא\u0004 הזב בשבת בכיסו, \u0003ואם יצא\u0004 בשוגג — \u0003חייב חטאת.\u0004","\u0003אמר רב יוסף: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 אין סתירה בין הברייתות, שכן \u0003הא\u0004 \u0005[זו,\u0006 ברייתא אחת\u0005]\u0006 שיטת \u0003ר' מאיר\u0004 היא, ואילו \u0003הא\u0004 \u0005[זו,\u0006 הברייתא האחרת\u0005]\u0006 שיטת \u0003ר' יהודה\u0004 היא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את \u0003ר' מאיר\u0004 שהוא פוטר — \u0003במידי דלאו אורחיה\u0004 \u0005[בדבר שאין\u0006 זו \u0005דרכו],\u0006 להוציא כרגיל באופן זה, ואולם \u0003במידי דהיינו אורחיה מי שמעת ליה\u0004 \u0005[בדבר שזו דרכו האם שמעת אותו]\u0006 שיפטור? שהרי כרגיל אדם מוציא מחט בידו, ופטר ר' מאיר אפילו אומן המוציא אותה בבגדו. אולם כיס זה של זב, אף על פי שאינו מחזיקו בידו, הרי מוציאים אותו תמיד באופן זה, ואף לדעת ר' מאיר הרי זו הוצאה ממש. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שפרטי מלאכה מסויימת נעשים בצורות שונות, \u0003אלא מעתה\u0004 לפי אותו רעיון \u0003הדיוט\u0004 (מי שאיננו אומן) \u0003שחקק\u0004 כלי של \u0003קב בבקעת\u0004 (חתיכת עץ), האם תאמר ש\u0003ר' מאיר הכי נמי דלא\u0004 \u0005[כך גם כן שאינו]\u0006 \u0003מחייב\u0004 בזה משום מלאכה בשבת מפני שאינו אומן ואינו עושה את הכלי כדרכו? אלא וודאי מכיון שהיא מלאכה גמורה, וההדיוט עשה אותה כמיטב יכולתו — הרי הוא חייב.","\u0003אלא אמר רב המנונא: לא קשיא\u0004 \u0005[אין זו קושיה\u0006 וסתירה\u0005],\u0006 שמדובר בשני מקרים שונים. \u0003כאן\u0004 כשאסרו וחייבו מן התורה, מדובר \u0003בזב בעל שתי ראיות,\u0004 כלומר, שראה זיבה שתי פעמים, והחיוב להביא קרבן עם הטהרה הריהו רק כאשר ראה זוב שלש פעמים. ולכן זקוק זב זה לכיס כדי לדעת אם יראה זיבה פעם שלישית. ואילו \u0003כאן\u0004 בברייתא הפוטרת מדובר \u0003בזב בעל שלש ראיות\u0004 שלגביו אין חשיבות אם יראה פעם נוספת, ועל כן הכיס איננו חשוב בעיניו ואינו מעוניין בהוצאתו.","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003זב בעל שתי ראיות\u0004 שאמרת שהוא \u0003חייב\u0004 — משום \u0003דמיבעי ליה\u0004 \u0005[שצריך אותו]\u0006 \u0003ל\u0004צורך \u0003בדיקה,\u0004 ואולם גם \u0003זב בעל שלש\u0004 ראיות הלא \u0003מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003ל\u0004שם \u0003ספירה,\u0004 שעל מנת להטהר צריך הוא לספור שבעה ימים נקיים בלא זיבה. ואם כן, גם זב שראה שלש ראיות זקוק לכיס, כדי לדעת אם ראה שוב זוב אם לא. על כך משיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 ברייתא זו \u0003אלא לבו ביום,\u0004 שראה כבר את זובו השלישי, ובאותו יום הריהו בכל אופן טמא.","ושואלים: \u0003והא מיבעי ליה\u0004 \u0005[והרי,\u0006 אף אותו זב, \u0005צריך אותו]\u0006 \u0003כדי שלא יטנפו כליו\u0004 (בגדיו) בזוב, ואף שאינו נזקק לכיס לקביעה שבהלכה, מכל מקום זקוק הוא לו למעשה! \u0003אמר ר' זירא: האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003הוא\u0004 ש\u0003אמר כל אצולי\u0004 \u0005[\u0006\u0003הצלה]\u0004 מ\u0003טינוף\u0004 (לכלוך) \u0003לא קא חשיב\u0004 \u0005[איננה חשובה]\u0006 מטרה מיוחדת לעצמה שבשלה ייחשב חפץ מסויים לכלי ממש. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכופה קערה על הכותל\u0004 בזמן שיורדים הגשמים, \u0003אם\u0004 עשה כן \u0003בשביל שתודח הקערה\u0004 במי הגשמים, \u0003הרי זה ב\"כי יותן\",\u0004 שנחשבים המים הללו כמים ששאב מרצונו, ואם נשפכו המים על פירות וזרעים הריהם מכשירים לקבל טומאה, ככתוב \"וכי \u0003יותן\u0004 מים על זרע ונפל מנבלתם עליו טמא הוא לכם\" (ויקרא יא, לח). אך \u0003אם\u0004 כפה את הקערה \u0003בשביל\u0004"],["\u0003שלא ילקה\u0004 (יתקלקל) \u0003הכותל\u0004 — \u0003אינו ב\"כי יותן\",\u0004 שאין המים נחשבים כמים שנשאבו לצורך זה. ומכאן שתנא זה אינו מחשיב את ההצלה מן הלכלוך (בכותל) כמטרה חשובה למדי, ולפי אותה שיטה לא ייחשב כיסו של הזב שנעשה להגנה מן הלכלוך ככלי חשוב! ודוחים: \u0003מי דמי\u0004 \u0005[האם זה דומה]?\u0006 \u0003התם לא קא בעי להו להני\u0004 \u0005[שם אינו צריך לאותם]\u0006 ה\u0003משקין,\u0004 מי הגשמים, \u0003כלל,\u0004 ולכן אין חושבים שהכלי נועד לקבלם. ואולם \u0003הכא קא בעי להו להאי כיס לקבולי ביה\u0004 \u0005[כאן הוא צריך לכיס זה כדי לקבל בו]\u0006 \u0003זיבה,\u0004 לבדוק אם ראה זוב. ואף שביום זה אינו זקוק לכיס, בדרך כלל זקוק הזב לכיסו לצורך הבדיקה.","אלא \u0003הא לא דמיא\u0004 \u0005[זו,\u0006 ההלכה בענין הזב, \u0005אינה דומה]\u0006 \u0003אלא לסיפא\u0004 \u0005[לסוף]\u0006 המשנה בדבר מי הגשמים. ששנינו בה: \u0003עריבה שירד דלף\u0004 הגשם \u0003לתוכה, מים הניתזין\u0004 מן העריבה או \u0003הנצפין\u0004 (העוברים על גדותיה של העריבה) אינם נחשבים למים שנשאבו לצורך, ו\u0003אינן ב\"כי יותן\". ו\u0004אילו המים \u0003שבתוכה\u0004 נחשבים כאילו נאספו לשם כך ו\u0003הרי זה ב\"כי יותן\".\u0004 הרי אף שביסודו של דבר אין הוא מעונין כלל בדלף, בכל זאת כיון שכבר ירד הדלף הריהו מעונין שהמים הנמצאים בעריבה ישארו בה ולא ילכלכו את הבית. ורצון זה דיו להחשיב את המים שבעריבה כאילו הכניסם לתוכה מרצונו. והוא הדין לגבי כיסו של הזב, שבמצב הדברים הנוכחי הוא מעונין בהחזקתו. והקושי הראשון בסתירה שבין שתי הברייתות עומד עדיין בעינו!","\u0003אלא אביי ורבא דאמרי תרוייהו לא קשיא\u0004 \u0005[שאמרו שניהם\u0006 ש\u0005אין\u0006 זה \u0005קשה],\u0006 אין סתירה בין הברייתות, אלא \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 שנאמר בה שהזב חייב מן התורה על הוצאת כיסו, הריהו לדעת \u0003ר' יהודה,\u0004 שלשיטתו אם עשה אדם מלאכה, גם אם אינו מעונין בגופה של המלאכה אלא בתוצאת לואי — חייב הוא עליה. \u0003והא\u0004 \u0005[\u0006וברייתא \u0005זו]\u0006 הפוטרת נאמרה לדעת \u0003ר' שמעון,\u0004 הסבור כי מלאכה שאין אדם צריך לעצם גופה — פטור הוא על עשייתה. ומכיוון שהזב אינו מעונין כל עיקר בזוב ובכיס — אינו מחויב מן התורה על נשיאת הכיס.","\u0003תני דבי\u0004 \u0005[נשנתה\u0006 ברייתא \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: יוצא אדם\u0004 מלכתחילה בהיותו חבוש \u0003בתפילין בערב שבת עם חשיכה,\u0004 שאף שאין מניחים תפילין בשבת ויציאה בהם יש בה משום הוצאה, אין חוששים שמא ישכח ויוציאם בשבת. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003כיון\u0004 ש\u0003אמר רבה בר רב הונא\u0004 ש\u0003חייב אדם למשמש בתפילין כל שעה ושעה\u0004 כשהם עליו, ודבר זה למדים ב\u0003קל וחמר\u0004 מן \u0003הציץ\u0004 של הכהן הגדול בדרך זו: \u0003מה ציץ שאין בו אלא אזכרה אחת\u0004 (של שם ה') \u0003אמרה\u0004 ה\u0003תורה: \"והיה על מצחו תמיד\"\u0004 (שמות כח, לח), והכוונה שתמיד צריך הכהן הגדול לזכור שהציץ מונח על ראשו, \u0003שלא יסיח דעתו ממנו,\u0004 ה\u0003תפילין שיש בהן אזכרות הרבה\u0004 של השם — \u0003על אחת כמה וכמה. הלכך מידכר דכיר להו\u0004 \u0005[על כן זוכר הוא אותן]\u0006 ואינו עשוי לשכוח בשבת שהתפילין בראשו ולטלטלן. בהקשר לכך מזכירים כי \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 שהיה \u0003חנניא אומר: חייב אדם למשמש בבגדו ערב שבת עם חשכה\u0004 כדי לבדוק אם לא שכח חפץ כלשהו בכיסיו, ועלול לבוא ולטלטלו בשבת. והעיר ו\u0003אמר רב יוסף: הלכתא רבתי\u0004 \u0005[הלכה גדולה]\u0006 היא זו \u0003לשבת,\u0004 וראוי לעשות כן כדי שלא להכשל באיסור.","שנינו במשנה ש\u0003לא יפלה את כליו,\u0004 ולא יקרא בספר לאור הנר מחשש שמא יטה. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים שאלה זו: האם כוונת הדבר היא ש\u0003לא יפלה את כליו ביום\u0004 מחשש \u0003שמא יהרוג\u0004 את הכינה שהוא מוצא בבגדו, \u0003ו\u0004משנתו \u0003כ\u0004שיטת \u0003ר' אליעזר היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' אליעזר: ההורג כינה בשבת\u0004 — \u0003כאילו הורג גמל,\u0004 ואין הבדל בחומרת האיסור. ומה שאמרו \u0003ולא יקרא לאור הנר\u0004 הרי זה מתוך חשש \u0003שמא יטה,\u0004 והוא ענין לעצמו. \u0003או דילמא תרוייהו\u0004 \u0005[שמא שניהם]\u0006 מפני הטעם \u0003שמא יטה\u0004 את הנר אליו. ושניהם נאמרו בלילה, אבל ביום מותר לפלות כליו, ואין חוששים להריגת כינה?!","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו בברייתא האומרת: \u0003אין פולין ואין קורין\u0004 בשבת בספר \u0003לאור הנר.\u0004 ומסגנון הברייתא נראה שנאסרו שני הדברים מאותו טעם. ודוחים: \u0003מי אלימא ממתניתין\u0004 \u0005[וכי חזקה היא,\u0006 ראיה זו, יותר \u0005ממשנתנו],\u0006 שאף במשנה נאמרו שני הדברים יחד, ולא הצלחנו להוכיח שיש להם טעם משותף.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו בברייתא אחרת האומרת: \u0003אין פולין לאור הנר ואין קורין לאור הנר, ואלו\u0004 (שתי הגזירות) \u0003מן ההלכות שאמרו בעליית חנניה בן חזקיה בן גרון. שמע מינה דתרוייהו\u0004 \u0005[למד ממנה שבשתיהם]\u0006 הטעם הוא מחשש \u0003שמא יטה,\u0004 שכן בשתיהם הוזכר איסור העשייה לאור הנר, והוא מחשש שמא יבוא להטותו.","\u0003אמר רב יהודה אמר שמואל:\u0004 אסור להשתמש לאורו של הנר \u0003אפילו\u0004 כדי \u0003להבחין בין בגדו לבגדי אשתו.\u0004 שכן מצריך הדבר עיון מסויים, ויש חשש שמא יטה את הנר אליו כדי להיטיב לראות. על כך \u0003אמר רבא:\u0004 יש לסייג את הדברים ולומר כי \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא\u0004 בבגדים של \u0003בני\u0004 העיר \u0003מחוזא,\u0004 שגם הגברים היו לבושים בבגדים רחבים ומקושטים, הדומים לבגדי נשים, \u0003אבל\u0004 של \u0003בני חקליתא\u0004 \u0005[החקלאים,\u0006 בני הכפר\u0005]\u0006 \u0003מידע ידעי\u0004 \u0005[יודעים הם]\u0006 את ההבדל, ואין לחשוש באלה שמא יבוא להטות את הנר להבחנה, שאצלם יש הבדל גדול בין בגדי גברים לבגדי נשים. ואף \u0003של בני מחוזא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 בבגדים של \u0003זקנות אבל\u0004 של \u0003ילדות\u0004 (צעירות) \u0003מידע ידיעי\u0004 \u0005[יודעים הם]\u0006 את ההבדל, ואין לחשוש באלה שמא יבוא להטות את הנר להבחנה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין פולין\u0004 את הבגד מכינים \u0003ברשות הרבים מפני הכבוד,\u0004 כבוד הבריות, שהעוברים ושבים נפגעים מכך. ו\u0003כיוצא בו אמר ר' יהודה, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' נחמיה: אין עושין אפיקטויזין\u0004 \u0005[סם הקאה]\u0006 \u0003ברשות הרבים מפני הכבוד.\u0004 בענין פילוי הבגד מכינים בשבת מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003המפלה את כליו מולל,\u0004 כלומר, לוחץ וממעך קצת את הכינה, \u0003וזורק\u0004 אותה, \u0003ובלבד שלא יהרוג\u0004 אותה. ואילו \u0003אבא שאול אומר: נוטל וזורק\u0004 את הכינה, \u0003ובלבד שלא ימלול\u0004 אותה, שלדעתו הריגת כינה אסורה מן התורה, ולכן אפילו למלול אסור, שמא יבוא להרוג. \u0003אמר רב הונא: הלכה\u0004 היא ש\u0003מולל\u0004 וזורק את הכינה, \u0003וזהו כבודו, ואפילו בחול.\u0004 כלומר, אף בימות החול שאין חשש איסור בהריגת כינה, אף על פי כן מוטב שלא יהרגנה, מפני המיאוס, ודיו אם זורקה בלבד (מאירי). ומסופר כי \u0003רבה מקטע להו\u0004 \u0005[היה הורג אותן],\u0006 את הכינים. \u0003ו\u0004כן \u0003רב ששת מקטע להו\u0004 \u0005[היה הורג אותן].\u0006 ואילו \u0003רבא שדי להו לקנא דמיא\u0004 \u0005[היה זורק אותן לתוך ספל מים]\u0006 ולא היה הורגן בידיים ממש. ומסופר ש\u0003אמר להו\u0004 \u0005[היה אומר להן]\u0006 \u0003רב נחמן לבנתיה\u0004 \u0005[לבנותיו]:\u0006 \u0003קטולין ואשמעינן לי קלא דסנוותי\u0004 \u0005[הרגון והשמיעו לי את קול המסרקות],\u0006 כלומר, יכולות אתן להרוג את הכינים כרגיל על גבי המסרק.","וביסודו של דבר, \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' שמעון בן אלעזר אומר\u0004 כי בדבר הריגת הכינה בשבת נחלקו בית שמאי ובית הלל, ששנינו \u0003אין הורגין את המאכולת\u0004 (כינה) \u0003בשבת,\u0004 אלו \u0003דברי בית שמאי. ובית הלל מתירין,\u0004 שלדעתם אין הכינה כשאר היצורים שחייבים על הריגתם בשבת.","\u0003וכן היה ר' שמעון בן אלעזר אומר משום רבן שמעון בן גמליאל: אין משדכין את התינוקות לארס\u0004 אותם בשבת, \u0003ולא\u0004 עושים \u0003את\u0004 ההסכמים לקחת את \u0003התינוק ללמדו\u0004 קריאת \u0003ספר\u0004 או \u0003ללמדו אומנות,\u0004 וכן \u0003אין מנחמין אבלים\u0004 בשבת, \u0003ואין מבקרין חולין בשבת,\u0004 אלו \u0003דברי בית שמאי,\u0004 שלדעתם כל אלה הם דברי חול שאין ראוי לעשותם בשבת. \u0003ובית הלל מתירין\u0004 בכל אלה, כי יש צד של מצוה בכל הדברים, ולכך לדעתם מותר לעשותם אף בשבת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנכנס לבקר את החולה\u0004 בשבת, אינו מדבר כדרך שנוהגים בחול, אלא אומר: \u0003\"שבת היא מלזעק\u0004 (ולבקש רחמים ותחנונים כביום חול), \u0003ורפואה קרובה לבוא\". ור' מאיר אומר\u0004 שראוי להוסיף: \u0003\"יכולה היא\u0004 (זכות השבת) \u0003שתרחם\".\u0004"],["\u0003ר' יהודה אומר\u0004 שראוי לומר: \u0003\"המקום\u0004 (ה') \u0003ירחם עליך ועל חולי ישראל\".\u0004 ו\u0003ר' יוסי אומר\u0004 שראוי לומר: \u0003\"המקום ירחם עליך בתוך חולי ישראל\",\u0004 שכולל את החולה הזה בכלל ישראל. \u0003שבנא איש ירושלים\u0004 כשהיה בא לבקר חולה, \u0003בכניסתו\u0004 היה \u0003אומר \"שלום\", וביציאתו\u0004 היה \u0003אומר: \"שבת היא מלזעק ורפואה קרובה לבא, ורחמיו,\u0004 של ה', \u0003מרובים, ושבתו בשלום \".\u0004 ומעירים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר ר' חנינא: מי שיש לו חולה בתוך ביתו צריך שיערבנו\u0004 בתפילתו \u0003בתוך חולי ישראל? כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 — \u0003כ\u0004שיטת \u0003ר' יוסי.\u0004","\u0003ואמר ר' חנינא: בקושי התירו לנחם אבלים ולבקר חולים בשבת.\u0004 שהמבקר והמנחם מביא עצמו לידי צער ביום השבת, ורק משום המצוה שבדבר התירו. \u0003אמר רבה בר בר חנה: כי הוה אזלינן בתריה\u0004 \u0005[כאשר הייתי הולך אחריו]\u0006 אחרי \u0003ר' אלעזר לשיולי בתפיחה\u0004 \u0005[לשאול ב\u0006שלומו של \u0005חולה],\u0006 \u0003זימנין אמר\u0004 \u0005[לפעמים היה אומר]:\u0006 \u0003\"המקום יפקדך לשלום\". וזימנין אמר ליה\u0004 \u0005[ולפעמים היה אומר לו]:\u0006 \u0003\"רחמנא ידכרינך לשלם \"\u0004\u0005[ה' יזכרך לשלום],\u0006 ואמר זאת בארמית כשלא הבין החולה עברית (רא\"מ הורוביץ). ושואלים: \u0003היכי עביד הכי\u0004 \u0005[איך עשה כך]\u0006 להתפלל בארמית? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה: לעולם אל ישאל אדם צרכיו בלשון ארמי. ו\u0004כן \u0003אמר ר' יוחנן: כל השואל צרכיו בלשון ארמי\u0004 — \u0003אין מלאכי השרת נזקקין לו\u0004 (מטפלים בו) להכניס תפלתו לפנים מן הפרגוד, \u0003שאין מלאכי השרת מכירין\u0004 (מבינים) \u0003בלשון ארמי,\u0004 אלא לשון הקודש בלבד! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 ה\u0003חולה\u0004 כיון שה\u0003שכינה עמו,\u0004 אינו נזקק למלאכים כדי להכניס תפלתו לפניו.","וכפי ש\u0003אמר רב ענן אמר רב: מנין ששכינה סועד\u0004 ומסייעת \u0003את החולה?\u0004 — \u0003שנאמר: \"ה' יסעדנו על ערש דוי\"\u0004 (תהלים מא, ד). \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003הנכנס לבקר את החולה, לא ישב לא על גבי מטה ולא על גבי כסא, אלא מתעטף\u0004 בטליתו באימה ובכבוד, \u0003ויושב לפניו,\u0004 לפני החולה ונמוך ממנו, \u0003מפני ששכינה למעלה מראשותיו של החולה. שנאמר: \"ה' יסעדנו על ערש דוי\",\u0004 וצריך לנהוג כבוד בשכינה. \u0003ו\u0004מעין זה \u0003אמר רבא\u0004 שכך \u0003אמר רבין: מנין שהקדוש ברוך הוא זן את החולה\u0004 בשעת חוליו? — \u0003שנאמר: \"ה' יסעדנו על ערש דוי\".\u0004","שנינו במשנה ש\u0003לא יקרא\u0004 אדם בספר \u0003לאור הנר\u0004 בשבת. \u0003אמר רבה:\u0004 כיון שנגזרה גזירה — אין מבחינים בה אם הנר קרוב אליו בכדי הטיה, ואותו איסור שייך \u0003אפילו\u0004 היה הנר \u0003גבוה שתי קומות\u0004 אדם, \u0003ואפילו\u0004 גבוה כ\u0003שתי מרדעות\u0004 (מוטות ארוכים המשמשים לנהוג את הבהמה), \u0003ואפילו\u0004 היה גבוה \u0003עשרה בתים זו על גב זו.\u0004 שנינו במשנה ש\"לא יקרא אדם\", ומדייקים: \u0003חד\u0004 \u0005[אחד]\u0006 \u0003הוא\u0004 ש\u0003לא ליקרי\u0004 \u0005[יקרא],\u0006 \u0003הא תרי\u0004 \u0005[הרי\u0006 אם הם \u0005שנים]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה נחשב],\u0006 אינו עושה בכך שום איסור, וזאת משום ששני אנשים יחד ודאי לא ישכחו את איסור השבת. \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שלא יקרא לאור הנר \u0003לא אחד ולא שנים! אמר ר' אלעזר: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שאפשר לחלק ולומר כי \u0003כאן\u0004 שהתירו לשניים, הרי זה כשעוסקים \u0003בענין אחד\u0004 ויזכירו זה לזה. ו\u0003כאן,\u0004 שאסרו בשניים, הרי זה כשעוסקים הם \u0003בשני ענינים.\u0004 וכיון שכל אחד מעיין במקום אחר — אינם שמים לב להזכיר זה לזה. \u0003אמר רב הונא: ובמדורה\u0004 שהכל יושבים מסביבה ולא בסמוך, \u0003אפילו\u0004 היו \u0003עשרה בני אדם\u0004 — \u0003אסור\u0004 לקרוא לאורה, שדרך היושבים מסביב למדורה שכל אחד יושב במרחק מה מחבירו, ולכך אינם רואים זה את זה וכל אחד עלול להטות אליו את האודים להאיר לו.","\u0003אמר רבא:\u0004 אף על פי שאסרו לקרוא לאור הנר גזירה שמא יטה, \u0003אם אדם חשוב הוא\u0004 — מותר. משום שאף בימות החול אין הוא נוהג להטות אליו נר שהוא מלוכלך בשמן. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בתוספתא: \u0003לא יקרא\u0004 אדם בספר בשבת \u0003לאור הנר, שמא יטה.\u0004 וסיפרו שפעם אחת \u0003אמר ר' ישמעאל בן אלישע: אני אקרא ולא אטה,\u0004 שבוודאי לא אשכח את השבת. ואולם \u0003פעם אחת קרא\u0004 בספר לאור הנר \u0003ובקש להטות\u0004 את הנר. \u0003אמר: כמה גדולים דברי חכמים שהיו אומרים\u0004 ש\u0003לא יקרא לאור הנר,\u0004 שהרי אפילו אדם שכמוני ביקש להטות. \u0003ר' נתן אומר\u0004 שלא כך היה המעשה, אלא \u0003קרא והטה\u0004 ממש \u0003וכתב\u0004 אחר כך \u0003על פנקסו: אני ישמעאל בן אלישע, קריתי והטיתי נר בשבת, לכשיבנה בית המקדש אביא חטאת שמנה\u0004 לכפרה על חטא זה. ומכאן שאפילו אדם חשוב כר' ישמעאל בן אלישע עשוי להטות את הנר! \u0003אמר ר' אבא: שאני\u0004 \u0005[שונה]\u0006 \u0003ר' ישמעאל בן אלישע, הואיל ומשים עצמו על דברי תורה כהדיוט\u0004 (כאדם פשוט) ואינו מקפיד על כבודו, אבל אדם חשוב אחר מן הסתם לא יטה. ובנושא מביאים שתי ברייתות הסותרות לכאורה זו את זו.","שכן \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]\u0006 שה\u0003שמש בודק\u0004 את ה\u0003כוסות וקערות לאור הנר\u0004 לראות אם נקיות הן. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 ש\u0003לא יבדוק!\u0004 ומסבירים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 אלא \u0003כאן\u0004 שאסרו, מדובר \u0003בשמש קבוע,\u0004 שהוא מתיירא מרבו ובודק היטב, ולכך יש לחשוש שמא יטה. ואילו \u0003כאן\u0004 שהתירו, מדובר \u0003בשמש שאינו קבוע,\u0004 שאינו מתיירא מפני הרב, ולכך אינו בודק יפה, ולכן אין לחשוש שמא יבוא להטות את הנר. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי \u0003הא והא\u0004 \u0005[זה וזה]\u0006 בשני הברייתות מדובר \u0003בשמש קבוע, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 אלא שאינן מדברות באותו סוג נר, \u0003הא\u0004 \u0005[זה]\u0006 שאסרו מדובר \u0003בדמשחא\u0004 \u0005[ב\u0006נר \u0005של שמן],\u0006 שיש לחשוש שמא יטהו, \u0003והא\u0004 \u0005[וזה]\u0006 שהתירו מדובר \u0003בדנפטא\u0004 \u0005[ב\u0006נר \u0005של נפט],\u0006 שכיון שהוא מלוכלך ודאי לא יגע בנר של נפט, בשעת בדיקת הכוסות.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לבני הישיבה שאלה זו: \u0003שמש שאינו קבוע בנר של שמן מהו\u0004 דינו, האם מותר לו לבדוק את הכוסות לאור הנר, או שמא לא? שכן מצד היותו שמש בלתי קבוע — יש להתיר, אך בגלל נר השמן יש לאסור. \u0003אמר רב: הלכה\u0004 היא שמותר \u0003ו\u0004אולם \u0003אין מורין\u0004 כן מלכתחילה ברבים, שלא להכשילם. אבל היודע הלכה זו — מותר לו לנהוג כך. ואילו \u0003ר' ירמיה בר אבא אמר : הלכה ומורין כן\u0004 אפילו לרבים. ומסופר ש\u0003ר' ירמיה בר אבא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב אסי\u0004 בשבת. \u0003קם שמעיה קא בדיק לנהורא דשרגא\u0004 \u0005[עמד שמשו\u0006 של ר' ירמיה \u0005ובדק\u0006 את הכוסות \u0005לאור הנר],\u0006 שהרי הוא לא היה שמש קבוע בבית רב אסי. \u0003אמרה ליה דביתהו\u0004 \u0005[אמרה לו אשתו]\u0006 של רב אסי לרב אסי: \u0003ומר\u0004 \u0005[והרי אדוני]\u0006 \u0003לא עביד הכי\u0004 \u0005[עושה כן],\u0006 ומדוע עושה זאת שמשו של ר' ירמיה? \u0003אמר לה: שבקיה, כרביה סבירא ליה\u0004 \u0005[עזבי אותו, כרבו סבור הוא].\u0006","שנינו במשנה כי \u0003באמת אמרו\u0004 ש\u0003החזן\u0004 יכול לראות היכן התינוקות אוחזים בקריאתם בספר ואפילו לאור הנר בשבת, אבל הוא עצמו לא יקרא. ושואלים: \u0003והאמרת רישא\u0004 \u0005[והרי אמרת בראש\u0006 המשפט\u0005]\u0006 כי החזן \u0003\"רואה\", מאי לאו לקרות\u0004 \u0005[האם\u0006 הכוונה היא \u0005לא\u0006 שרואה כדי \u0005לקרוא],\u0006 וכיצד אומרים בסוף המשפט שלא יקרא?! ומשיבים: \u0003לא\u0004 הכוונה אינה שמותר לחזן לקרוא ממש, אלא רק להסתכל ו\u0003לסדר\u0004 את \u0003ראשי פרשיותיו\u0004 שצריך הוא לקרוא מחר. \u0003וכן אמר רבה בר שמואל: אבל מסדר הוא ראשי פרשיותיו, וכולה\u0004 \u0005[ו\u0006אולם את \u0005כל]\u0006 ה\u0003פרשה\u0004 הוא \u0003לא\u0004 יכול לקרוא."],["\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בתוספתא: \u0003רבן שמעון בן גמליאל אומר: התינוקות של בית רבן היו מסדרין פרשיות וקורין\u0004 בספר \u0003לאור הנר.\u0004 והרי שמותר לקרוא לאור הנר בשבת! ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שהכוונה רק ל\u0003ראשי פרשיותיו. ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי \u0003שאני\u0004 \u0005[שונים]\u0006 ה\u0003תינוקות\u0004 לענין זה \u0003הואיל ואימת רבם עליהן\u0004 ולכן \u0003לא אתי לאצלויי\u0004 \u0005[יבואו להטות],\u0006 שאפילו ביום חול אימת רבם עליהם ולא יטפלו בנר.","שנינו במשנה: \u0003כיוצא בו\u0004 בגזירה זו של שבת גזרו ש\u0003לא יאכל הזב\u0004 עם הזבה מפני הרגל עבירה. \u0003תניא\u0004 \u0005[שנויה\u0006 תוספתא\u0005]:\u0006 היה \u0003ר' שמעון בן אלעזר אומר: בוא וראה עד היכן פרצה\u0004 (נפוצה) \u0003טהרה בישראל, ש\u0004הרי \u0003לא שנינו \"לא יאכל הטהור עם הטמאה\", אלא לא יאכל הזב עם הזבה,\u0004 אף ששניהם טמאים, \u0003מפני הרגל עבירה.\u0004 והרי שהיה מובן מאליו שטהור וטמא ודאי לא יאכלו יחד, כי הכל נשמרו בטהרה. ו\u0003כיוצא בו\u0004 אמרו: \u0003לא יאכל זב פרוש,\u0004 שכרגיל הוא מאוכלי טהרות ומן הנזהרים בהפרשת מעשרות, \u0003עם זב עם הארץ,\u0004 וזאת משום החשש \u0003שמא ירגילנו אצלו,\u0004 על ידי סעודה משותפת.","ותוהים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003מרגילו אצלו מאי הוי\u0004 \u0005[מה נהיה],\u0006 ומה פגם בדבר? \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003שמא יאכילנו דברים טמאין.\u0004 ושואלים: \u0003אטו\u0004 \u0005[וכי]\u0006 ה\u0003זב\u0004 ה\u0003פרוש לאו\u0004 \u0005[לא]\u0006 \u0003דברים טמאין אכיל\u0004 \u0005[\u0006הוא \u0005אוכל]?\u0006 שהרי בטומאתו, כל דבר שהוא נוגע בו ממילא נעשה טמא, ומה לו לחשוש מדברים טמאים? \u0003אלא אמר אביי:\u0004 איסור זה הוא משום \u0003גזירה\u0004 שגזרו \u0003שמא יאכילנו\u0004 עם הארץ זה \u0003דברים שאינן מתוקנין\u0004 (שאינם מעושרים). \u0003ורבא אמר:\u0004 לדברים שאינם מעושרים אין לחשוש, אפילו היה חבירו עם הארץ, שכן כלל הוא בידינו ש\u0003רוב עמי הארץ מעשרין הן\u0004 את פירותיהם, \u0003אלא\u0004 חששו \u0003שמא יהא רגיל אצלו\u0004 גם לאחר זמן טומאתו ויבוא \u0003ויאכילנו\u0004 לאותו פרוש \u0003דברים טמאין\u0004 אף \u0003בימי טהרתו.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לבני הישיבה שאלה אחרת בענין הרחקה מאיסור וטומאה: \u0003נדה מהו\u0004 הדין לענין \u0003שתישן עם בעלה\u0004 במיטה אחת, באופן ש\u0003היא בבגדה והוא בבגדו? אמר רב יוסף, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו במשנה: \u0003העוף\u0004 מותר שיהא \u0003עולה\u0004 יחד \u0003עם הגבינה על השלחן,\u0004 אף שאסור לאוכלו עם גבינה, אלו \u0003דברי בית שמאי. בית הלל אומר: לא עולה\u0004 העוף ביחד עם הגבינה על השלחן, \u0003ו\u0004ודאי ש\u0003לא נאכל\u0004 עמו. הרי שלשיטת בית הלל, שהיא כהלכה, לא זו בלבד שאנו מקפידים בהרחקה גופה של עבירה אלא גם שומרים שלא יהיו דברים האסורים בצירוף מצויים במקום אחד. ודוחים: \u0003שאני התם דליכא\u0004 \u0005[שונה שם שאין]\u0006 שם כמה \u0003דיעות.\u0004 כי כשמעלים את העוף עם הגבינה לשולחנו של אדם אחד, עשוי הוא לטעות ולאכול את שניהם, שכן יש שם רק דעת אחת — שלו. מה שאין כן כשנמצאים שני אנשים במיטה אחת שאז יש שתי דעות, אין לחשוש שמא ישכחו את האיסור.","ומוסיפים: \u0003הכי נמי מסתברא דהיכא דאיכא\u0004 \u0005[כך גם כן מסתבר\u0006 לומר \u0005שהיכן שיש]\u0006 שתי \u0003דיעות\u0004 ויותר \u0003שאני\u0004 \u0005[שונה].\u0006 וראיה לדבר ממה \u0003דקתני סיפא\u0004 \u0005[ששנינו בסופה]\u0006 של המשנה: \u0003רבן שמעון בן גמליאל אומר: שני אכסניים\u0004 (אורחים) הנמצאים בבית אחד \u0003אוכלין על שלחן אחד,\u0004 ואף אם \u0003זה אוכל בשר וזה אוכל גבינה, ואין חוששין.\u0004 ודוחים: אין זו ראיה, שכן \u0003ולאו אתמר עלה\u0004 \u0005[והאם לא נאמר עליה,\u0006 על הלכה זו\u0005]\u0006 ש\u0003אמר ר' חנין בר אמי אמר שמואל: לא שנו\u0004 שמותר לשניהם לאכול על שלחן אחד \u0003אלא\u0004 כ\u0003שאין מכירין זה את זה, אבל\u0004 כאשר \u0003מכירין\u0004 הם \u0003זה את זה\u0004 — \u0003אסורים.\u0004 שאנו חוששים שמתוך ההכרות שביניהם ישתתפו יחד במזונם, ויבואו לידי עבירה. \u0003ו\u0004אם כן, \u0003הני נמי\u0004 \u0005[אלה גם כן],\u0006 הבעל ואשתו \u0003מכירין\u0004 הם \u0003זה את זה נינהו\u0004 \u0005[הם],\u0006 ויש לחשוש שלא ינהגו בהרחקה הראויה ולכן לא יוכלו לישון במיטה אחת ביחד אף שהוא בבגדו והיא בבגדה. ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה מדמה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בבשר וחלב שתי \u0003דיעות איכא\u0004 \u0005[יש],\u0006 ואולם \u0003שינוי ליכא\u0004 \u0005[אין],\u0006 שהבשר והגבינה נמצאים על השלחן בלא סימן היכר המזכיר שלא לערבם. ואילו \u0003הכא איכא\u0004 \u0005[כאן ב\u0006ענין נדה \u0005יש]\u0006 גם שתי \u0003דיעות ואיכא\u0004 \u0005[ויש]\u0006 גם \u0003שינוי,\u0004 כי אין דרך בני אדם לישון בבגדיהם, וכאשר שניהם לבושים — הרי יש בכך שינוי.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שקטע אחרון זה בסגנון שונה נאמר, שמתחילה הובא כסיוע לדברי רב יוסף ונדחה, ועל כן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו, \u0003רבן שמעון בן גמליאל אומר: שני אכסניים אוכלין על שלחן אחד,\u0004 ואפילו היה אוכל \u0003זה בשר וזה גבינה. ואתמר עלה\u0004 \u0005[ושנינו עליה]\u0006 ש\u0003אמר רב חנין בר אמי אמר שמואל: לא שנו\u0004 כן \u0003אלא\u0004 כ\u0003שאין מכירין\u0004 הם \u0003זה את זה, אבל\u0004 כאשר \u0003מכירין\u0004 הם \u0003זה את זה\u0004 — \u0003אסור\u0004 להם לאכול בשלחן אחד אם זה אוכל בשר וזה גבינה. \u0003ו\u0004אם כן, \u0003הני נמי\u0004 \u0005[אלה גם כן],\u0006 הבעל ואשתו \u0003מכירין זה את זה נינהו\u0004 \u0005[הם],\u0006 ולא יוכלו לישון במיטה אחת ביחד אף שהוא בבגדו והיא בבגדה. ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 בבשר וחלב שתי \u0003דיעות איכא\u0004 \u0005[יש],\u0006 ואולם \u0003שינוי ליכא\u0004 \u0005[אין],\u0006 שהבשר והגבינה נמצאים על השלחן בלא סימן היכר המזכיר שלא לערבם. ואילו \u0003הכא איכא\u0004 \u0005[כאן ב\u0006ענין נדה \u0005יש]\u0006 גם שתי \u0003דיעות ואיכא\u0004 \u0005[ויש]\u0006 גם \u0003שינוי,\u0004 שהלא ישנים הם לבושים בבגדיהם.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון אחר לדבר ממה ששנינו במשנתנו: \u0003לא יאכל הזב עם הזבה משום\u0004 החשש ל\u0003הרגל עבירה.\u0004 והרי שאפילו אכילה משותפת נאסרה! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 שתי \u0003דיעות איכא\u0004 \u0005[יש],\u0006 ואולם \u0003שינוי ליכא\u0004 \u0005[אין].\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון אחר לדבר ממה ששנינו בברייתא: נאמר \u0003\"אל ההרים לא אכל ועיניו לא נשא אל גלולי בית ישראל ואת אשת רעהו לא טמא ואל אשה נדה לא יקרב\"\u0004 (יחזקאל יח, ו), ובפסוק זה \u0003מקיש\u0004 (משווה) \u0003אשה נדה לאשת רעהו\u0004 — \u0003מה\u0004 לגבי \u0003אשת רעהו\u0004 לשכב יחדיו ואפילו כאשר \u0003הוא בבגדו והיא בבגדה\u0004 — \u0003אסור,\u0004 אף ב\u0003אשתו נדה\u0004 גם כאשר \u0003הוא בבגדו והיא בבגדה\u0004 — \u0003אסור.\u0004","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 מסקנה זו על שיטת \u0003ר' פדת\u0004. ש\u0003אמר ר' פדת: לא אסרה\u0004 ה\u0003תורה אלא קורבה של\u0004 (שיש בה) \u0003גלוי עריות\u0004 ממש \u0003בלבד,\u0004 וכפי \u0003שנאמר: \"איש איש אל כל שאר בשרו לא תקרבו לגלות ערוה\"\u0004 (ויקרא יח, ו).","הרי שאיסור הקריבה בתורה הוא בבעילה בלבד, וכל שאר מיני התקרבות שאין בהם גלוי ערוה אינם אסורים אלא מדברי סופרים. וכאשר יש הרחקה — אף הם לא גזרו. ומסופר שכך נהג \u0003עולא, כי הוה אתי מבי רב הוה\u0004 \u0005[כאשר היה בא מבית רבו היה]\u0006 \u0003מנשק להו לאחוותיה אבי חדייהו\u0004 \u0005[להן לאחיותיו על בית חזיהן],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003אבי ידייהו\u0004 \u0005[על ידיהן].\u0006 הרי שעולא לא חשש לאיסור של מעשה חיבה בקרובה האסורה עליו כשאין כוונתו לגילוי ערוה. \u0003ו\u0004מוסיפים כי \u0003פליגא דידיה אדידיה\u0004 \u0005[חלוק,\u0006 המעשה \u0005שלו על\u0006 אימרה \u0005שלו],\u0006 ש\u0003אמר עולא: אפילו שום קורבה אסור\u0004 באשה האסורה משום ערוה, \u0003משום\u0004 הטעם שנמסר בדרך פתגם: \u0003\"לך לך אמרי נזירא סחור סחור לכרמא\u0004 \u0005[אומרים לנזיר, מסביב,\u0006 ו\u0005לכרם]\u0006 \u0003לא תקרב.\u0004 כלומר, הנזיר שאסור לו כל הבא מן הגפן, מייעצים לו שאף לא יתקרב אל הכרם, וכן הוא לגבי איסור ערוה, שלדעת עולא ראוי שיתרחק ממנו ככל האפשר.","\u0003תני דבי\u0004 \u0005[שנו בבית\u0006 מדרשו\u0005]\u0006 של \u0003אליהו\u0004 ברייתא העוסקת בפסק הלכה זה: \u0003מעשה בתלמיד\u0004 חכם \u0003אחד ששנה הרבה\u0004 במשנה, \u0003וקרא הרבה\u0004 מקרא, \u0003ושימש תלמידי חכמים\u0004 הרבה בלימוד גמרא, \u0003ו\u0004בכל זאת \u0003מת בחצי ימיו. והיתה אשתו\u0004 במרירותה \u0003נוטלת תפיליו ומחזרתם\u0004 (מסתובבת עמם) \u0003בבתי כנסיות ובבתי מדרשות, ואמרה להם\u0004 לחכמים: והרי \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בתורה \"כי הוא חייך ואורך ימיך\"\u0004 (דברים ל, כ), ואם כן \u0003בעלי ששנה\u0004 כל כך \u0003הרבה וקרא הרבה\u0004"],["\u0003ושימש תלמידי חכמים הרבה, מפני מה מת בחצי ימיו?\u0004 היכן אורך ימיו של זה? \u0003ולא היה אדם\u0004 שיהא \u0003מחזירה\u0004 על תמיהתה \u0003דבר.\u0004 ואמר אליהו: \u0003פעם אחת נתארחתי אצלה והיתה מסיחה כל אותו מאורע\u0004 על בעלה שמת. \u0003ואמרתי לה: בתי בימי נדותך מה הוא אצלך?\u0004 כיצד היה נוהג? \u0003אמרה לי: חס ושלום, אפילו באצבע קטנה לא נגע בי.\u0004 ושאלתי אותה: \u0003בימי לבוניך,\u0004 באותם הימים שפסקת מלראות דם נידה, ורק ספרת ימים נקיים, \u0003מהו אצלך\u0004 מה היה אז יחסו אליך? אמרה לי: \u0003אכל עמי ושתה עמי וישן עמי בקירוב בשר ו\u0004אולם \u0003לא עלתה\u0004 על \u0003דעתו על דבר אחר\u0004 (זיווג). \u0003ואמרתי לה: ברוך המקום שהרגו\u0004 על חטא זה, \u0003ש\u0004כן בעלך \u0003לא נשא פנים\u0004 (התחשב) \u0003לתורה. שהרי אמרה\u0004 ה\u0003תורה: \"ואל אשה בנדת טומאתה לא תקרב\"\u0004 (ויקרא יח, יט), הרי שאסורה אפילו קירבה בלבד. ומסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר:\u0004 אותו תלמיד חכם לא בקירוב בשר ממש ישן עמה, אלא רק \u0003מטה חדא הואי\u0004 \u0005[מיטה אחת היתה]\u0006 שישנו בה, ולא בקירוב. \u0003במערבא אמרי\u0004 \u0005[במערב,\u0006 בארץ ישראל \u0005היו אומרים]\u0006 ש\u0003אמר רב יצחק בר יוסף\u0004 שאותו תלמיד חכם \u0003סינר\u0004 היה \u0003מפסיק בינו לבינה,\u0004 שהיתה לבושה בו, ובכל זאת, כיון שאסור הדבר נענש אותו תלמיד חכם.","\u0003ואלו מן ההלכות שאמרו בעליית חנניה בן חזקיה בן גרון.\u0004 ויבואר בגמרא מה הן בדיוק הלכות אלו, ואותן הלכות נחשבות לחטיבה אחת משום שיש בהן צד יחוד, \u0003שעלו\u0004 חכמים לעלייתו של חנניה בן חזקיה בן גרון \u0003לבקרו,\u0004 ומאחר שהיו שם חכמים מרובים, שכללו את רוב חכמי התורה בארץ ישראל, עסקו בהלכות שונות שבתורה, והתברר כי כאשר \u0003נמנו\u0004 בעלי הדעות, אז אירע ש\u0003רבו בית שמאי על בית הלל, ושמונה עשר דברים גזרו בו ביום\u0004 כדעת בית שמאי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף:\u0004 האם לשון \u0003\"אלו \" תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003או\u0004 לשון \u0003\"ואלו \" תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]?\u0006 וההסבר לחשיבות ההבדל: אם נאמר כי לשון \u0003\"ואלו \" תנן\u0004 \u0005[שנינו],\u0006 והרי תהיה הכוונה \u0003הני דאמרן\u0004 \u0005[אותן שאמרנו]\u0006 קודם, שאותן הלכות נכללות בתוך הגזירות. \u0003או\u0004 לשון \u0003\"אלו \" תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 והכוונה היא על אלה \u0003דבעינן למימר קמן\u0004 \u0005[שאנו רוצים לומר הלאה]?\u0006 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו בברייתא את הדברים יחד: \u0003אין פולין לאור הנר ואין קורין לאור הנר, ואלו מן ההלכות שאמרו בעליית חנניה בן חזקיה בן גרון. שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי לשון \u0003\"ואלו \" תנן\u0004 \u0005[שנינו],\u0006 וכוונתה לדברים שנאמרו קודם, \u0003שמע מינה\u0004.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא ביחס למגילת תענית שהיא רשימת ימי אבל שנקבעו כזכרון של צרות שאירעו בהם לישראל, או של ימי גאולה שנקבעו שמחה לדורות: \u0003מי כתב\u0004 את \u0003מגילת תענית?\u0004 — מגילה זו נכתבה על ידי \u0003חנניה בן חזקיה\u0004 (בן גרון) \u0003וסיעתו שהיו מחבבין את\u0004 זכרון \u0003הצרות\u0004 והצלת ישראל מהן.","\u0003אמר רבן שמעון בן גמליאל: אף אנו מחבבין את\u0004 זכרון \u0003הצרות\u0004 שנצלו מהם, \u0003אבל מה נעשה שאם באנו לכתוב\u0004 את כל הימים מסוג זה \u0003אין אנו מספיקין,\u0004 שהרי מרובות הן הצרות שהיו לישראל בכל דור ותקופה, ובכל יום יש מאורע הראוי לזכרון.","\u0003דבר\u0004 (טעם) \u0003אחר:\u0004 מפני מה אין כותבים? — לפי שכמו ש\u0003אין שוטה נפגע,\u0004 שאינו מכיר בפגעים הבאים עליו, אף אנו איננו יכולים להבין את גודל הצרה העוברת עלינו.","\u0003דבר אחר: אין בשר המת מרגיש באיזמל\u0004 החותך בו, וכמו כן אנו במצב קשה כל כך ששוב איננו חשים בכאבים ובצרות. על הדימוי האחרון שואלים: \u0003איני\u0004 \u0005[וכן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יצחק: קשה\u0004 ה\u0003רימה\u0004 האוכלת את ה\u0003מת\u0004 ומכאיבה לו \u0003כ\u0004דקירת \u0003מחט בבשר\u0004 האדם \u0003החי,\u0004 וכפי \u0003שנאמר\u0004 על המת: \u0003\"אך בשרו עליו יכאב ונפשו עליו תאבל\"\u0004 (איוב יד, כט)! אלא \u0003אימא\u0004 \u0005[אמור]\u0006 ופרש את הדבר: \u0003אין בשר המת,\u0004 כלומר, אותו בשר שנמצא במקומות שאינם רגישים לכאב, \u0003שבחי מרגיש באיזמל\u0004 החותך אותו.","ועוד סיפרו על חנניה בן חזקיה, ש\u0003אמר רב יהודה אמר רב: ברם זכור אותו האיש לטוב וחנניה בן חזקיה שמו, שאלמלא הוא נגנז ספר יחזקאל. ש\u0004כן \u0003היו דבריו\u0004 של ספר יחזקאל בפרטים רבים \u0003סותרין\u0004 את \u0003דברי\u0004 ה\u0003תורה\u0004 ולפיכך רצו לגנוז את הספר ולא לכלול אותו בכתבי הקודש. \u0003מה עשה\u0004 חנניה בן חזקיה? — \u0003העלו לו שלש מאות גרבי\u0004 (כדי) \u0003שמן\u0004 למאור ולאכילה לעליית הגג שלו, \u0003וישב בעלייה ודרשן\u0004 לאותם כתובים בספר יחזקאל עד שנתיישבו הסתירות.","שנינו במשנה שכאשר עלו החכמים לעליית בית חנניה בן חזקיה בן גרון, נמנו \u0003ושמונה עשר דבר גזרו\u0004 כשיטת בית שמאי. ושואלים: \u0003מאי נינהו\u0004 \u0005[מה הם]\u0006 אותם \u0003שמנה עשר דבר?\u0004 ומשיבים: \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 רשימת גזירות שגזרו חכמים על דברים שיהיו \u0003פוסלים את התרומה,\u0004 כלומר, שהם טמאים בדרגה כזו שאם יגעו בתרומה — יפסלו אותה, ומשמעות הדבר שהיא עצמה תהיה טמאה, אך לא תטמא עוד אחרים. ואלו הם: אדם \u0003האוכל אוכל\u0004 שהוא \u0003ראשון\u0004 לטומאה (שנגע אותו אוכל בדבר המטמא מן התורה, כגון שרץ), \u0003ו\u0004כן \u0003האוכל אוכל שני\u0004 (שנטמא האוכל מדבר שהוא ראשון לטומאה), \u0003ו\u0004כן \u0003השותה משקין טמאין\u0004 בכל דרגה של טומאה, \u0003ו\u0004כן \u0003הבא\u0004 (הנכנס) \u0003ראשו ורובו במים שאובין\u0004 לאחר שטבל במקוה לטהרתו, \u0003ו\u0004כן אדם \u0003טהור שנפלו על ראשו ורובו שלשה לוגין\u0004 של \u0003מים שאובין, ו\u0004כן פוסלים את התרומה \u0003ספר\u0004 תורה, \u0003והידים\u0004 של כל אדם שלא נטהר לשם טהרת תרומה, ונגע בה, \u0003והטבול יום,\u0004 שהוא מי שנטמא וטבל, ועדיין לא הגיע הערב, ואיננו נחשב כטהור לחלוטין, וכן \u0003האוכלים והכלים שנטמאו במשקין\u0004 טמאים. את הדברים הללו מבררים לגופם.","ושואלים תחילה: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כי \u0003האוכל אוכל ראשון והאוכל אוכל שני, מפסל פסלי טמויי\u0004 \u0005[לפסול\u0006 הם \u0005פוסלים\u0006 את התרומה, אבל \u0005לטמא]\u0006"]]};
